local G=SoloProgressGuide
-- Editorial paraphrases; source manifest: research/solo-progress/quest-comment-sources.json
G.questHelp={}
-- Zul'Gurub: quest descriptions and NPC coordinates from local Questie Classic;
-- availability at stage 3 is the Solo Progress rule in full-guide.txt.
G.questHelp[3520]={steps={"Возьмите задание и посох у Йе’киньи в Порту Картеля, Танарис (67, 22).","В Фераласе убейте трёх дольных крикунов. Используйте посох на каждом трупе и поговорите с появившимся духом; одного убийства недостаточно.","Верните посох и собранные сущности Йе’кинье."}}
G.questHelp[3527]={steps={"У Йе’киньи возьмите продолжение и отправляйтесь в Зул’Фаррак.","Добудьте первую табличку Мошару у Теки Мученика, вторую — у гидроманта Велраты. Верните обе таблички Йе’кинье в Порт Картеля."}}
G.questHelp[4787]={steps={"Возьмите задание у Йе’киньи в Танарисе.","Добудьте Древнее яйцо в пещере за амфитеатром на вершине Джинта’Алора во Внутренних землях и верните его Йе’кинье."}}
G.questHelp[3528]={steps={"Получите яйцо Хаккара у Йе’киньи и отнесите его в святилище Падшего Бога в Храме Атал’Хаккара, Болото Печали.","Используйте яйцо для начала события. Убивайте прислужников и используйте кровь Хаккари, чтобы погасить огни. Победите появившуюся аватару Хаккара и заполните яйцо.","Сдайте заполненное яйцо Йе’кинье. На Solo Progress этапов 0–2 цепочка здесь прерывается; продолжение открывается с начала этапа 3."}}
G.questHelp[5065]={steps={"С этапа 3 после «Бога Хаккара» возьмите продолжение у геолога Железного Башмака в Порту Картеля, Танарис (67, 24).","Найдите третью и четвёртую таблички Мошару у троллей племени Моходеров в Восточных Чумных землях. Верните обе геологу."}}
G.questHelp[4788]={steps={"У геолога Железного Башмака возьмите следующее задание.","Найдите пятую и шестую таблички Мошару у троллей Тлеющего Терновника в нижней части Пика Чёрной горы. Верните обе таблички геологу в Танарис."}}
G.questHelp[8181]={steps={"После сдачи последних табличек возьмите задание у геолога Железного Башмака (67, 24).","Поговорите с Йе’киньей неподалёку в Порту Картеля (67, 22) и завершите задание."}}
G.questHelp[8182]={steps={"Вернитесь к геологу Железному Башмаку и возьмите «Длань Растахана».","Поговорите с Молтором на острове Йоджамба у северо-западного побережья Тернистой долины (15, 15) и сдайте задание.","По правилам Solo Progress завершение этой цепочки открывает вход в Зул’Гуруб. Рейд необязателен для перехода к следующему этапу."}}
do
 local yeh={name="Йе’кинья",zone="Танарис",zoneEN="Tanaris",x=66.99,y=22.36,kind="npc",entityID=8579}
 local ironboot={name="Геолог Железный Башмак",zone="Танарис",zoneEN="Tanaris",x=66.89,y=24.03,kind="npc",entityID=10460}
 for _,id in ipairs({3520,3527,4787,3528,5065,4788,8181,8182}) do
  G.questHelp[id].url="https://www.wowhead.com/classic/ru/quest="..id
  G.questHelp[id].startTargets={(id==3520 or id==3527 or id==4787 or id==3528) and yeh or ironboot}
 end
end
G.questHelp[4182]={["steps"]={"У Хелендиса Речного Мыса в Дозоре Моргана возьмите начало допуска к Ониксии.","Убейте указанные в журнале виды драконов в Пылающих степях и вернитесь к нему. Если взято задание на сущности дракончиков, выполняйте их одновременно."},["refs"]={{[1]="Начало: Хелендис Речной Мыс",[2]="https://www.wowhead.com/classic/ru/npc=9562",["targets"]={{["name"]="Хелендис Речной Мыс",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=85.82,["y"]=68.95,["kind"]="npc",["entityID"]=9562}},["kind"]="npc",["entityID"]=9562},{[1]="Цель: Детеныш черного дракона",[2]="https://www.wowhead.com/classic/ru/npc=7047",["targets"]={{["name"]="Детеныш черного дракона",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=86.92,["y"]=30.55,["kind"]="npc",["entityID"]=7047},{["name"]="Детеныш черного дракона",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=84.87,["y"]=31.86,["kind"]="npc",["entityID"]=7047},{["name"]="Детеныш черного дракона",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=91.86,["y"]=38.48,["kind"]="npc",["entityID"]=7047},{["name"]="Детеныш черного дракона",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=81.01,["y"]=28.2,["kind"]="npc",["entityID"]=7047}},["kind"]="npc",["entityID"]=7047},{[1]="Цель: Черный драконид",[2]="https://www.wowhead.com/classic/ru/npc=7040",["targets"]={{["name"]="Черный драконид",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=85.41,["y"]=27.2,["kind"]="npc",["entityID"]=7040},{["name"]="Черный драконид",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=83.57,["y"]=28.6,["kind"]="npc",["entityID"]=7040},{["name"]="Черный драконид",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=56.96,["y"]=61.45,["kind"]="npc",["entityID"]=7040},{["name"]="Черный драконид",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=87.21,["y"]=39.79,["kind"]="npc",["entityID"]=7040}},["kind"]="npc",["entityID"]=7040},{[1]="Цель: Черный дракон",[2]