G.questHelp[4183]={["steps"]={"Отнесите письмо мировому судье Соломону в Приозерье, Красногорье.","После сдачи возьмите следующий этап «Подлинных хозяев»: одинаковое название не означает одно и то же задание."},["refs"]={{[1]="Начало: Хелендис Речной Мыс",[2]="https://www.wowhead.com/classic/ru/npc=9562",["targets"]={{["name"]="Хелендис Речной Мыс",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=85.82,["y"]=68.95,["kind"]="npc",["entityID"]=9562}},["kind"]="npc",["entityID"]=9562},{[1]="Сдача: Мировой судья Соломон",[2]="https://www.wowhead.com/classic/ru/npc=344",["targets"]={{["name"]="Мировой судья Соломон",["zone"]="Красногорье",["zoneEN"]="Redridge Mountains",["x"]=29.99,["y"]=44.45,["kind"]="npc",["entityID"]=344}},["kind"]="npc",["entityID"]=344},{[1]="Выданный предмет: Письмо Хелендиса Речного Мыса",[2]="https://www.wowhead.com/classic/ru/item=11366",["targets"]={},["kind"]="item",["entityID"]=11366}},["url"]="https://www.wowhead.com/classic/quest=4183#comments",["startTargets"]={{["name"]="Хелендис Речной Мыс",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=85.82,["y"]=68.95,["kind"]="npc",["entityID"]=9562}}}
G.questHelp[4184]={["steps"]={"Отправляйтесь к Болвару Фордрагону в крепость Штормграда и передайте письмо.","Он находится в центральном зале крепости; продолжение ведёт к разговору с леди Престор."},["refs"]={{[1]="Начало: Мировой судья Соломон",[2]="https://www.wowhead.com/classic/ru/npc=344",["targets"]={{["name"]="Мировой судья Соломон",["zone"]="Красногорье",["zoneEN"]="Redridge Mountains",["x"]=29.99,["y"]=44.45,["kind"]="npc",["entityID"]=344}},["kind"]="npc",["entityID"]=344},{[1]="Сдача: Верховный лорд Болвар Фордрагон",[2]="https://www.wowhead.com/classic/ru/npc=1748",["targets"]={{["name"]="Верховный лорд Болвар Фордрагон",["zone"]="Штормград",["zoneEN"]="Stormwind City",["x"]=78.23,["y"]=17.98,["kind"]="npc",["entityID"]=1748}},["kind"]="npc",["entityID"]=1748},{[1]="Выданный предмет: Обращение Соломона к королю Ринну",[2]="https://www.wowhead.com/classic/ru/item=11367",["targets"]={},["kind"]="item",["entityID"]=11367}},["url"]="https://www.wowhead.com/classic/quest=4184#comments",["startTargets"]={{["name"]="Мировой судья Соломон",["zone"]="Красногорье",["zoneEN"]="Redridge Mountains",["x"]=29.99,["y"]=44.45,["kind"]="npc",["entityID"]=344}}}
G.questHelp[4185]={["steps"]={"Поговорите с леди Катраной Престор рядом с Болваром и пройдите все реплики, затем снова обратитесь к Болвару.","Над Престор может не быть вопросительного знака. Если идёт чужой «Великий Маскарад», дождитесь окончания события и её возвращения."},["refs"]={{[1]="Начало: Верховный лорд Болвар Фордрагон",[2]="https://www.wowhead.com/classic/ru/npc=1748",["targets"]={{["name"]="Верховный лорд Болвар Фордрагон",["zone"]="Штормград",["zoneEN"]="Stormwind City",["x"]=78.23,["y"]=17.98,["kind"]="npc",["entityID"]=1748}},["kind"]="npc",["entityID"]=1748}},["url"]="https://www.wowhead.com/classic/quest=4185#comments",["startTargets"]={{["name"]="Верховный лорд Болвар Фордрагон",["zone"]="Штормград",["zoneEN"]="Stormwind City",["x"]=78.23,["y"]=17.98,["kind"]="npc",["entityID"]=1748}}}
G.questHelp[4186]={["steps"]={"Вернитесь из Штормграда к мировому судье Соломону в Приозерье.","Сдайте этот этап и возьмите поручение для Дозора Моргана."},["refs"]={{[1]="Начало: Верховный лорд Болвар Фордрагон",[2]="https://www.wowhead.com/classic/ru/npc=1748",["targets"]={{["name"]="Верховный лорд Болвар Фордрагон",["zone"]="Штормград",["zoneEN"]="Stormwind City",["x"]=78.23,["y"]=17.98,["kind"]="npc",["entityID"]=1748}},["kind"]="npc",["entityID"]=1748},{[1]="Сдача: Мировой судья Соломон",[2]="https://www.wowhead.com/classic/ru/npc=344",["targets"]={{["name"]="Мировой судья Соломон",["zone"]="Красногорье",["zoneEN"]="Redridge Mountains",["x"]=29.99,["y"]=44.45,["kind"]="npc",["entityID"]=344}},["kind"]="npc",["entityID"]=344},{[1]="Выданный предмет: Указ Ринна",[2]="https://www.wowhead.com/classic/ru/item=11368",["targets"]={},["kind"]="item",["entityID"]=11368}},["url"]="https://www.wowhead.com/classic/quest=4186#comments",["startTargets"]={{["name"]="Верховный лорд Болвар Фордрагон",["zone"]="Штормград",["zoneEN"]="Stormwind City",["x"]=78.23,["y"]=17.98,["kind"]="npc",["entityID"]=1748}}}
G.questHelp[4223]={["steps"]={"Из Приозерья отправляйтесь к маршалу Максвеллу в Дозор Моргана, Пылающие степи.","Следующее поручение потребует сведений от Джона Оборванца."},["refs"]={{[1]="Начало: Мировой судья Соломон",[2]="https://www.wowhead.com/classic/ru/npc=344",["targets"]={{["name"]="Мировой судья Соломон",["zone"]="Красногорье",["zoneEN"]="Redridge Mountains",["x"]=29.99,["y"]=44.45,["kind"]="npc",["entityID"]=344}},["kind"]="npc",["entityID"]=344},{[1]="Сдача: Маршал Максвелл",[2]="https://www.wowhead.com/classic/ru/npc=9560",["targets"]={{["name"]="Маршал Максвелл",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=84.74,["y"]=69.02,["kind"]="npc",["entityID"]=9560}},["kind"]="npc",["entityID"]=9560}},["url"]="https://www.wowhead.com/classic/quest=4223#comments",["startTargets"]={{["name"]="Мировой судья Соломон",["zone"]="Красногорье",["zoneEN"]="Redridge Mountains",["x"]=29.99,["y"]=44.45,["kind"]="npc",["entityID"]=344}}}
G.questHelp[4224]={["steps"]={"Найдите Джона Оборванца у Пламенеющего Стяга на севере Пылающих степей, примерно 65, 24: он снаружи у котла и палатки.","Поговорите с ним даже без вопросительного знака и вернитесь к маршалу Максвеллу."},["refs"]={{[1]="Начало: Маршал Максвелл",[2]="https://www.wowhead.com/classic/ru/npc=9560",["targets"]={{["name"]="Маршал Максвелл",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=84.74,["y"]=69.02,["kind"]="npc",["entityID"]=9560}},["kind"]="npc",["entityID"]=9560}},["url"]="https://www.wowhead.com/classic/quest=4224#comments",["startTargets"]={{["name"]="Маршал Максвелл",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=84.74,["y"]=69.02,["kind"]="npc",["entityID"]=9560}}}
G.questHelp[4241]={["steps"]={"Войдите в Глубины Чёрной горы и ищите тюрьму справа от входной области.","Маршал Винздор находится в камере. По пути следите за патрулями с собаками; доберитесь до него и поговорите."},["refs"]={{[1]="Начало: Маршал Максвелл",[2]="https://www.wowhead.com/classic/ru/npc=9560",["targets"]={{["name"]="Маршал Максвелл",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=84.74,["y"]=69.02,["kind"]="npc",["entityID"]=9560}},["kind"]="npc",["entityID"]=9560},{[1]="Сдача: Маршал Винздор",[2]="https://www.wowhead.com/classic/ru/npc=9023",["targets"]={{["name"]="Подход к подземелью: Маршал Винздор находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9023},{["name"]="Подход к подземелью: Маршал Винздор находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9023}},["kind"]="npc",["entityID"]=9023}},["url"]="https://www.wowhead.com/classic/quest=4241#comments",["startTargets"]={{["name"]="Маршал Максвелл",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=84.74,["y"]=69.02,["kind"]="npc",["entityID"]=9560}}}
G.questHelp[4242]={["steps"]={"Вернитесь к маршалу Максвеллу и сдайте сведения Винздора.","Отсутствие нового задания у Максвелла нормально: продолжение начинается с Измятой записки, которая после этой сдачи выпадает с противников в Глубинах Чёрной горы."},["refs"]={{[1]="Начало: Маршал Винздор",[2]="https://www.wowhead.com/classic/ru/npc=9023",["targets"]={{["name"]="Подход к подземелью: Маршал Винздор находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9023},{["name"]="Подход к подземелью: Маршал Винздор находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9023}},["kind"]="npc",["entityID"]=9023},{[1]="Сдача: Маршал Максвелл",[2]="https://www.wowhead.com/classic/ru/npc=9560",["targets"]={{["name"]="Маршал Максвелл",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=84.74,["y"]=69.02,["kind"]="npc",["entityID"]=9560}},["kind"]="npc",["entityID"]=9560}},["url"]="https://www.wowhead.com/classic/quest=4242#comments",["startTargets"]={{["name"]="Подход к подземелью: Маршал Винздор находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9023},{["name"]="Подход к подземелью: Маршал Винздор находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9023}}}
G.questHelp[4264]={["steps"]={"После сдачи «Утраченной надежды» убивайте противников в Глубинах Чёрной горы до получения Измятой записки.","Используйте записку и отнесите её Винздору в тюрьму внутри подземелья, а не Максвеллу в Дозор Моргана."},["refs"]={{[1]="Начало: Измятая записка",[2]="https://www.wowhead.com/classic/ru/item=11446",["targets"]={{["name"]="Подход к подземелью: Друг Риббли находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=10043},{["name"]="Подход к подземелью: Друг Риббли находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=10043}},["kind"]="item",["entityID"]=11446},{[1]="Сдача: Маршал Винздор",[2]="https://www.wowhead.com/classic/ru/npc=9023",["targets"]={{["name"]="Подход к подземелью: Маршал Винздор находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9023},{["name"]="Подход к подземелью: Маршал Винздор находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9023}},["kind"]="npc",["entityID"]=9023}},["url"]="https://www.wowhead.com/classic/quest=4264#comments",["startTargets"]={{["name"]="Подход к подземелью: Друг Риббли находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=10043},{["name"]="Подход к подземелью: Друг Риббли находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=10043}}}
G.questHelp[4282]={["steps"]={"Добудьте сведения с повелителя големов Аргелмаха и генерала Кузни Гнева в Глубинах Чёрной горы.","Вернитесь к Винздору. Не принимайте следующее «Побег!», пока группа не готова: принятие запускает сопровождение."},["refs"]={{[1]="Начало: Маршал Винздор",[2]="https://www.wowhead.com/classic/ru/npc=9023",["targets"]={{["name"]="Подход к подземелью: Маршал Винздор находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9023},{["name"]="Подход к подземелью: Маршал Винздор находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9023}},["kind"]="npc",["entityID"]=9023},{[1]="Цель: Утерянная информация маршала Виндзора",[2]="https://www.wowhead.com/classic/ru/item=11464",["targets"]={{["name"]="Подход к подземелью: Генерал Кузня Гнева находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9033},{["name"]="Подход к подземелью: Генерал Кузня Гнева находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9033}},["kind"]="item",["entityID"]=11464},{[1]="Источник добычи: Генерал Кузня Гнева",[2]="https://www.wowhead.com/classic/ru/npc=9033",["targets"]={{["name"]="Подход к подземелью: Генерал Кузня Гнева находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9033},{["name"]="Подход к подземелью: Генерал Кузня Гнева находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9033}},["kind"]="npc",["entityID"]=9033},{[1]="Цель: Утерянная информация маршала Виндзора",[2]="https://www.wowhead.com/classic/ru/item=11465",["targets"]={{["name"]="Подход к подземелью: Повелитель големов Аргелмах находится внутри",["zone"]="Тлеющее ущелье",["z