G.questHelp[4322]={["steps"]={"До принятия задания расчистите тюремные коридоры и путь сопровождения, включая боковые комнаты.","Примите «Побег!» и сопровождайте Винздора, защищая его на всех остановках.","В конце обязательно поговорите с ним и завершите задание до выхода из подземелья."},["refs"]={{[1]="Начало: Маршал Винздор",[2]="https://www.wowhead.com/classic/ru/npc=9023",["targets"]={{["name"]="Подход к подземелью: Маршал Винздор находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9023},{["name"]="Подход к подземелью: Маршал Винздор находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9023}},["kind"]="npc",["entityID"]=9023},{[1]="Сдача: Маршал Максвелл",[2]="https://www.wowhead.com/classic/ru/npc=9560",["targets"]={{["name"]="Маршал Максвелл",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=84.74,["y"]=69.02,["kind"]="npc",["entityID"]=9560}},["kind"]="npc",["entityID"]=9560}},["url"]="https://www.wowhead.com/classic/quest=4322#comments",["startTargets"]={{["name"]="Подход к подземелью: Маршал Винздор находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9023},{["name"]="Подход к подземелью: Маршал Винздор находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9023}}}
G.questHelp[4903]={["steps"]={"В Каргате полностью пройдите диалог с полководцем Горчуком и используйте полученные распоряжения, чтобы взять задание.","В Нижней части Пика Чёрной горы победите трёх указанных командиров. Неприметные документы появляются возле одного из них; проверьте все три места."},["refs"]={{[1]="Начало: Полководец Клинозуб",[2]="https://www.wowhead.com/classic/ru/npc=9077",["targets"]={{["name"]="Полководец Клинозуб (место поиска)",["zone"]="Бесплодные земли",["zoneEN"]="Badlands",["x"]=5.81,["y"]=47.52,["kind"]="npc",["entityID"]=9077}},["kind"]="npc",["entityID"]=9077},{[1]="Начало: Приказ полководца Клинозуба",[2]="https://www.wowhead.com/classic/ru/item=12563",["targets"]={{["name"]="Полководец Клинозуб (место поиска)",["zone"]="Бесплодные земли",["zoneEN"]="Badlands",["x"]=5.81,["y"]=47.52,["kind"]="npc",["entityID"]=9077}},["kind"]="item",["entityID"]=12563},{[1]="Цель: Властитель Змейталак",[2]="https://www.wowhead.com/classic/ru/npc=9568",["targets"]={{["name"]="Подход к подземелью: Властитель Змейталак находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9568},{["name"]="Подход к подземелью: Властитель Змейталак находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9568}},["kind"]="npc",["entityID"]=9568},{[1]="Цель: Вождь Омокк",[2]="https://www.wowhead.com/classic/ru/npc=9196",["targets"]={{["name"]="Подход к подземелью: Вождь Омокк находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9196},{["name"]="Подход к подземелью: Вождь Омокк находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9196}},["kind"]="npc",["entityID"]=9196},{[1]="Цель: Воевода Вун",[2]="https://www.wowhead.com/classic/ru/npc=9237",["targets"]={{["name"]="Подход к подземелью: Во