,["entityID"]=9077}}}
G.questHelp[4941]={["steps"]={"Поговорите с Эйтриггом в зале Тралла в Оргриммаре. Отсутствие значка над головой не мешает разговору.","Пройдите диалог до конца и доложите Траллу."},["refs"]={{[1]="Начало: Полководец Клинозуб",[2]="https://www.wowhead.com/classic/ru/npc=9077",["targets"]={{["name"]="Полководец Клинозуб (место поиска)",["zone"]="Бесплодные земли",["zoneEN"]="Badlands",["x"]=5.81,["y"]=47.52,["kind"]="npc",["entityID"]=9077}},["kind"]="npc",["entityID"]=9077},{[1]="Сдача: Тралл",[2]="https://www.wowhead.com/classic/ru/npc=4949",["targets"]={{["name"]="Тралл",["zone"]="Оргриммар",["zoneEN"]="Orgrimmar",["x"]=31.73,["y"]=37.82,["kind"]="npc",["entityID"]=4949}},["kind"]="npc",["entityID"]=4949}},["url"]="https://www.wowhead.com/classic/quest=4941#comments",["startTargets"]={{["name"]="Полководец Клинозуб (место поиска)",["zone"]="Бесплодные земли",["zoneEN"]="Badlands",["x"]=5.81,["y"]=47.52,["kind"]="npc",["entityID"]=9077}}}
G.questHelp[4974]={["steps"]={"Пройдите Верхнюю часть Пика Чёрной горы и победите Ренда Чернорука.","Заберите его голову и вернитесь к Траллу. После сдачи продолжайте допуск к Ониксии разговором о дальнейших событиях."},["refs"]={{[1]="Начало: Тралл",[2]="https://www.wowhead.com/classic/ru/npc=4949",["targets"]={{["name"]="Тралл",["zone"]="Оргриммар",["zoneEN"]="Orgrimmar",["x"]=31.73,["y"]=37.82,["kind"]="npc",["entityID"]=4949}},["kind"]="npc",["entityID"]=4949},{[1]="Цель: Голова Ренда Чернорука",[2]="https://www.wowhead.com/classic/ru/item=12630",["targets"]={},["kind"]="item",["entityID"]=12630},{[1]="Источник добычи: Вождь Ренд Чернорук",[2]="https://www.wowhead.com/classic/ru/npc=10429",["targets"]={},["kind"]="npc",["entityID"]=10429}},["url"]="https://www.wowhead.com/classic/quest=4974#comments",["startTargets"]={{["name"]="Тралл",["zone"]="Оргриммар",["zoneEN"]="Orgrimmar",["x"]=31.73,["y"]=37.82,["kind"]="npc",["entityID"]=4949}}}
G.questHelp[6402]={["steps"]={"У ворот Штормграда поговорите с оруженосцем Роу, чтобы вызвать Винздора.","Если он занят сопровождением другого игрока, дождитесь окончания того события. Затем поговорите с прибывшим Виндзором."},["refs"]={{[1]="Начало: Маршал Максвелл",[2]="https://www.wowhead.com/classic/ru/npc=9560",["targets"]={{["name"]="Маршал Максвелл",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=84.74,["y"]=69.02,["kind"]="npc",["entityID"]=9560}},["kind"]="npc",["entityID"]=9560},{[1]="Сдача: Реджинальд Винздор",[2]="https://www.wowhead.com/classic/ru/npc=12580",["targets"]={{["name"]="Реджинальд Винздор",["zone"]="Штормград",["zoneEN"]="Stormwind City",["x"]=69.56,["y"]=85.9,["kind"]="npc",["entityID"]=12580}},["kind"]="npc",["entityID"]=12580}},["url"]="https://www.wowhead.com/classic/quest=6402#comments",["startTargets"]={{["name"]="Маршал Максвелл",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=84.74,["y"]=69.02,["kind"]="npc",["entityID"]=9560}}}
G.questHelp[6403]={["steps"]={"Сопроводите Виндзора в крепость Штормграда и дождитесь разоблачения Престор.","Во время боя держитесь в стороне: Болвар способен разобраться с драконами. После окончания события поговорите с ним для продолжения."},["refs"]={{[1]="Начало: Реджинальд Винздор",[2]="https://www.wowhead.com/classic/ru/npc=12580",["targets"]={{["name"]="Реджинальд Винздор",["zone"]="Штормград",["zoneEN"]="Stormwind City",["x"]=69.56,["y"]=85.9,["kind"]="npc",["entityID"]=12580}},["kind"]="npc",["entityID"]=12580},{[1]="Сдача: Верховный лорд Болвар Фордрагон",[2]="https://www.wowhead.com/classic/ru/npc=1748",["targets"]={{["name"]="Верховный лорд Болвар Фордрагон",["zone"]="Штормград",["zoneEN"]="Stormwind City",["x"]=78.23,["y"]=17.98,["kind"]="npc",["entityID"]=1748}},["kind"]="npc",["entityID"]=1748}},["url"]="https://www.wowhead.com/classic/quest=6403#comments",["startTargets"]={{["name"]="Реджинальд Винздор",["zone"]="Штормград",["zoneEN"]="Stormwind City",["x"]=69.56,["y"]=85.9,["kind"]="npc",["entityID"]=12580}}}
G.questHelp[6501]={["steps"]={"Пройдите пещеру Мазторил в Зимних Ключах до светящейся руны в глубине.","Встаньте на руну: она перенесёт к Хале. Поговорите с ней о восстановлении амулета."},["refs"]={{[1]="Начало: Верховный лорд Болвар Фордрагон",[2]="https://www.wowhead.com/classic/ru/npc=1748",["targets"]={{["name"]="Верховный лорд Болвар Фордрагон",["zone"]="Штормград",["zoneEN"]="Stormwind City",["x"]=78.23,["y"]=17.98,["kind"]="npc",["entityID"]=1748}},["kind"]="npc",["entityID"]=1748},{[1]="Сдача: Халех",[2]="https://www.wowhead.com/classic/ru/npc=10929",["targets"]={{["name"]="Халех",["zone"]="Зимние Ключи",["zoneEN"]="Winterspring",["x"]=54.55,["y"]=51.2,["kind"]="npc",["entityID"]=10929}},["kind"]="npc",["entityID"]=10929},{[1]="Выданный предмет: Фрагмент амулета Око Дракона",[2]="https://www.wowhead.com/classic/ru/item=16662",["targets"]={},["kind"]="item",["entityID"]=16662}},["url"]="https://www.wowhead.com/classic/quest=6501#comments",["startTargets"]={{["name"]="Верховный лорд Болвар Фордрагон",["zone"]="Штормград",["zoneEN"]="Stormwind City",["x"]=78.23,["y"]=17.98,["kind"]="npc",["entityID"]=1748}}}
G.questHelp[6502]={["steps"]={"Возьмите задание у Хале до похода в Верхнюю часть Пика Чёрной горы.","Победите генерала Драккисата, заберите кровь и принесите Хале. Полученный Амулет Пламени дракона нужен каждому входящему к Ониксии."},["refs"]={{[1]="Начало: Халех",[2]="https://www.wowhead.com/classic/ru/npc=10929",["targets"]={{["name"]="Халех",["zone"]="Зимние Ключи",["zoneEN"]="Winterspring",["x"]=54.55,["y"]=51.2,["kind"]="npc",["entityID"]=10929}},["kind"]="npc",["entityID"]=10929},{[1]="Цель: Кровь могучего черного дракона",[2]="https://www.wowhead.com/classic/ru/item=16663",["targets"]={{["name"]="Подход к подземелью: Генерал Драккисат находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=10363},{["name"]="Подход к подземелью: Генерал Драккисат находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=10363}},["kind"]="item",["entityID"]=16663},{[1]="Источник добычи: Генерал Драккисат",[2]="https://www.wowhead.com/classic/ru/npc=10363",["targets"]={{["name"]="Подход к подземелью: Генерал Драккисат находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=10363},{["name"]="Подход к подземелью: Генерал Драккисат находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=10363}},["kind"]="npc",["entityID"]=10363}},["url"]="https://www.wowhead.com/classic/quest=6502#comments",["startTargets"]={{["name"]="Халех",["zone"]="Зимние Ключи",["zoneEN"]="Winterspring",["x"]=54.55,["y"]=51.2,["kind"]="npc",["entityID"]=10929}}}
G.questHelp[6566]={["steps"]={"Снова поговорите с Траллом и нажимайте маленькую реплику в диалоге, пока рассказ не закончится.","Простого открытия окна задания недостаточно."},["refs"]={{[1]="Начало: Тралл",[2]="https://www.wowhead.com/classic/ru/npc=4949",["targets"]={{["name"]="Тралл",["zone"]="Оргриммар",["zoneEN"]="Orgrimmar",["x"]=31.73,["y"]=37.82,["kind"]="npc",["entityID"]=4949}},["kind"]="npc",["entityID"]=4949}},["url"]="https://www.wowhead.com/classic/quest=6566#comments",["startTargets"]={{["name"]="Тралл",["zone"]="Оргриммар",["zoneEN"]="Orgrimmar",["x"]=31.73,["y"]=37.82,["kind"]="npc",["entityID"]=4949}}}
G.questHelp[6567]={["steps"]={"Найдите Рексара на его патруле между Когтистыми горами, Пустошами и Фераласом.","На карте персонажа Wowhead показана траектория, а не его текущее положение. Идите вдоль маршрута навстречу патрулю."},["refs"]={{[1]="Начало: Тралл",[2]="https://www.wowhead.com/classic/ru/npc=4949",["targets"]={{["name"]="Тралл",["zone"]="Оргриммар",["zoneEN"]="Orgrimmar",["x"]=31.73,["y"]=37.82,["kind"]="npc",["entityID"]=4949}},["kind"]="npc",["entityID"]=4949},{[1]="Сдача: Рексар",[2]="https://www.wowhead.com/classic/ru/npc=10182",["targets"]={{["name"]="Рексар — маршрут патруля",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=46.39,["y"]=18.24,["kind"]="npc",["entityID"]=10182,["npc"]=10182,["patrol"]=true}},["kind"]="npc",["entityID"]=10182}},["url"]="https://www.wowhead.com/classic/quest=6567#comments",["startTargets"]={{["name"]="Тралл",["zone"]="Оргриммар",["zoneEN"]="Orgrimmar",["x"]=31.73,["y"]=37.82,["kind"]="npc",["entityID"]=4949}},["serverNote"]="На классическом этапе Solo Progress нужен Рексар, даже если текст другой версии упоминает Рокаро."}
G.questHelp[6568]={["steps"]={"Доставьте Завет Рексара Миранде Колдунье в Западные Чумные земли.","Это передача письма, а не бой: после разговора возьмите следующий этап с глазами драконов."},["refs"]={{[1]="Начало: Рексар",[2]="https://www.wowhead.com/classic/ru/npc=10182",["targets"]={{["name"]="Рексар — маршрут патруля",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=46.39,["y"]=18.24,["kind"]="npc",["entityID"]=10182,["npc"]=10182,["patrol"]=true}},["kind"]="npc",["entityID"]=10182},{[1]="Сдача: Миранда Колдунья",[2]="https://www.wowhead.com/classic/ru/npc=11872",["targets"]={{["name"]="Миранда Колдунья",["zone"]="Западные Чумные земли",["zoneEN"]="Western Plaguelands",["x"]=50.79,["y"]=77.85,["kind"]="npc",["entityID"]=11872}},["kind"]="npc",["entityID"]=11872},{[1]="Выданный предмет: Письмо Рокаро",[2]="https://www.wowhead.com/classic/ru/item=16785",["targets"]={},["kind"]="item",["entityID"]=16785}},["url"]="https://www.wowhead.com/classic/quest=6568#comments",["startTargets"]={{["name"]="Рексар — маршрут патруля",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=46.39,["y"]=18.24,["kind"]="npc",["entityID"]=10182,["npc"]=10182,["patrol"]=true}}}
G.questHelp[6569]={["steps"]={"Соберите 20 глаз чёрных драконов с драконидов в Верхней части Пика Чёрной горы.","Вернитесь к Миранде. Если задание есть у нескольких участников, каждому нужен свой комплект предметов."},["refs"]={{[1]="Начало: Миранда Колдунья",[2]="https://www.wowhead.com/classic/ru/npc=11872",["targets"]={{["name"]="Миранда Колдунья",["zone"]="Западные Чумные земли",["zoneEN"]="Western Plaguelands",["x"]=50.79,["y"]=77.85,["kind"]="npc",["entityID"]=11872}},["kind"]="npc",["entityID"]=11872},{[1]="Цель: Глаз черного драконида",[2]="https://www.wowhead.com/classic/ru/item=16786",["targets"]={{["name"]="Подход к подземелью: Гнездовая Когтя Смерти находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=12468},{["name"]="Подход к подземелью: Гнездовая Когтя Смерти находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=12468}},["kind"]="item",["entityID"]=16786}},["url"]="https://www.wowhead.com/classic/quest=6569#comments",["startTargets"]={{["name"]="Миранда Колдунья",["zone"]="Западные Чумные земли",["zoneEN"]="Western Plaguelands",["x"]=50.79,["y"]=77.85,["kind"]="npc",["entityID"]=11872}}}
G.questHelp[6570]={["steps"]={"Используйте выданный Мирандой амулет для маскировки и поговорите с Огнебором в его логове в Пылевых топях.","Возьмите три задания на черепа Хроналиса, Провидца и Сомнуса. Их можно выполнить в любом порядке; затем откроется Акстроз."},["refs"]={{[1]="Начало: Миранда Колдунья",[2]="https://www.wowhead.com/classic/ru/npc=11872",["targets"]={{["name"]="Миранда Колдунья",["zone"]="Западные Чумные земли",["zoneEN"]="Western Plaguelands",["x"]=50.79,["y"]=77.85,["kind"]="npc",["entityID"]=11872}},["kind"]="npc",["entityID"]=11872},{[1]="Сдача: Огнебор",[2]="https://www.wowhead.com/classic/ru/npc=10321",["targets"]={{["name"]="Огнебор",["zone"]="Пылевые топи",["zoneEN"]="Dustwallow Marsh",["x"]=56.66,["y"]=87.72,["kind"]="npc",["entityID"]=10321}},["kind"]="npc",["entityID"]=10321},{[1]="Выданный предмет: Амулет обмана драконов",[2]="https://www.wowhead.com/classic/ru/item=16787",["targets"]={},["kind"]="item",["entityID"]=16787}},["url"]="https://www.wowhead.com/classic/quest=6570#comments",["startTargets"]={{["name"]="Миранда Колдунья",["zone"]="Западные Чумные земли",["zoneEN"]="Western Plaguelands",["x"]=50.79,["y"]=77.85,["kind"]="npc",["entityID"]=11872}}}
G.questHelp[6582]={["steps"]={"Найдите синего дракона Провидца в Зимних Ключах и победите его.","Заберите череп с тела и вернитесь к Огнебору."},["refs"]={{[1]="Начало: Огнебор",[2]="https://www.wowhead.com/classic/ru/npc=10321",["targets"]={{["name"]="Огнебор",["zone"]="Пылевые топи",["zoneEN"]="Dustwallow Marsh",["x"]=56.66,["y"]=87.72,["kind"]="npc",["entityID"]=10321}},["kind"]="npc",["entityID"]=10321},{[1]="Цель: Череп Провидца",[2]="https://www.wowhead.com/classic/ru/item=16869",["targets"]={{["name"]="Источник добычи: Провидец (место поиска)",["zone"]="Зимние Ключи",["zoneEN"]="Winterspring",["x"]=52.71,["y"]=55.89,["kind"]="npc",["entityID"]=10664}},["kind"]="item",["entityID"]=16869},{[1]="Источник добычи: Провидец",[2]="https://www.wowhead.com/classic/ru/npc=10664",["targets"]={{["name"]="Провидец (место поиска)",["zone"]="Зимние Ключи",["zoneEN"]="Winterspring",["x"]=52.71,["y"]=55.89,["kind"]="npc",["entityID"]=10664}},["kind"]="npc",["entityID"]=10664}},["url"]="https://www.wowhead.com/classic/quest=6582#comments",["startTargets"]={{["name"]="Огнебор",["zone"]="Пылевые топи",["zoneEN"]="Dustwallow Marsh",["x"]=56.66,["y"]=87.72,["kind"]="npc",["entityID"]=10321}}}
G.questHelp[6583]={["steps"]={"Найдите патрулирующего Сомнуса в Болоте Печали. Расчистите место боя заранее.","Учитывайте отбрасывание: рядом не должно быть лишних противников. Заберите череп и принесите Огнебору."},["refs"]={{[1]="Начало: Огнебор",[2]="https://www.wowhead.com/classic/ru/npc=10321",["targets"]={{["name"]="Огнебор",["zone"]="Пылевые топи",["zoneEN"]="Dustwallow Marsh",["x"]=56.66,["y"]=87.72,["kind"]="npc",["entityID"]=10321}},["kind"]="npc",["entityID"]=10321},{[1]="Цель: Череп Сомнуса",[2]="https://www.wowhead.com/classic/ru/item=16870",["targets"]={{["name"]="Источник добычи: Сомнус (место поиска)",["zone"]="Болото Печали",["zoneEN"]="Swamp of Sorrows",["x"]=74.12,["y"]=68.35,["kind"]="npc",["entityID"]=12900}},["kind"]="item",["entityID"]=16870},{[1]="Источник добычи: Сомнус",[2]="https://www.wowhead.com/classic/ru/npc=12900",["targets"]={{["name"]="Сомнус (место поиска)",["zone"]="Болото Печали",["zoneEN"]="Swamp of Sorrows",["x"]=74.12,["y"]=68.35,["kind"]="npc",["entityID"]=12900}},["kind"]="npc",["entityID"]=12900}},["url"]="https://www.wowhead.com/classic/quest=6583#comments",["startTargets"]={{["name"]="Огнебор",["zone"]="Пылевые топи",["zoneEN"]="Dustwallow Marsh",["x"]=56.66,["y"]=87.72,["kind"]="npc",["entityID"]=10321}}}
G.questHelp[6584]={["steps"]={"Найдите Хроналиса у Пещер Времени в Танарисе и победите его.","Заберите череп и принесите Огнебору. Не перепутайте цель с другими драконами у входа."},["refs"]={{[1]="Начало: Огнебор",[2]="https://www.wowhead.com/classic/ru/npc=10321",["targets"]={{["name"]="Огнебор",["zone"]="Пылевые топи",["zoneEN"]="Dustwallow Marsh",["x"]=56.66,["y"]=87.72,["kind"]="npc",["entityID"]=10321}},["kind"]="npc",["entityID"]=10321},{[1]="Цель: Череп Хроналиса",[2]="https://www.wowhead.com/classic/ru/item=16871",["targets"]={{["name"]="Источник добычи: Хроналис",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=64.16,["y"]=48.49,["kind"]="npc",["entityID"]=8197}},["kind"]="item",["entityID"]=16871},{[1]="Источник добычи: Хроналис",[2]="https://www.wowhead.com/classic/ru/npc=8197",["targets"]={{["name"]="Хроналис",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=64.16,["y"]=48.49,["kind"]="npc",["entityID"]=8197}},["kind"]="npc",["entityID"]=8197}},["url"]="https://www.wowhead.com/classic/quest=6584#comments",["startTargets"]={{["name"]="Огнебор",["zone"]="Пылевые топи",["zoneEN"]="Dustwallow Marsh",["x"]=56.66,["y"]=87.72,["kind"]="npc",["entityID"]=10321}}}
G.questHelp[6585]={["steps"]={"Отправляйтесь к Грим Батолу в Болотине и найдите Акстроза.","Победите дракона, заберите его череп и вернитесь к Огнебору."},["refs"]={{[1]="Начало: Огнебор",[2]="https://www.wowhead.com/classic/ru/npc=10321",["targets"]={{["name"]="Огнебор",["zone"]="Пылевые топи",["zoneEN"]="Dustwallow Marsh",["x"]=56.66,["y"]=87.72,["kind"]="npc",["entityID"]=10321}},["kind"]="npc",["entityID"]=10321},{[1]="Цель: Череп Акстроза",[2]="https://www.wowhead.com/classic/ru/item=16872",["targets"]={{["name"]="Источник добычи: Акстроз (место поиска)",["zone"]="Болотина",["zoneEN"]="Wetlands",["x"]=81.82,["y"]=48.24,["kind"]="npc",["entityID"]=12899}},["kind"]="item",["entityID"]=16872},{[1]="Источник добычи: Акстроз",[2]="https://www.wowhead.com/classic/ru/npc=12899",["targets"]={{["name"]="Акстроз (место поиска)",["zone"]="Болотина",["zoneEN"]="Wetlands",["x"]=81.82,["y"]=48.24,["kind"]="npc",["entityID"]=12899}},["kind"]="npc",["entityID"]=12899}},["url"]="https://www.wowhead.com/classic/quest=6585#comments",["startTargets"]={{["name"]="Огнебор",["zone"]="Пылевые топи",["zoneEN"]="Dustwallow Marsh",["x"]=56.66,["y"]=87.72,["kind"]="npc",["entityID"]=10321}}}
G.questHelp[6601]={["steps"]={"После испытаний Огнебора вернитесь к Рексару и покажите полученный амулет.","На классическом этапе Solo Progress нужен именно Рексар, а не Рокаро из других версий игры."},["refs"]={{[1]="Начало: Огнебор",[2]="https://www.wowhead.com/classic/ru/npc=10321",["targets"]={{["name"]="Огнебор",["zone"]="Пылевые топи",["zoneEN"]="Dustwallow Marsh",["x"]=56.66,["y"]=87.72,["kind"]="npc",["entityID"]=10321}},["kind"]="npc",["entityID"]=10321},{[1]="Сдача: Рексар",[2]="https://www.wowhead.com/classic/ru/npc=10182",["targets"]={{["name"]="Рексар — маршрут патруля",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=46.39,["y"]=18.24,["kind"]="npc",["entityID"]=10182,["npc"]=10182,["patrol"]=true}},["kind"]="npc",["entityID"]=10182},{[1]="Выданный предмет: Амулет угасающего пламени дракона",[2]="https://www.wowhead.com/classic/ru/item=16888",["targets"]={},["kind"]="item",["entityID"]=16888}},["url"]="https://www.wowhead.com/classic/quest=6601#comments",["startTargets"]={{["name"]="Огнебор",["zone"]="Пылевые топи",["zoneEN"]="Dustwallow Marsh",["x"]=56.66,["y"]=87.72,["kind"]="npc",["entityID"]=10321}},["serverNote"]="На Solo Progress ищите Рексара на классическом этапе; замена на Рокаро в других версиях сюда не переносится."}
G.questHelp[6602]={["steps"]={"Возьмите задание до похода к генералу Драккисату в Верхней части Пика Чёрной горы.","После победы заберите кровь и вернитесь к Рексару за Амулетом Пламени дракона. Проверьте добычу у каждого участника с заданием."},["refs"]={{[1]="Начало: Рексар",[2]="https://www.wowhead.com/classic/ru/npc=10182",["targets"]={{["name"]="Рексар — маршрут патруля",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=46.39,["y"]=18.24,["kind"]="npc",["entityID"]=10182,["npc"]=10182,["patrol"]=true}},["kind"]="npc",["entityID"]=10182},{[1]="Цель: Кровь могучего черного дракона",[2]="https://www.wowhead.com/classic/ru/item=16663",["targets"]={{["name"]="Подход к подземелью: Генерал Драккисат находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=10363},{["name"]="Подход к подземелью: Генерал Драккисат находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=10363}},["kind"]="item",["entityID"]=16663},{[1]="Источник добычи: Генерал Драккисат",[2]="https://www.wowhead.com/classic/ru/npc=10363",["targets"]={{["name"]="Подход к подземелью: Генерал Драккисат находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=10363},{["name"]="Подход к подземелью: Генерал Драккисат находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=10363}},["kind"]="npc",["entityID"]=10363}},["url"]="https://www.wowhead.com/classic/quest=6602#comments",["startTargets"]={{["name"]="Рексар — маршрут патруля",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=46.39,["y"]=18.24,["kind"]="npc",["entityID"]=10182,["npc"]=10182,["patrol"]=true}}}
G.questHelp[6804]={["steps"]={"На озере юго-западнее Часовни Последней Надежды найдите заражённых элементалей воды.","Применяйте Аспект Нептулона к цели до её убийства, затем собирайте наручи. Нужны 12 наручей для Гидраксиса."},["refs"]={{[1]="Начало: Герцог Гидраксис",[2]="https://www.wowhead.com/classic/ru/npc=13278",["targets"]={{["name"]="Герцог Гидраксис",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=79.28,["y"]=73.7,["kind"]="npc",["entityID"]=13278}},["kind"]="npc",["entityID"]=13278},{[1]="Цель: Наручи обезумевших духов воды",[2]="https://www.wowhead.com/classic/ru/item=17309",["targets"]={},["kind"]="item",["entityID"]=17309},{[1]="Источник добычи: Колыхающийся волноплеск",[2]="https://www.wowhead.com/classic/ru/npc=13279",["targets"]={},["kind"]="npc",["entityID"]=13279},{[1]="Выданный предмет: Аспект Нептулона",[2]="https://www.wowhead.com/classic/ru/item=17310",["targets"]={},["kind"]="item",["entityID"]=17310}},["url"]="https://www.wowhead.com/classic/quest=6804#comments",["startTargets"]={{["name"]="Герцог Гидраксис",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=79.28,["y"]=73.7,["kind"]="npc",["entityID"]=13278}}}
G.questHelp[6805]={["steps"]={"Ищите пылевых и каменных элементалей в северо-западной части Силитуса.","Убейте по 15 нужных элементалей и вернитесь к Гидраксису. Элементали других видов не закрывают счётчик."},["refs"]={{[1]="Начало: Герцог Гидраксис",[2]="https://www.wowhead.com/classic/ru/npc=13278",["targets"]={{["name"]="Герцог Гидраксис",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=79.28,["y"]=73.7,["kind"]="npc",["entityID"]=13278}},["kind"]="npc",["entityID"]=13278},{[1]="Цель: Пылевихрь",[2]="https://www.wowhead.com/classic/ru/npc=11744",["targets"]={{["name"]="Пылевихрь",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=27.49,["y"]=18.13,["kind"]="npc",["entityID"]=11744},{["name"]="Пылевихрь",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=28.47,["y"]=19.96,["kind"]="npc",["entityID"]=11744},{["name"]="Пылевихрь",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=30.17,["y"]=13.88,["kind"]="npc",["entityID"]=11744},{["name"]="Пылевихрь",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=30.37,["y"]=16.82,["kind"]="npc",["entityID"]=11744}},["kind"]="npc",["entityID"]=11744},{[1]="Цель: Пустынный грохотун",[2]="https://www.wowhead.com/classic/ru/npc=11746",["targets"]={{["name"]="Пустынный грохотун",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=27,["y"]=15.53,["kind"]="npc",["entityID"]=11746},{["name"]="Пустынный грохотун",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=18.73,["y"]=17.13,["kind"]="npc",["entityID"]=11746},{["name"]="Пустынный грохотун",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=22.63,["y"]=19.54,["kind"]="npc",["entityID"]=11746},{["name"]="Пустынный грохотун",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=25.45,["y"]=15.16,["kind"]="npc",["entityID"]=11746}},["kind"]="npc",["entityID"]=11746}},["url"]="https://www.wowhead.com/classic/quest=6805#comments",["startTargets"]={{["name"]="Герцог Гидраксис",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=79.28,["y"]=73.7,["kind"]="npc",["entityID"]=13278}}}
G.questHelp[6821]={["steps"]={"Пройдите Верхнюю часть Пика Чёрной горы до Пиростража Углевзора.","Победите его, заберите требуемое око и отнесите Гидраксису. Это этап цепочки тушения рун, не само получение воды."},["refs"]={{[1]="Начало: Герцог Гидраксис",[2]="https://www.wowhead.com/classic/ru/npc=13278",["targets"]={{["name"]="Герцог Гидраксис",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=79.28,["y"]=73.7,["kind"]="npc",["entityID"]=13278}},["kind"]="npc",["entityID"]=13278},{[1]="Цель: Глаз Огневидца",[2]="https://www.wowhead.com/classic/ru/item=17322",["targets"]={{["name"]="Подход к подземелью: Пиростраж Созерцатель Углей находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9816},{["name"]="Подход к подземелью: Пиростраж Созерцатель Углей находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9816}},["kind"]="item",["entityID"]=17322},{[1]="Источник добычи: Пиростраж Созерцатель Углей",[2]="https://www.wowhead.com/classic/ru/npc=9816",["targets"]={{["name"]="Подход к подземелью: Пиростраж Созерцатель Углей находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9816},{["name"]="Подход к подземелью: Пиростраж Созерцатель Углей находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9816}},["kind"]="npc",["entityID"]=9816}},["url"]="https://www.wowhead.com/classic/quest=6821#comments",["startTargets"]={{["name"]="Герцог Гидраксис",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=79.28,["y"]=73.7,["kind"]="npc",["entityID"]=13278}}}
G.questHelp[6822]={["steps"]={"Для начала этого этапа требуется Дружелюбие с Гидраксианскими Повелителями Вод.","В Огненных Недрах убейте указанные в журнале виды противников и вернитесь к Гидраксису."},["refs"]={{[1]="Начало: Герцог Гидраксис",[2]="https://www.wowhead.com/classic/ru/npc=13278",["targets"]={{["name"]="Герцог Гидраксис",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=79.28,["y"]=73.7,["kind"]="npc",["entityID"]=13278}},["kind"]="npc",["entityID"]=13278},{[1]="Цель: Оплавленный великан",[2]="https://www.wowhead.com/classic/ru/npc=11658",["targets"]={{["name"]="Подход к подземелью: Оплавленный великан находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=11658},{["name"]="Подход к подземелью: Оплавленный великан находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=11658}},["kind"]="npc",["entityID"]=11658},{[1]="Цель: Повелитель огня",[2]="https://www.wowhead.com/classic/ru/npc=11668",["targets"]={{["name"]="Подход к подземелью: Повелитель огня находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=11668},{["name"]="Подход к подземелью: Повелитель огня находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=11668}},["kind"]="npc",["entityID"]=11668},{[1]="Цель: Древняя гончая бездны",[2]="https://www.wowhead.com/classic/ru/npc=11673",["targets"]={{["name"]="Подход к подземелью: Древняя гончая бездны находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=11673},{["name"]="Подход к подземелью: Древняя гончая бездны находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=11673}},["kind"]="npc",["entityID"]=11673},{[1]="Цель: Лавовый 