G.questHelp[6823]={["steps"]={"Поднимите репутацию с Гидраксианскими Повелителями Вод до Уважения.","Обычные элементали Силитуса перестают давать репутацию раньше нужного уровня; продолжайте её получать в Огненных Недрах, затем вернитесь к Гидраксису."},["refs"]={{[1]="Начало: Герцог Гидраксис",[2]="https://www.wowhead.com/classic/ru/npc=13278",["targets"]={{["name"]="Герцог Гидраксис",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=79.28,["y"]=73.7,["kind"]="npc",["entityID"]=13278}},["kind"]="npc",["entityID"]=13278}},["url"]="https://www.wowhead.com/classic/quest=6823#comments",["startTargets"]={{["name"]="Герцог Гидраксис",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=79.28,["y"]=73.7,["kind"]="npc",["entityID"]=13278}}}
G.questHelp[6824]={["steps"]={"Возьмите задание перед убийством Люцифрона, Гееннаса, Шаззраха и Сульфурона в Огненных Недрах.","Заберите требуемые руки с каждого босса и верните Гидраксису. Одних убийств без добычи предметов недостаточно."},["refs"]={{[1]="Начало: Герцог Гидраксис",[2]="https://www.wowhead.com/classic/ru/npc=13278",["targets"]={{["name"]="Герцог Гидраксис",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=79.28,["y"]=73.7,["kind"]="npc",["entityID"]=13278}},["kind"]="npc",["entityID"]=13278},{[1]="Цель: Рука Шаззраха",[2]="https://www.wowhead.com/classic/ru/item=17332",["targets"]={{["name"]="Подход к подземелью: Шаззрах находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=12264},{["name"]="Подход к подземелью: Шаззрах находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=12264}},["kind"]="item",["entityID"]=17332},{[1]="Источник добычи: Шаззрах",[2]="https://www.wowhead.com/classic/ru/npc=12264",["targets"]={{["name"]="Подход к подземелью: Шаззрах находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=12264},{["name"]="Подход к подземелью: Шаззрах находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=12264}},["kind"]="npc",["entityID"]=12264},{[1]="Цель: Рука Люцифрона",[2]="https://www.wowhead.com/classic/ru/item=17329",["targets"]={{["name"]="Подход к подземелью: Люцифрон находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=12118},{["name"]="Подход к подземелью: Люцифрон находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=12118}},["kind"]="item",["entityID"]=17329},{[1]="Источник добычи: Люцифрон",[2]="https://www.wowh