G.questHelp[7486]={["steps"]={"После разговора с Гидраксисом нырните у скалы, на которой он стоит.","Под водой рядом находится его сундук с наградой: искать его на вершине скалы не нужно."},["refs"]={{[1]="Начало: Герцог Гидраксис",[2]="https://www.wowhead.com/classic/ru/npc=13278",["targets"]={{["name"]="Герцог Гидраксис",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=79.28,["y"]=73.7,["kind"]="npc",["entityID"]=13278}},["kind"]="npc",["entityID"]=13278},{[1]="Сдача: Сундук Гидраксиса",[2]="https://www.wowhead.com/classic/ru/object=179551",["targets"]={{["name"]="Сундук Гидраксиса",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=79.24,["y"]=74.87,["kind"]="object",["entityID"]=179551}},["kind"]="object",["entityID"]=179551}},["url"]="https://www.wowhead.com/classic/quest=7486#comments",["startTargets"]={{["name"]="Герцог Гидраксис",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=79.28,["y"]=73.7,["kind"]="npc",["entityID"]=13278}}}
G.questHelp[7761]={["steps"]={"Возле входа в Пик Чёрной горы найдите интенданта легиона Изрубленного Щита и добудьте распоряжения.","Используйте предмет, чтобы взять «Приказ Чернорука», затем пройдите Верхнюю часть Пика Чёрной горы до генерала Драккисата.","После победы взаимодействуйте со светящейся сферой за генералом. После завершения можно пользоваться внешней сферой для быстрого входа в Логово Крыла Тьмы."},["refs"]={{[1]="Начало: Распоряжения Ренда Чернорука",[2]="https://www.wowhead.com/classic/ru/item=18987",["targets"]={{["name"]="Подход к подземелью: Интендант из легиона Изрубленного Щита находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9046},{["name"]="Подход к подземелью: Интендант из легиона Изрубленного Щита находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9046}},["kind"]="item",["entityID"]=18987},{[1]="Источник добычи: Интендант из легиона Изрубленного Щита",[2]="https://www.wowhead.com/classic/ru/npc=9046",["targets"]={{["name"]="Подход к подземелью: Интендант из легиона Изрубленного Щита находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9046},{["name"]="Подход к подземелью: Интендант из легиона Изрубленного Щита находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9046}},["kind"]="npc",["entityID"]=9046},{[1]="Сдача: Клеймо Драккисата",[2]="https://www.wowhead.com/classic/ru/object=179880",["targets"]={{["name"]="Подход к подземелью: Клеймо Драккисата находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=179880},{["name"]="Подход к подземелью: Клеймо Драккисата находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["