G.questHelp[7848]={["steps"]={"Поговорите с Лотосом Хранителем Портала на пути в Глубины Чёрной горы.","Внутри Глубин доберитесь до перехода в Огненные Недра и возьмите Осколок из Огненных Недр у портала. Верните его Лотосу: это открывает быстрый вход."},["refs"]={{[1]="Начало: Лотос Хранитель Портала",[2]="https://www.wowhead.com/classic/ru/npc=14387",["targets"]={{["name"]="Лотос Хранитель Портала",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=26.4,["y"]=24.45,["kind"]="npc",["entityID"]=14387},{["name"]="Лотос Хранитель Портала",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=32.13,["y"]=94.7,["kind"]="npc",["entityID"]=14387}},["kind"]="npc",["entityID"]=14387},{[1]="Цель: Осколок из Огненных Недр",[2]="https://www.wowhead.com/classic/ru/item=18412",["targets"]={{["name"]="Подход к подземелью: Осколок из Огненных Недр находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=179553},{["name"]="Подход к подземелью: Осколок из Огненных Недр находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=179553}},["kind"]="item",["entityID"]=18412},{[1]="Источник добычи: Осколок из Огненных Недр",[2]="https://www.wowhead.com/classic/ru/object=179553",["targets"]={{["name"]="Подход к подземелью: Осколок из Огненных Недр находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=179553},{["name"]="Подход к подземелью: Осколок из Огненных Недр находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=179553}},["kind"]="object",["entityID"]=179553}},["url"]="https://www.wowhead.com/classic/quest=7848#comments",["startTargets"]={{["name"]="Лотос Хранитель Портала",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=26.4,["y"]=24.45,["kind"]="npc",["entityID"]=14387},{["name"]="Лотос Хранитель Портала",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=32.13,["y"]=94.7,["kind"]="npc",["entityID"]=14387}}}
G.questHelp[8286]={["steps"]={"Доберитесь до Пещер Времени в Танарисе и осмотрите область с драконом у входа, примерно 65, 50.","Получив зачёт наблюдения, вернитесь к Баристолфу в Крепость Кенария. Не нападайте на драконов ради этого этапа."},["refs"]={{[1]="Начало: Баристолф из Зыбучих Песков",[2]="https://www.wowhead.com/classic/ru/npc=15180",["targets"]={{["name"]="Баристолф из Зыбучих Песков",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=49.45,["y"]=36.45,["kind"]="npc",["entityID"]=15180}},["kind"]="npc",["entityID"]=15180}},["url"]="https://www.wowhead.com/classic/quest=8286#comments",["startTargets"]={{["name"]="Баристолф из Зыбучих Песков",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=49.45,["y"]=36.45,["kind"]="npc",["entityID"]=15180}}}
G.questHelp[8288]={["steps"]={"Убейте Предводителя драконов Разящего Бича в Логове Крыла Тьмы и заберите его голову.","Голова не является общей добычей для всех участников: заранее определите получателя и отнесите её Баристолфу."},["refs"]={{[1]="Начало: Баристолф из Зыбучих Песков",[2]="https://www.wowhead.com/classic/ru/npc=15180",["targets"]={{["name"]="Баристолф из Зыбучих Песков",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=49.45,["y"]=36.45,["kind"]="npc",["entityID"]=15180}},["kind"]="npc",["entityID"]=15180},{[1]="Цель: Голова предводителя драконидов Разящего Бича",[2]="https://www.wowhead.com/classic/ru/item=20383",["targets"]={{["name"]="Подход к подземелью: Предводитель драконов Разящий Бич находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=12017},{["name"]="Подход к подземелью: Предводитель драконов Разящий Бич находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=12017}},["kind"]="item",["entityID"]=20383},{[1]="Источник добычи: Предводитель драконов Разящий Бич",[2]="https://www.wowhead.com/classic/ru/npc=12017",["targets"]={{["name"]="Подход к подземелью: Предводитель драконов Разящий Бич находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=12017},{["name"]="Подход к подземелью: Предводитель драконов Разящий Бич находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=12017}},["kind"]="npc",["entityID"]=12017}},["url"]="https://www.wowhead.com/classic/quest=8288#comments",["startTargets"]={{["name"]="Баристолф из Зыбучих Песков",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=49.45,["y"]=36.45,["kind"]="npc",["entityID"]=15180}}}
G.questHelp[8301]={["steps"]={"Соберите 200 силитидских панцирей и принесите Баристолфу.","Панцири может собирать участник цепочки и назначенные им помощники. Жетон помощника не заменяет условия доступа и не нужен всем участникам рейда."},["refs"]={{[1]="Начало: Баристолф из Зыбучих Песков",[2]="https://www.wowhead.com/classic/ru/npc=15180",["targets"]={{["name"]="Баристолф из Зыбучих Песков",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=49.45,["y"]=36.45,["kind"]="npc",["entityID"]=15180}},["kind"]="npc",["entityID"]=15180},{[1]="Цель: Обломок силитидского панциря",[2]="https://www.wowhead.com/classic/ru/item=20384",["targets"]={{["name"]="Источник добычи: Острожал из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=42.14,["y"]=30.36,["kind"]="npc",["entityID"]=11698},{["name"]="Источник добычи: Острожал из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=54.12,["y"]=44.94,["kind"]="npc",["entityID"]=11698},{["name"]="Источник добычи: Острожал из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=47.22,["y"]=45.86,["kind"]="npc",["entityID"]=11698},{["name"]="Источник добычи: Острожал из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=50.19,["y"]=49.62,["kind"]="npc",["entityID"]=11698},{["name"]="Источник добычи: Рабочий из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=40.41,["y"]=15.18,["kind"]="npc",["entityID"]=11721},{["name"]="Источник добычи: Рабочий из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=49.09,["y"]=23.9,["kind"]="npc",["entityID"]=11721},{["name"]="Источник добычи: Рабочий из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=43.31,["y"]=18.21,["kind"]="npc",["entityID"]=11721},{["name"]="Источник добычи: Рабочий из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=50.64,["y"]=26.72,["kind"]="npc",["entityID"]=11721},{["name"]="Источник добычи: Защитник из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=50.04,["y"]=26.77,["kind"]="npc",["entityID"]=11722},{["name"]="Источник добычи: Защитник из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=37.85,["y"]=13.26,["kind"]="npc",["entityID"]=11722},{["name"]="Источник добычи: Защитник из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=48.54,["y"]=18.44,["kind"]="npc",["entityID"]=11722},{["name"]="Источник добычи: Защитник из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=47.17,["y"]=16.44,["kind"]="npc",["entityID"]=11722}},["kind"]="item",["entityID"]=20384},{[1]="Выданный предмет: Агент Ноздорму",[2]="https://www.wowhead.com/classic/ru/item=20402",["targets"]={},["kind"]="item",["entityID"]=20402}},["url"]="https://www.wowhead.com/classic/quest=8301#comments",["startTargets"]={{["name"]="Баристолф из Зыбучих Песков",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=49.45,["y"]=36.45,["kind"]="npc",["entityID"]=15180}},["serverNote"]="Жетон помощника относится только к сбору панцирей за участника цепочки. Условия гонга задаются отдельно и указаны в серверной вики."}
G.questHelp[8302]={["steps"]={"После однократного «Пути праведника» сдайте повторяемую «Руку праведника» пять раз. Каждая сдача требует 200 обломков силитидских панцирей.","Итого репутационный участок: 200 панцирей для «Пути праведника» и ещё 1000 для пяти повторов «Руки праведника» — 1200 панцирей и шесть сдач.","Аддон автоматически считает новые повторы по изменению репутации. Старые повторы серверная история показывает только как факт хотя бы одной сдачи; при необходимости исправьте счётчик кнопками −1 / +1.","После 5 / 5 повторов или достижения Равнодушия проверьте у Баристолфа или Анахроноса задание «Анахронос»."},["refs"]={{[1]="Начало: Баристолф из Зыбучих Песков",[2]="https://www.wowhead.com/classic/ru/npc=15180",["targets"]={{["name"]="Баристолф из Зыбучих Песков",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=49.45,["y"]=36.45,["kind"]="npc",["entityID"]=15180}},["kind"]="npc",["entityID"]=15180},{[1]="Цель: Обломок силитидского панциря",[2]="https://www.wowhead.com/classic/ru/item=20384",["targets"]={{["name"]="Источник добычи: Острожал из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=42.14,["y"]=30.36,["kind"]="npc",["entityID"]=11698},{["name"]="Источник добычи: Острожал из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=54.12,["y"]=44.94,["kind"]="npc",["entityID"]=11698},{["name"]="Источник добычи: Острожал из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=47.22,["y"]=45.86,["kind"]="npc",["entityID"]=11698},{["name"]="Источник добычи: Острожал из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=50.19,["y"]=49.62,["kind"]="npc",["entityID"]=11698},{["name"]="Источник добычи: Рабочий из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=40.41,["y"]=15.18,["kind"]="npc",["entityID"]=11721},{["name"]="Источник добычи: Рабочий из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=49.09,["y"]=23.9,["kind"]="npc",["entityID"]=11721},{["name"]="Источник добычи: Рабочий из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=43.31,["y"]=18.21,["kind"]="npc",["entityID"]=11721},{["name"]="Источник добычи: Рабочий из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=50.64,["y"]=26.72,["kind"]="npc",["entityID"]=11721},{["name"]="Источник добычи: Защитник из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=50.04,["y"]=26.77,["kind"]="npc",["entityID"]=11722},{["name"]="Источник добычи: Защитник из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=37.85,["y"]=13.26,["kind"]="npc",["entityID"]=11722},{["name"]="Источник добычи: Защитник из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=48.54,["y"]=18.44,["kind"]="npc",["entityID"]=11722},{["name"]="Источник добычи: Защитник из улья Аши",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=47.17,["y"]=16.44,["kind"]="npc",["entityID"]=11722}},["kind"]="item",["entityID"]=20384}},["url"]="https://www.wowhead.com/classic/quest=8302#comments",["startTargets"]={{["name"]="Баристолф из Зыбучих Песков",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=49.45,["y"]=36.45,["kind"]="npc",["entityID"]=15180}},["serverNote"]="Для Solo Progress подтверждены пять повторных сдач после «Пути праведника»: шесть партий по 200 панцирей суммарно. Переход также подтверждается появлением «Анахроноса» или Равнодушием с Родом Ноздорму."}
G.questHelp[8303]={["steps"]={"После этапа с панцирями отправляйтесь к Анахроносу у Пещер Времени в Танарисе.","Поговорите с ним и возьмите поручение о воспоминаниях у врат Ан’Киража."},["refs"]={{[1]="Начало: Баристолф из Зыбучих Песков",[2]="https://www.wowhead.com/classic/ru/npc=15180",["targets"]={{["name"]="Баристолф из Зыбучих Песков",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=49.45,["y"]=36.45,["kind"]="npc",["entityID"]=15180}},["kind"]="npc",["entityID"]=15180},{[1]="Сдача: Анахронос",[2]="https://www.wowhead.com/classic/ru/npc=15192",["targets"]={{["name"]="Анахронос",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.27,["y"]=50.03,["kind"]="npc",["entityID"]=15192}},["kind"]="npc",["entityID"]=15192},{[1]="Выданный предмет: Война Зыбучих песков",[2]="https://www.wowhead.com/classic/ru/item=20415",["targets"]={},["kind"]="item",["entityID"]=20415}},["url"]="https://www.wowhead.com/classic/quest=8303#comments",["startTargets"]={{["name"]="Баристолф из Зыбучих Песков",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=49.45,["y"]=36.45,["kind"]="npc",["entityID"]=15180}}}
G.questHelp[8305]={["steps"]={"У врат Ан’Киража в Силитусе найдите небольшой красный светящийся кристалл на земле.","Взаимодействуйте с ним и посмотрите историческое событие. Затем вернитесь к Анахроносу."},["refs"]={{[1]="Начало: Анахронос",[2]="https://www.wowhead.com/classic/ru/npc=15192",["targets"]={{["name"]="Анахронос",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.27,["y"]=50.03,["kind"]="npc",["entityID"]=15192}},["kind"]="npc",["entityID"]=15192},{[1]="Сдача: Хрустальная слеза",[2]="https://www.wowhead.com/classic/ru/object=180633",["targets"]={{["name"]="Хрустальная слеза",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=28.68,["y"]=89.14,["kind"]="object",["entityID"]=180633}},["kind"]="object",["entityID"]=180633}},["url"]="https://www.wowhead.com/classic/quest=8305#comments",["startTargets"]={{["name"]="Анахронос",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.27,["y"]=50.03,["kind"]="npc",["entityID"]=15192}}}
G.questHelp[8519]={["steps"]={"Дождитесь окончания показанного воспоминания и вернитесь к Анахроносу.","После разговора продолжайте ветви осколков Скипетра. Этот этап не требует повторного убийства участников исторической сцены."},["refs"]={{[1]="Начало: Хрустальная слеза",[2]="https://www.wowhead.com/classic/ru/object=180633",["targets"]={{["name"]="Хрустальная слеза",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=28.68,["y"]=89.14,["kind"]="object",["entityID"]=180633}},["kind"]="object",["entityID"]=180633},{[1]="Сдача: Анахронос",[2]="https://www.wowhead.com/classic/ru/npc=15192",["targets"]={{["name"]="Анахронос",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.27,["y"]=50.03,["kind"]="npc",["entityID"]=15192}},["kind"]="npc",["entityID"]=15192}},["url"]="https://www.wowhead.com/classic/quest=8519#comments",["startTargets"]={{["name"]="Хрустальная слеза",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=28.68,["y"]=89.14,["kind"]="object",["entityID"]=180633}}}
G.questHelp[8555]={["steps"]={"Поговорите с Анахроносом и узнайте о трёх осколках Скипетра.","Дальнейший поиск связан с Нефарианом, Азурегосом и Эраникусом: это отдельные ветви одной цепочки."},["refs"]={{[1]="Начало: Анахронос",[2]="https://www.wowhead.com/classic/ru/npc=15192",["targets"]={{["name"]="Анахронос",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.27,["y"]=50.03,["kind"]="npc",["entityID"]=15192}},["kind"]="npc",["entityID"]=15192}},["url"]="https://www.wowhead.com/classic/quest=8555#comments",["startTargets"]={{["name"]="Анахронос",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.27,["y"]=50.03,["kind"]="npc",["entityID"]=15192}}}
G.questHelp[8575]={["steps"]={"Начало задания — у Духа Азурегоса (NPC 15481) в Азшаре. Он не стоит в одной точке, а патрулирует южную часть локации; откройте карту, чтобы увидеть весь маршрут.","Поговорите с Духом Азурегоса и пройдите диалог, чтобы получить магическую книгу.","Отнесите книгу Нарайну Причудню в Танарис: она начинает синюю ветвь Скипетра."},["refs"]={{[1]="Начало: Дух Азургероса",[2]="https://www.wowhead.com/classic/ru/npc=15481",["targets"]={{["name"]="Дух Азургероса — маршрут патруля",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=54.38,["y"]=79.79,["kind"]="npc",["entityID"]=15481,["npc"]=15481,["patrol"]=true}},["kind"]="npc",["entityID"]=15481},{[1]="Сдача: Нарайн Причудень",[2]="https://www.wowhead.com/classic/ru/npc=11811",["targets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}},["kind"]="npc",["entityID"]=11811}},["url"]="https://www.wowhead.com/classic/quest=8575#comments",["startTargets"]={{["name"]="Дух Азургероса — маршрут патруля",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=54.38,["y"]=79.79,["kind"]="npc",["entityID"]=15481,["npc"]=15481,["patrol"]=true}}}
G.questHelp[8576]={["steps"]={"Поговорите с Нарайном о переводе книги Азурегоса.","Он потребует очки, огромную курицу и учебник драконьего языка. Возьмите соответствующие поручения: они выполняются отдельными ветвями."},["refs"]={{[1]="Начало: Нарайн Причудень",[2]="https://www.wowhead.com/classic/ru/npc=11811",["targets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}},["kind"]="npc",["entityID"]=11811}},["url"]="https://www.wowhead.com/classic/quest=8576#comments",["startTargets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}}}
G.questHelp[8577]={["steps"]={"У Стены Седогрива на юге Серебряного бора откройте Неприметный ящик, 46.2, 86.7.","Поговорите с Измождённым беженцем внутри ящика и возьмите следующее задание."},["refs"]={{[1]="Начало: Нарайн Причудень",[2]="https://www.wowhead.com/classic/ru/npc=11811",["targets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}},["kind"]="npc",["entityID"]=11811},{[1]="Сдача: Не вызывающий подозрений сундук",[2]="https://www.wowhead.com/classic/ru/object=180642",["targets"]={{["name"]="Не вызывающий подозрений сундук",["zone"]="Серебряный бор",["zoneEN"]="Silverpine Forest",["x"]=46.19,["y"]=86.68,["kind"]="object",["entityID"]=180642}},["kind"]="object",["entityID"]=180642}},["url"]="https://www.wowhead.com/classic/quest=8577#comments",["startTargets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}}}
G.questHelp[8578]={["steps"]={"В Огненных Недрах убивайте обычных противников, пока не выпадут Гадальные очки Нарайна.","Предмет редкий и может потребовать нескольких заходов. Получив очки, вернитесь к Нарайну в Танарис."},["refs"]={{[1]="Начало: Не вызывающий подозрений сундук",[2]="https://www.wowhead.com/classic/ru/object=180642",["targets"]={{["name"]="Не вызывающий подозрений сундук",["zone"]="Серебряный бор",["zoneEN"]="Silverpine Forest",["x"]=46.19,["y"]=86.68,["kind"]="object",["entityID"]=180642}},["kind"]="object",["entityID"]=180642},{[1]="Сдача: Нарайн Причудень",[2]="https://www.wowhead.com/classic/ru/npc=11811",["targets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}},["kind"]="npc",["entityID"]=11811},{[1]="Цель: Гадальные очки Нарайна",[2]="https://www.wowhead.com/classic/ru/item=20951",["targets"]={{["name"]="Подход к подземелью: Шаззрах находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=12264},{["name"]="Подход к подземелью: Шаззрах находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=12264}},["kind"]="item",["entityID"]=20951}},["url"]="https://www.wowhead.com/classic/quest=8578#comments",["startTargets"]={{["name"]="Не вызывающий подозрений сундук",["zone"]="Серебряный бор",["zoneEN"]="Silverpine Forest",["x"]=46.19,["y"]=86.68,["kind"]="object",["entityID"]=180642}}}
G.questHelp[8584]={["steps"]={"В Прибамбасске поговорите с Могилем Быстрорубом, 52.6, 28.1.","Возьмите у него задание на Остров Ужаса. Навык кулинарии для этой ветки не требуется."},["refs"]={{[1]="Начало: Нарайн Причудень",[2]="https://www.wowhead.com/classic/ru/npc=11811",["targets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}},["kind"]="npc",["entityID"]=11811},{[1]="Сдача: Могиль Быстроруб",[2]="https://www.wowhead.com/classic/ru/npc=8125",["targets"]={{["name"]="Могиль Быстроруб",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=52.63,["y"]=28.11,["kind"]="npc",["entityID"]=8125}},["kind"]="npc",["entityID"]=8125}},["url"]="https://www.wowhead.com/classic/quest=8584#comments",["startTargets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}}}
G.questHelp[8585]={["steps"]={"В Фераласе зайдите на Остров Ужаса с юго-востока, около 35, 88. Пещера наг не ведёт к химерам.","Убейте Лорда Лакмерана около 29.7, 79.2 и заберите его труп.","Соберите 20 вырезок химеры с химер острова и вернитесь к Могилю в Прибамбасск."},["refs"]={{[1]="Начало: Могиль Быстроруб",[2]="https://www.wowhead.com/classic/ru/npc=8125",["targets"]={{["name"]="Могиль Быстроруб",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=52.63,["y"]=28.11,["kind"]="npc",["entityID"]=8125}},["kind"]="npc",["entityID"]=8125},{[1]="Цель: Труп Лакмерана",[2]="https://www.wowhead.com/classic/ru/item=21027",["targets"]={{["name"]="Источник добычи: Лорд Лакмеран",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=29.34,["y"]=72.63,["kind"]="npc",["entityID"]=12803}},["kind"]="item",["entityID"]=21027},{[1]="Источник добычи: Лорд Лакмеран",[2]="https://www.wowhead.com/classic/ru/npc=12803",["targets"]={{["name"]="Лорд Лакмеран",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=29.34,["y"]=72.63,["kind"]="npc",["entityID"]=12803}},["kind"]="npc",["entityID"]=12803},{[1]="Цель: Вырезка химеры",[2]="https://www.wowhead.com/classic/ru/item=21024",["targets"]={{["name"]="Источник добычи: Химера",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=31.25,["y"]=87.79,["kind"]="npc",["entityID"]=12800},{["name"]="Источник добычи: Химера",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=29.67,["y"]=80.99,["kind"]="npc",["entityID"]=12800},{["name"]="Источник добычи: Химера",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=28.15,["y"]=74.54,["kind"]="npc",["entityID"]=12800},{["name"]="Источник добычи: Химера",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=29.82,["y"]=80.93,["kind"]="npc",["entityID"]=12800},{["name"]="Источник добычи: Волшебный химерон",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=30.93,["y"]=85.54,["kind"]="npc",["entityID"]=12801},{["name"]="Источник добычи: Волшебный химерон",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=30.16,["y"]=87.84,["kind"]="npc",["entityID"]=12801},{