=12801},{["name"]="Волшебный химерон",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=29.19,["y"]=75.46,["kind"]="npc",["entityID"]=12801}},["kind"]="npc",["entityID"]=12801},{[1]="Источник добычи: Химера-пожиратель",[2]="https://www.wowhead.com/classic/ru/npc=12802",["targets"]={{["name"]="Химера-пожиратель",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=30.57,["y"]=75.76,["kind"]="npc",["entityID"]=12802},{["name"]="Химера-пожиратель",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=29.59,["y"]=75.89,["kind"]="npc",["entityID"]=12802},{["name"]="Химера-пожиратель",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=28.47,["y"]=71.42,["kind"]="npc",["entityID"]=12802},{["name"]="Химера-пожиратель",["zone"]="Фералас",["zoneEN"]="Feralas",["x"]=28.95,["y"]=71.25,["kind"]="npc",["entityID"]=12802}},["kind"]="npc",["entityID"]=12802}},["url"]="https://www.wowhead.com/classic/quest=8585#comments",["startTargets"]={{["name"]="Могиль Быстроруб",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=52.63,["y"]=28.11,["kind"]="npc",["entityID"]=8125}}}
G.questHelp[8586]={["steps"]={"Гоблинское ракетное топливо выгоднее изготовить: алхимику с навыком 210 нужно по 1 огнецвету, летучему рому и освинцованной колбе на каждую единицу. Для задания подготовьте по 20 каждого компонента и попросите алхимика сделать 20 топлива.","Рецепт «Гоблинское ракетное топливо» (предмет 10644) создаёт гоблинский инженер с навыком 205 из чистого пергамента и инженерного красителя. Огнецвет собирается в Танарисе, Тлеющем ущелье и Выжженных землях; летучий ром удобно выбивать у пиратов Южных морей в бухте Сорванных Парусов, Танарис, примерно 70–76, 42–49. Освинцованные колбы продают торговцы алхимическими принадлежностями.","Глубокоскальная соль падает с каменных элементалей. Быстрый маршрут для персонажа 60-го уровня: Бесплодные земли — младшие каменные элементали на западе, примерно 13–23, 37–48, затем каменные элементали на юго-востоке, примерно 35–46, 74–88.","Если маршрут в Бесплодных землях занят, убивайте обсидиановых и больших обсидиановых элементалей в Пылающих степях; они разбросаны по центру и востоку локации, ориентиры 41, 44; 55, 49; 55, 63; 66, 32.","Собрав 20 гоблинского ракетного топлива и 20 глубокоскальной соли, вернитесь к Могилю Быстрорубу в Прибамбасск. После сдачи заберите 500-фунтовую курицу и новое задание на возвращение к Нарайну."},["refs"]={{[1]="Начало: Могиль Быстроруб",[2]="https://www.wowhead.com/classic/ru/npc=8125",["targets"]={{["name"]="Могиль Быстроруб",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=52.63,["y"]=28.11,["kind"]="npc",["entityID"]=8125}},["kind"]="npc",["entityID"]=8125},{[1]="Цель: Гоблинское ракетное топливо",[2]="https://www.wowhead.com/classic/ru/item=9061",["targets"]={{["name"]="Источник добычи: Лязгун",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.69,["y"]=51.89,["kind"]="npc",["entityID"]=8447},{["name"]="Подход к подземелью: Огр-волхв из клана Черной Вершины находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9201},{["name"]="Подход к подземелью: Огр-волхв из клана Черной Вершины находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=9201},{["name"]="Источник добычи: Истерзанный друид",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=60.94,["y"]=58.39,["kind"]="npc",["entityID"]=12178},{["name"]="Источник добычи: Истерзанный друид",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=63.96,["y"]=58.43,["kind"]="npc",["entityID"]=12178},{["name"]="Источник добычи: Истерзанный друид",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=62.73,["y"]=58.37,["kind"]="npc",["entityID"]=12178},{["name"]="Источник добычи: Истерзанный друид",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=59.77,["y"]=54.14,["kind"]="npc",["entityID"]=12178},{["name"]="Источник добычи: 7:XT",["zone"]="Бесплодные земли",["zoneEN"]="Badlands",["x"]=55.07,["y"]=83.62,["kind"]="npc",["entityID"]=14224},{["name"]="Источник добычи: 7:XT",["zone"]="Бесплодные земли",["zoneEN"]="Badlands",["x"]=54.25,["y"]=53.54,["kind"]="npc",["entityID"]=14224},{["name"]="Источник добычи: 7:XT",["zone"]="Бесплодные земли",["zoneEN"]="Badlands",["x"]=23.76,["y"]=52.38,["kind"]="npc",["entityID"]=14224},{["name"]="Источник добычи: 7:XT",["zone"]="Бесплодные земли",["zoneEN"]="Badlands",["x"]=28.72,["y"]=68.72,["kind"]="npc",["entityID"]=14224}},["kind"]="item",["entityID"]=9061},{[1]="Источник добычи: Лязгун",[2]="https://www.wowhead.com/classic/ru/npc=8447",["targets"]={{["name"]="Лязгун",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.69,["y"]=51.89,["kind"]="npc",["entityID"]=8447}},["kind"]="npc",["entityID"]=8447},{[1]="Источник добычи: Огр-волхв из клана Черной Вершины",[2]="https://www.wowhead.com/classic/ru/npc=9201",["targets"]={{["name"]="Подход к подземелью: Огр-волхв из клана Черной Вершины находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=9201},{["n