G.questHelp[8587]={["steps"]={"Отнесите 500-фунтовую курицу Нарайну в Танарис, 65.2, 18.6.","Ничего дополнительно добывать не нужно."},["refs"]={{[1]="Начало: Могиль Быстроруб",[2]="https://www.wowhead.com/classic/ru/npc=8125",["targets"]={{["name"]="Могиль Быстроруб",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=52.63,["y"]=28.11,["kind"]="npc",["entityID"]=8125}},["kind"]="npc",["entityID"]=8125},{[1]="Сдача: Нарайн Причудень",[2]="https://www.wowhead.com/classic/ru/npc=11811",["targets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}},["kind"]="npc",["entityID"]=11811},{[1]="Выданный предмет: 500-фунтовый цыпленок",[2]="https://www.wowhead.com/classic/ru/item=21028",["targets"]={},["kind"]="item",["entityID"]=21028}},["url"]="https://www.wowhead.com/classic/quest=8587#comments",["startTargets"]={{["name"]="Могиль Быстроруб",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=52.63,["y"]=28.11,["kind"]="npc",["entityID"]=8125}}}
G.questHelp[8597]={["steps"]={"Доберитесь до дальнего острова южнее Танариса и найдите закопанную книгу: вместо неё обнаружится записка о выкупе.","Для плавания через область усталости полезен эффект русалки после «Любовной песни для Нарайна». Не путайте этот этап с более поздним сбором восьми глав."},["refs"]={{[1]="Начало: Нарайн Причудень",[2]="https://www.wowhead.com/classic/ru/npc=11811",["targets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}},["kind"]="npc",["entityID"]=11811},{[1]="Сдача: Только что выброшенная земля",[2]="https://www.wowhead.com/classic/ru/object=180652",["targets"]={{["name"]="Только что выброшенная земля",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=59.3,["y"]=99.3,["kind"]="object",["entityID"]=180652}},["kind"]="object",["entityID"]=180652}},["url"]="https://www.wowhead.com/classic/quest=8597#comments",["startTargets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}}}
G.questHelp[8598]={["steps"]={"Прочитайте записку о выкупе, найденную вместо книги, и верните её Нарайну в Танарис.","Следующий этап — подмена получателя выкупа, а не оплата похитителям из собственного кошелька."},["refs"]={{[1]="Начало: Только что выброшенная земля",[2]="https://www.wowhead.com/classic/ru/object=180652",["targets"]={{["name"]="Только что выброшенная земля",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=59.3,["y"]=99.3,["kind"]="object",["entityID"]=180652}},["kind"]="object",["entityID"]=180652},{[1]="Сдача: Нарайн Причудень",[2]="https://www.wowhead.com/classic/ru/npc=11811",["targets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}},["kind"]="npc",["entityID"]=11811},{[1]="Выданный предмет: Письмо с требованием выкупа",[2]="https://www.wowhead.com/classic/ru/item=21029",["targets"]={},["kind"]="item",["entityID"]=21029}},["url"]="https://www.wowhead.com/classic/quest=8598#comments",["startTargets"]={{["name"]="Только что выброшенная земля",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=59.3,["y"]=99.3,["kind"]="object",["entityID"]=180652}}}
G.questHelp[8599]={["steps"]={"Это задание не обязательно для продолжения цепочки, но крайне рекомендуется перед «Драконьим языком для чайников». Возьмите письмо у Мередит Русаллы в море южнее Танариса и доставьте Нарайну.","После сдачи обязательно вернитесь к Мередит: она даст эффект ускорения плавания, который заметно упрощает заплыв к дальнему острову за книгой."},["refs"]={{[1]="Начало: Мередит Русалла",[2]="https://www.wowhead.com/classic/ru/npc=15526",["targets"]={{["name"]="Мередит Русалла",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=59.43,["y"]=96.05,["kind"]="npc",["entityID"]=15526}},["kind"]="npc",["entityID"]=15526},{[1]="Сдача: Нарайн Причудень",[2]="https://www.wowhead.com/classic/ru/npc=11811",["targets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}},["kind"]="npc",["entityID"]=11811},{[1]="Выданный предмет: Любовное послание Меридит",[2]="https://www.wowhead.com/classic/ru/item=21032",["targets"]={},["kind"]="item",["entityID"]=21032}},["url"]="https://www.wowhead.com/classic/quest=8599#comments",["startTargets"]={{["name"]="Мередит Русалла",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=59.43,["y"]=96.05,["kind"]="npc",["entityID"]=15526}}}
G.questHelp[8606]={["steps"]={"Откройте особый набор Нарайна и используйте выданную маскировку.","В Зимних Ключах положите мешок в указанном похитителями месте и дождитесь встречи. Победите прибывшего противника и вернитесь к Нарайну."},["refs"]={{[1]="Начало: Нарайн Причудень",[2]="https://www.wowhead.com/classic/ru/npc=11811",["targets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}},["kind"]="npc",["entityID"]=11811},{[1]="Цель: Номер Два",[2]="https://www.wowhead.com/classic/ru/npc=15554",["targets"]={},["kind"]="npc",["entityID"]=15554},{[1]="Выданный предмет: Особый набор Нарайна",[2]="https://www.wowhead.com/classic/ru/item=21042",["targets"]={},["kind"]="item",["entityID"]=21042}},["url"]="https://www.wowhead.com/classic/quest=8606#comments",["startTargets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}}}
G.questHelp[8620]={["steps"]={"Альянс — глава I: убейте Доктора Жло в доме на острове Алькац, Пылевые топи, около 78, 17. Глава выпадает в одном экземпляре.","Альянс — глава II: убивайте элитных стражей Скверны, повелителей ужаса и командиров стражи рока в Гнилом Шраме, Выжженные земли. Это случайная добыча.","Альянс — глава III: убивайте посвящённых и душегубов Хедерины в Теснине Тёмного Шёпота на юге Зимних Ключей. Это случайная добыча.","Альянс — глава IV: во вражеском Подгороде войдите через канализацию и доберитесь до Квартала Магов. Книга лежит на столе торговца книгами Салазара Блоча, 77, 39; помогут скрытность, невидимость или рейд на столицу.","Альянс — глава V: в своём Штормграде войдите в крепость; королевская библиотека — первая комната слева. Книга лежит у основания колонны слева от входа, около 75, 30.","Альянс — глава VI: убейте Ониксию в Логове Ониксии. Глава выпадает в одном экземпляре.","Альянс — глава VII: в Логове Крыла Тьмы пройдите зал Огнечрева. Книга лежит на алхимическом столе на площадке между пандусами по дороге к Черноскалу и Пламегору.","Альянс — глава VIII: убейте Рагнароса в Огненных Недрах. Глава выпадает в одном экземпляре; соберите том Магическим книжным переплётом и вернитесь к Нарайну."},["refs"]={{[1]="Начало: Нарайн Причудень",[2]="https://www.wowhead.com/classic/ru/npc=11811",["targets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}},["kind"]="npc",["entityID"]=11811},{[1]="Цель: Драконий язык для чайников, т. II",[2]="https://www.wowhead.com/classic/ru/item=21111",["targets"]={},["kind"]="item",["entityID"]=21111},{[1]="Выданный предмет: Магический книжный переплет",[2]="https://www.wowhead.com/classic/ru/item=21112",["targets"]={},["kind"]="item",["entityID"]=21112}},["url"]="https://www.wowhead.com/classic/quest=8620#comments",["startTargets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}},["allianceSteps"]={"Альянс — глава I: убейте Доктора Жло в доме на острове Алькац, Пылевые топи, около 78, 17. Глава выпадает в одном экземпляре.","Альянс — глава II: убивайте элитных стражей Скверны, повелителей ужаса и командиров стражи рока в Гнилом Шраме, Выжженные земли. Это случайная добыча.","Альянс — глава III: убивайте посвящённых и душегубов Хедерины в Теснине Тёмного Шёпота на юге Зимних Ключей. Это случайная добыча.","Альянс — глава IV: во вражеском Подгороде войдите через канализацию и доберитесь до Квартала Магов. Книга лежит на столе торговца книгами Салазара Блоча, 77, 39; помогут скрытность, невидимость или рейд на столицу.","Альянс — глава V: в своём Штормграде войдите в крепость; королевская библиотека — первая комната слева. Книга лежит у основания колонны слева от входа, около 75, 30.","Альянс — глава VI: убейте Ониксию в Логове Ониксии. Глава выпадает в одном экземпляре.","Альянс — глава VII: в Логове Крыла Тьмы пройдите зал Огнечрева. Книга лежит на алхимическом столе на площадке между пандусами по дороге к Черноскалу и Пламегору.","Альянс — глава VIII: убейте Рагнароса в Огненных Недрах. Глава выпадает в одном экземпляре; соберите том Магическим книжным переплётом и вернитесь к Нарайну."},["hordeSteps"]={"Орда — глава I: убейте Доктора Жло в доме на острове Алькац, Пылевые топи, около 78, 17. Глава выпадает в одном экземпляре.","Орда — глава II: убивайте элитных стражей Скверны, повелителей ужаса и командиров стражи рока в Гнилом Шраме, Выжженные земли. Это случайная добыча.","Орда — глава III: убивайте посвящённых и душегубов Хедерины в Теснине Тёмного Шёпота на юге Зимних Ключей. Это случайная добыча.","Орда — глава IV: в своём Подгороде идите в Квартал Магов. Книга лежит на столе торговца книгами Салазара Блоча, около 77, 39.","Орда — глава V: во вражеском Штормграде доберитесь до крепости; королевская библиотека — первая комната слева. Книга лежит у основания колонны слева от входа, около 75, 30; помогут скрытность, невидимость или рейд на столицу.","Орда — глава VI: убейте Ониксию в Логове Ониксии. Глава выпадает в одном экземпляре.","Орда — глава VII: в Логове Крыла Тьмы пройдите зал Огнечрева. Книга лежит на алхимическом столе на площадке между пандусами по дороге к Черноскалу и Пламегору.","Орда — глава VIII: убейте Рагнароса в Огненных Недрах. Глава выпадает в одном экземпляре; соберите том Магическим книжным переплётом и вернитесь к Нарайну."}}
