G.questHelp[8728]={["steps"]={"Принесите Нарайну в Танарис 20 арканитовых слитков, 10 элементиевой руды, 10 азеротских алмазов и 10 синих сапфиров.","В награду он выдаст арканитовый буй для следующего задания."},["refs"]={{[1]="Начало: Нарайн Причудень",[2]="https://www.wowhead.com/classic/ru/npc=11811",["targets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}},["kind"]="npc",["entityID"]=11811},{[1]="Цель: Арканитовый слиток",[2]="https://www.wowhead.com/classic/ru/item=12360",["targets"]={},["kind"]="item",["entityID"]=12360},{[1]="Цель: Элементиевая руда",[2]="https://www.wowhead.com/classic/ru/item=18562",["targets"]={{["name"]="Подход к подземелью: Техник Крыла Тьмы находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=13996},{["name"]="Подход к подземелью: Техник Крыла Тьмы находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=13996}},["kind"]="item",["entityID"]=18562},{[1]="Источник добычи: Техник Крыла Тьмы",[2]="https://www.wowhead.com/classic/ru/npc=13996",["targets"]={{["name"]="Подход к подземелью: Техник Крыла Тьмы находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=13996},{["name"]="Подход к подземелью: Техник Крыла Тьмы находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=13996}},["kind"]="npc",["entityID"]=13996},{[1]="Цель: Азеротский алмаз",[2]="https://www.wowhead.com/classic/ru/item=12800",["targets"]={{["name"]="Источник добычи: Скальный разрушитель",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=56.71,["y"]=79.76,["kind"]="npc",["entityID"]=6146},{["name"]="Источник добычи: Скальный разрушитель",["zone"]="Азшара",["zoneEN"]="Azshara",["x"]=48.81,["y"]=83.38,["kind"]="npc",["