G.questHelp[8729]={["steps"]={"В Азшаре доплывите до Водоворота в Заливе Бурь, около 65.8, 54.8, и используйте арканитовый буй.","Убейте Утробу, заберите синий осколок и отнесите его Анахроносу в Танарис. После неудачной попытки новый буй можно бесплатно получить у Нарайна."},["refs"]={{[1]="Начало: Нарайн Причудень",[2]="https://www.wowhead.com/classic/ru/npc=11811",["targets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}},["kind"]="npc",["entityID"]=11811},{[1]="Сдача: Анахронос",[2]="https://www.wowhead.com/classic/ru/npc=15192",["targets"]={{["name"]="Анахронос",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.27,["y"]=50.03,["kind"]="npc",["entityID"]=15192}},["kind"]="npc",["entityID"]=15192},{[1]="Цель: Осколки синего скипетра",[2]="https://www.wowhead.com/classic/ru/item=21137",["targets"]={},["kind"]="item",["entityID"]=21137},{[1]="Источник добычи: Утроба",[2]="https://www.wowhead.com/classic/ru/npc=15571",["targets"]={},["kind"]="npc",["entityID"]=15571},{[1]="Выданный предмет: Арканитовый буй",[2]="https://www.wowhead.com/classic/ru/item=21136",["targets"]={},["kind"]="item",["entityID"]=21136}},["url"]="https://www.wowhead.com/classic/quest=8729#comments",["startTargets"]={{["name"]="Нарайн Причудень",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.24,["y"]=18.58,["kind"]="npc",["entityID"]=11811}}}
G.questHelp[8730]={["steps"]={"Примите задание у Ваеластраза в Логове Крыла Тьмы перед продолжением рейда.","За пять часов доберитесь до Нефариана, убейте его и заберите красный осколок. Подготовьте рейд до принятия задания."},["refs"]={{[1]="Начало: Валестраз Порочный",[2]="https://www.wowhead.com/classic/ru/npc=13020",["targets"]={{["name"]="Подход к подземелью: Валестраз Порочный находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=13020},{["name"]="Подход к подземелью: Валестраз Порочный находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=13020}},["kind"]="npc",["entityID"]=13020},{[1]="Сдача: Анахронос",[2]="https://www.wowhead.com/classic/ru/npc=15192",["targets"]={{["name"]="Анахронос",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.27,["y"]=50.03,["kind"]="npc",["entityID"]=15192}},["kind"]="npc",["entityID"]=15192},{[1]="Цель: Осколок красного скипетра",[2]="https://www.wowhead.com/classic/ru/item=21138",["targets"]={},["kind"]="item",["entityID"]=21138},{[1]="Источник добычи: Нефариан",[2]="https://www.wowhead.com/classic/ru/npc=11583",["targets"]={},["kind"]="npc",["entityID"]=11583}},["url"]="https://www.wowhead.com/classic/quest=8730#comments",["startTargets"]={{["name"]="Подход к подземелью: Валестраз Порочный находится внутри",["zone"]="Тлеющее ущелье",["zoneEN"]="Searing Gorge",["x"]=34.8,["y"]=85.3,["kind"]="entrance",["entityID"]=13020},{["name"]="Подход к подземелью: Валестраз Порочный находится внутри",["zone"]="Пылающие степи",["zoneEN"]="Burning Steppes",["x"]=29.4,["y"]=38.3,["kind"]="entrance",["entityID"]=13020}}}
G.questHelp[8733]={["steps"]={"После «Создания драконов» войдите в Храм Атал’Хаккара и доберитесь до зала Тени Эраникуса. При приближении к Тени появится Малфурион Ярость Бури.","Поговорите с Малфурионом и возьмите у него «Эраникус, Тиран Сна». Цель этого задания — найти агента Малфуриона: Лесного огонька у стен Дарнаса.","Выйдите из Дарнаса в Тельдрассил, от ворот поверните на север и найдите Лесного огонька примерно на 37.6, 47.9. Сдайте ему задание; только после этого он предложит отдельное следующее задание «Тиранда и Ремулос»."},["refs"]={{[1]="Начало: Малфурион Ярость Бури",[2]="https://www.wowhead.com/classic/ru/npc=15362",["targets"]={{["name"]="Подход к подземелью: Малфурион Ярость Бури находится внутри",["zone"]="Болото Печали",["zoneEN"]="Swamp of Sorrows",["x"]=69.9,["y"]=53.5,["kind"]="entrance",["entityID"]=15362}},["kind"]="npc",["entityID"]=15362},{[1]="Сдача: Лесной огонек",[2]="https://www.wowhead.com/classic/ru/npc=15624",["targets"]={{["name"]="Лесной огонек",["zone"]="Тельдрассил",["zoneEN"]="Teldrassil",["x"]=37.55,["y"]=47.92,["kind"]="npc",["entityID"]=15624}},["kind"]="npc",["entityID"]=15624}},["url"]="https://www.wowhead.com/classic/quest=8733#comments",["startTargets"]={{["name"]="Подход к подземелью: Малфурион Ярость Бури находится внутри",["zone"]="Болото Печали",["zoneEN"]="Swamp of Sorrows",["x"]=69.9,["y"]=53.5,["kind"]="entrance",["entityID"]=15362}}}
G.questHelp[8734]={["steps"]={"Возьмите «Тиранда и Ремулос» у Лесного огонька возле Дарнаса примерно на 37.6, 47.9. Это отдельное задание после «Эраникуса, Тирана Сна».","Отправляйтесь в Лунную поляну к Хранителю Ремулу примерно на 36.2, 41.8 и сдайте задание.","После сдачи Ремул предложит отдельное следующее задание «Порча Кошмара» на четыре фрагмента."},["refs"]={{[1]="Начало: Лесной огонек",[2]="https://www.wowhead.com/classic/ru/npc=15624",["targets"]={{["name"]="Лесной огонек",["zone"]="Тельдрассил",["zoneEN"]="Teldrassil",["x"]=37.55,["y"]=47.92,["kind"]="npc",["entityID"]=15624}},["kind"]="npc",["entityID"]=15624},{[1]="Сдача: Хранитель Ремул",[2]="https://www.wowhead.com/classic/ru/npc=11832",["targets"]={{["name"]="Хранитель Ремул",["zone"]="Лунная поляна",["zoneEN"]="Moonglade",["x"]=36.18,["y"]=41.79,["kind"]="npc",["entityID"]=11832}},["kind"]="npc",["entityID"]=11832}},["url"]="https://www.wowhead.com/classic/quest=8734#comments",["startTargets"]={{["name"]="Лесной огонек",["zone"]="Тельдрассил",["zoneEN"]="Teldrassil",["x"]=37.55,["y"]=47.92,["kind"]="npc",["entityID"]=15624}}}
G.questHelp[8735]={["steps"]={"Возьмите у Хранителя Ремула в Лунной поляне «Порчу Кошмара». Нужно собрать четыре разных фрагмента — по одному у каждого портала Изумрудного Сна.","Ясеневый лес, Тенистая Ветвь, примерно 93.3, 38.5: фрагмент добывается с элитных драконидов у портала.","Фералас, Ветвь Снов, примерно 51.5, 11.3: фрагмент добывается с элитных драконидов у портала.","Внутренние земли, Серадан, примерно 63.1, 24.5: фрагмент добывается с элитных драконидов у портала.","Сумеречный лес, Сумеречная роща, примерно 46, 38: при входе в область портала появляется Сумеречный Осквернитель; фрагмент добывается с него.","Собрав все четыре фрагмента, вернитесь к Хранителю Ремулу на 36.2, 41.8 в Лунной поляне."},["refs"]={{[1]="Начало: Хранитель Ремул",[2]="https://www.wowhead.com/classic/ru/npc=11832",["targets"]={{["name"]="Хранитель Ремул",["zone"]="Лунная поляна",["zoneEN"]="Moonglade",["x"]=36.18,["y"]=41.79,["kind"]="npc",["entityID"]=11832}},["kind"]="npc",["entityID"]=11832},{[1]="Цель: Фрагмент порчи Кошмара",[2]="https://www.wowhead.com/classic/ru/item=21147",["targets"]={{["name"]="Источник добычи: Изумрудон-страж ветвей",["zone"]="Ясеневый лес",["zoneEN"]="Ashenvale",["x"]=91.59,["y"]=38.95,["kind"]="npc",["entityID"]=12474},{["name"]="Источник добычи: Изумрудон-страж ветвей",["zone"]="Ясеневый лес",["zoneEN"]="Ashenvale",["x"]=91.52,["y"]=39,["kind"]="npc",["entityID"]=12474},{["name"]="Источник добычи: Изумрудон-страж ветвей",["zone"]="Ясеневый лес",["zoneEN"]="Ashenvale",["x"]=89.52,["y"]=39.69,["kind"]="npc",["entityID"]=12474},{["name"]="Источник добычи: Изумрудон-страж ветвей",["zone"]="Ясеневый лес",["zoneEN"]="Ashenvale",["x"]=92.69,["y"]=37.22,["kind"]="npc",["entityID"]=12474},{["name"]="Источник добычи: Изумрудон-хранитель деревьев",["zone"]="Ясеневый лес",["zoneEN"]="Ashenvale",["x"]=89.48,["y"]=39.63,["kind"]="npc",["entityID"]=12475},{["name"]="Источник добычи: Изумрудон-хранитель деревьев",["zone"]="Ясеневый лес",["zoneEN"]="Ashenvale",["x"]=92