]=11832}}}
G.questHelp[8736]={["steps"]={"Подготовьте группу перед запуском события у Ремула в Лунной поляне.","Защищайте Ночную Гавань и Ремула до прибытия Тиранды. Задача — очищение Эраникуса: не убивайте его и не допускайте гибели Ремула."},["refs"]={{[1]="Начало: Хранитель Ремул",[2]="https://www.wowhead.com/classic/ru/npc=11832",["targets"]={{["name"]="Хранитель Ремул",["zone"]="Лунная поляна",["zoneEN"]="Moonglade",["x"]=36.18,["y"]=41.79,["kind"]="npc",["entityID"]=11832}},["kind"]="npc",["entityID"]=11832}},["url"]="https://www.wowhead.com/classic/quest=8736#comments",["startTargets"]={{["name"]="Хранитель Ремул",["zone"]="Лунная поляна",["zoneEN"]="Moonglade",["x"]=36.18,["y"]=41.79,["kind"]="npc",["entityID"]=11832}}}
G.questHelp[8741]={["steps"]={"Получив зелёный осколок после события в Лунной поляне, вернитесь к Анахроносу в Танарис.","Передайте осколок. Для завершения Скипетра также нужны окончания красной и синей ветвей."},["refs"]={{[1]="Начало: Хранитель Ремул",[2]="https://www.wowhead.com/classic/ru/npc=11832",["targets"]={{["name"]="Хранитель Ремул",["zone"]="Лунная поляна",["zoneEN"]="Moonglade",["x"]=36.18,["y"]=41.79,["kind"]="npc",["entityID"]=11832}},["kind"]="npc",["entityID"]=11832},{[1]="Сдача: Анахронос",[2]="https://www.wowhead.com/classic/ru/npc=15192",["targets"]={{["name"]="Анахронос",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.27,["y"]=50.03,["kind"]="npc",["entityID"]=15192}},["kind"]="npc",["entityID"]=15192},{[1]="Выданный предмет: Осколок зеленого скипетра",[2]="https://www.wowhead.com/classic/ru/item=21139",["targets"]={},["kind"]="item",["entityID"]=21139}},["url"]="https://www.wowhead.com/classic/quest=8741#comments",["startTargets"]={{["name"]="Хранитель Ремул",["zone"]="Лунная поляна",["zoneEN"]="Moonglade",["x"]=36.18,["y"]=41.79,["kind"]="npc",["entityID"]=11832}}}
G.questHelp[8742]={["steps"]={"После завершения красной, зелёной и синей ветвей поговорите с Анахроносом у Пещер Времени, 65.3, 50.0.","Получите Скипетр Зыбучих песков и сохраните его для удара в гонг."},["refs"]={{[1]="Начало: Анахронос",[2]="https://www.wowhead.com/classic/ru/npc=15192",["targets"]={{["name"]="Анахронос",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.27,["y"]=50.03,["kind"]="npc",["entityID"]=15192}},["kind"]="npc",["entityID"]=15192}},["url"]="https://www.wowhead.com/classic/quest=8742#comments",["startTargets"]={{["name"]="Анахронос",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.27,["y"]=50.03,["kind"]="npc",["entityID"]=15192}},["serverNote"]="На Solo Progress перед гонгом дополнительно нужны 15 разных ресурсных заданий и 100 печатей по «Военным действиям»."}
G.questHelp[8745]={["steps"]={"После получения Скипетра завершите подготовку этапа и ударьте им в гонг у врат Ан’Киража, около 25.9, 91.0.","Поговорите с Джонатаном Богословом рядом с гонгом и выберите одну из четырёх наград."},["refs"]={{[1]="Начало: Джонатан Богослов",[2]="https://www.wowhead.com/classic/ru/npc=15693",["targets"]={{["name"]="Джонатан Богослов",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=25.94,["y"]=90.96,["kind"]="npc",["entityID"]=15693}},["kind"]="npc",["entityID"]=15693}},["url"]="https://www.wowhead.com/classic/quest=8745#comments",["startTargets"]={{["name"]="Джонатан Богослов",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=25.94,["y"]=90.96,["kind"]="npc",["entityID"]=15693}}}
G.questHelp[9121]={["steps"]={"При Уважении с Серебряным Рассветом обратитесь к Анджеле Досантос в Часовне Последней Надежды.","Принесите 5 чародейских кристаллов, 2 кристалла-источника, 1 сферу Праведности и 60 золотых. При более высокой репутации выбирается другой, более дешёвый вариант допуска."},["refs"]={{[1]="Начало: Верховный маг Анджела Досантос",[2]="https://www.wowhead.com/classic/ru/npc=16116",["targets"]={{["name"]="Верховный маг Анджела Досантос",["zone"]="Восточные Чумные земли",["zoneEN"]="Eastern Plaguelands",["x"]=81.52,["y"]=58.27,["kind"]="npc",["entityID"]=16116}},["kind"]="npc",["entityID"]=16116},{[1]="Цель: Чародейный кристалл",[2]="https://www.wowhead.com/classic/ru/item=12363",["targets"]={{["name"]="Источник добычи: Малая ториевая жила",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=40.3,["y"]=90.86,["kind"]="object",["entityID"]=324},{["name"]="Источник добычи: Малая ториевая жила",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=40.39,["y"]=79.93,["kind"]="object",["entityID"]=324},{["name"]="Источник добычи: Малая ториевая жила",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=43.66,["y"]=78.47,["kind"]="object",["entityID"]=324},{["name"]="Источник добычи: Малая ториевая жила",["zone"]="Силитус",["zoneEN"]="Silithus",["x"]=32.27,["y"]=83.77,["kind"]="object",["entityID"]=324},{["name"]="Источник добычи: Малая ториевая жила",["zone"]="Восточные Чумные земли",["zoneEN"]="Eastern Plaguelands",["x"]=56.08,["y"]=49.27,["kind"]="object",["entityID"]=324},{["name"]="Источник добычи: Малая ториевая жила",["zone"]="Восточные Чумные земли",["zoneEN"]="Eastern Plaguelands",["x"]=52.82,["y"]=43.8,["kind"]="object",["entityID"]=324},{["name"]="Источник добычи: Малая ториевая жила",["zone"]="Восточные Чумные земли",["zoneEN"]="Eastern Plaguelands",["x"]=47.37,["y"]=71.26,["kind"]="object",["entityID"]=324},{["name"]="Источник добычи: Малая ториевая жила",["zone"]="Восточные Чумные земли",["zoneEN"]="Eastern Plaguelands",["x"]=41.53,["y"]=84.06,["kind"]="