G.questHelp[9123]={["steps"]={"При Превознесении с Серебряным Рассветом поговорите с Анджелой Досантос в Часовне Последней Надежды.","Этот вариант допуска не требует материалов и оплаты. Все три одноимённых задания — альтернативы по репутации."},["refs"]={{[1]="Начало: Верховный маг Анджела Досантос",[2]="https://www.wowhead.com/classic/ru/npc=16116",["targets"]={{["name"]="Верховный маг Анджела Досантос",["zone"]="Восточные Чумные земли",["zoneEN"]="Eastern Plaguelands",["x"]=81.52,["y"]=58.27,["kind"]="npc",["entityID"]=16116}},["kind"]="npc",["entityID"]=16116}},["url"]="https://www.wowhead.com/classic/quest=9123#comments",["startTargets"]={{["name"]="Верховный маг Анджела Досантос",["zone"]="Восточные Чумные земли",["zoneEN"]="Eastern Plaguelands",["x"]=81.52,["y"]=58.27,["kind"]="npc",["entityID"]=16116}}}
G.questHelp[9630]={["steps"]={"Достигните Уважения с Аметистовым Оком и возьмите задание у Каражана.","В библиотеке Каражана найдите Вравиена. Пройдите разговоры с библиотекарями до убийства Тени Арана, иначе за дневником может потребоваться следующий заход."},["refs"]={{[1]="Начало: Верховный маг Альтур",[2]="https://www.wowhead.com/wotlk/ru/npc=17613",["targets"]={{["name"]="Верховный маг Альтур (место поиска)",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=47.28,["y"]=75.21,["kind"]="npc",["entityID"]=17613}},["kind"]="npc",["entityID"]=17613},{[1]="Сдача: Вравьен",[2]="https://www.wowhead.com/wotlk/ru/npc=16813",["targets"]={{["name"]="Подход к подземелью: Вравьен находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=16813}},["kind"]="npc",["entityID"]=16813}},["url"]="https://www.wowhead.com/wotlk/quest=9630#comments",["startTargets"]={{["name"]="Верховный маг Альтур (место поиска)",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=47.28,["y"]=75.21,["kind"]="npc",["entityID"]=17613}}}
G.questHelp[9631]={["steps"]={"Отнесите находку Калинне Латред в Зону 52, Пустоверть, примерно 32, 63.","Не ищите её в лесу Тероккар: старое название зоны в журнале и на страницах могло быть ошибочным."},["refs"]={{[1]="Начало: Верховный маг Альтур",[2]="https://www.wowhead.com/wotlk/ru/npc=17613",["targets"]={{["name"]="Верховный маг Альтур (место поиска)",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=47.28,["y"]=75.21,["kind"]="npc",["entityID"]=17613}},["kind"]="npc",["entityID"]=17613},{[1]="Сдача: Калинна Латред",[2]="https://www.wowhead.com/wotlk/ru/npc=17636",["targets"]={{["name"]="Калинна Латред",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=32.22,["y"]=63.6,["kind"]="npc",["entityID"]=17636}},["kind"]="npc",["entityID"]=17636},{[1]="Выданный предмет: Фрагмент обугленной кости",[2]="https://www.wowhead.com/wotlk/ru/item=24152",["targets"]={{["name"]="Источник добычи: Фрагмент обугленной кости",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=45,["y"]=78.96,["kind"]="object",["entityID"]=181963}},["kind"]="item",["entityID"]=24152},{[1]="Источник добычи: Фрагмент обугленной кости",[2]="https://www.wowhead.com/wotlk/ru/object=181963",["targets"]={{["name"]="Фрагмент обугленной кости",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=45,["y"]=78.96,["kind"]="object",["entityID"]=181963}},["kind"]="object",["entityID"]=181963}},["url"]="https://www.wowhead.com/wotlk/quest=9631#comments",["startTargets"]={{["name"]="Верховный маг Альтур (место поиска)",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=47.28,["y"]=75.21,["kind"]="npc",["entityID"]=17613}}}
G.questHelp[9637]={["steps"]={"В героических Сетеккских залах победите Темнопряда Сита; в героических Разрушенных залах — великого чернокнижника Пустоклята.","Заберите предметы с обоих первых боссов и верните Калинне. Для этих предметов полные зачистки обоих подземелий не обязательны."},["refs"]={{[1]="Начало: Калинна Латред",[2]="https://www.wowhead.com/wotlk/ru/npc=17636",["targets"]={{["name"]="Калинна Латред",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=32.22,["y"]=63.6,["kind"]="npc",["entityID"]=17636}},["kind"]="npc",["entityID"]=17636},{[1]="Цель: Книга Забытых Имен",[2]="https://www.wowhead.com/wotlk/ru/item=25461",["targets"]={},["kind"]="item",["entityID"]=25461},{[1]="Источник добычи: Darkweaver Syth (1)",[2]="https://www.wowhead.com/wotlk/ru/npc=20690",["targets"]={},["kind"]="npc",["entityID"]=20690},{[1]="Цель: Фолиант сумерек",[2]="https://www.wowhead.com/wotlk/ru/item=25462",["targets"]={},["kind"]="item",["entityID"]=25462},{[1]="Источник добычи: Grand Warlock Nethekurse (1)",[2]="https://www.wowhead.com/wotlk/ru/npc=20568",["targets"]={},["kind"]="npc",["entityID"]=20568}},["url"]="https://www.wowhead.com/wotlk/quest=9637#comments",["startTargets"]={{["name"]="Калинна Латред",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=32.22,["y"]=63.6,["kind"]="npc",["entityID"]=17636}}}
G.questHelp[9638]={["steps"]={"После Вравиена найдите Градава в той же библиотеке Каражана, в соседней нише.","Расчистите путь от патрулей и поговорите с ним, чтобы продолжить поиск дневника."},["refs"]={{[1]="Начало: Вравьен",[2]="https://www.wowhead.com/wotlk/ru/npc=16813",["targets"]={{["name"]="Подход к подземелью: Вравьен находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=16813}},["kind"]="npc",["entityID"]=16813},{[1]="Сдача: Градав",[2]="https://www.wowhead.com/wotlk/ru/npc=16814",["targets"]={{["name"]="Подход к подземелью: Градав находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=16814}},["kind"]="npc",["entityID"]=16814}},["url"]="https://www.wowhead.com/wotlk/quest=9638#comments",["startTargets"]={{["name"]="Подход к подземелью: Вравьен находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=16813}}}
G.questHelp[9639]={["steps"]={"Камсис находится дальше в том же библиотечном зале Каражана, возле большого пандуса.","Поговорите с ней и возьмите задание на Тень Арана до убийства босса."},["refs"]={{[1]="Начало: Градав",[2]="https://www.wowhead.com/wotlk/ru/npc=16814",["targets"]={{["name"]="Подход к подземелью: Градав находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=16814}},["kind"]="npc",["entityID"]=16814},{[1]="Сдача: Камсис",[2]="https://www.wowhead.com/wotlk/ru/npc=16815",["targets"]={{["name"]="Подход к подземелью: Камсис находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=16815}},["kind"]="npc",["entityID"]=16815}},["url"]="https://www.wowhead.com/wotlk/quest=9639#comments",["startTargets"]={{["name"]="Подход к подземелью: Градав находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=16814}}}
G.questHelp[9640]={["steps"]={"С активным заданием победите Тень Арана в Каражане и заберите дневник Медива.","Верните его Камсис. Если убить босса до принятия задания, дневник задним числом не появится."},["refs"]={{[1]="Начало: Камсис",[2]="https://www.wowhead.com/wotlk/ru/npc=16815",["targets"]={{["name"]="Подход к подземелью: Камсис находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=16815}},["kind"]="npc",["entityID"]=16815},{[1]="Цель: Дневник Медива",[2]="https://www.wowhead.com/wotlk/ru/item=23933",["targets"]={{["name"]="Подход к подземелью: Тень Арана находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=16524}},["kind"]="item",["entityID"]=23933},{[1]="Источник добычи: Тень Арана",[2]="https://www.wowhead.com/wotlk/ru/npc=16524",["targets"]={{["name"]="Подход к подземелью: Тень Арана находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=16524}},["kind"]="npc",["entityID"]=16524}},["url"]="https://www.wowhead.com/wotlk/quest=9640#comments",["startTargets"]={{["name"]="Подход к подземелью: Камсис находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=16815}}}
G.questHelp[9644]={["steps"]={"Получите Вороненую урну и вызовите Ночную погибель на Террасе Мастера в Каражане.","Возьмите «Дубину Кардеша» до боя, если одновременно проходите допуск в Змеиное святилище: от Ночной погибели нужен отдельный предмет."},["refs"]={{[1]="Начало: Калинна Латред",[2]="https://www.wowhead.com/wotlk/ru/npc=17636",["targets"]={{["name"]="Калинна Латред",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=32.22,["y"]=63.6,["kind"]="npc",["entityID"]=17636}},["kind"]="npc",["entityID"]=17636},{[1]="Сдача: Верховный маг Альтур",[2]="https://www.wowhead.com/wotlk/ru/npc=17613",["targets"]={{["name"]="Верховный маг Альтур (место поиска)",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=47.28,["y"]=75.21,["kind"]="npc",["entityID"]=17613}},["kind"]="npc",["entityID"]=17613},{[1]="Цель: Слабая чародейская сущность",[2]="https://www.wowhead.com/wotlk/ru/item=24139",["targets"]={{["name"]="Подход к подземелью: Ночная Погибель находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=17225}},["kind"]="item",["entityID"]=24139},{[1]="Источник добычи: Ночная Погибель",[2]="https://www.wowhead.com/wotlk/ru/npc=17225",["targets"]={{["name"]="Подход к подземелью: Ночная Погибель находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=17225}},["kind"]="npc",["entityID"]=17225}},["url"]="https://www.wowhead.com/wotlk/quest=9644#comments",["startTargets"]={{["name"]="Калинна Латред",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=32.22,["y"]=63.6,["kind"]="npc",["entityID"]=17636}},["serverNote"]="Solo Progress: урну держите в сумке, а для призыва нажимайте урну на полу Террасы Мастера. Не продавайте её по советам для официального Wrath."}
G.questHelp[9645]={["steps"]={"Доберитесь до Террасы Мастера в Каражане и используйте дневник Медива.","Пусть предмет использует один участник и только один раз: повторные одновременные запуски мешают событию. Дождитесь окончания сцены, а не только появления персонажей."},["refs"]={{[1]="Начало: Камсис",[2]="https://www.wowhead.com/wotlk/ru/npc=16815",["targets"]={{["name"]="Подход к подземелью: Камсис находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=16815}},["kind"]="npc",["entityID"]=16815},{[1]="Сдача: Верховный маг Альтур",[2]="https://www.wowhead.com/wotlk/ru/npc=17613",["targets"]={{["name"]="Верховный маг Альтур (место поиска)",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=47.28,["y"]=75.21,["kind"]="npc",["entityID"]=17613}},["kind"]="npc",["entityID"]=17613},{[1]="Выданный предмет: Дневник Медива",[2]="https://www.wowhead.com/wotlk/ru/item=23934",["targets"]={},["kind"]="item",["entityID"]=23934}},["url"]="https://www.wowhead.com/wotlk/quest=9645#comments",["startTargets"]={{["name"]="Подход к подземелью: Камсис находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=16815}}}
G.questHelp[9680]={["steps"]={"Снаружи Каражана найдите обугленную кость между входом и кладбищем, у подножия гор.","Перед сбором выйдите из рейдовой группы, иначе предмет может не засчитаться. Верните кость Альтуру."},["refs"]={{[1]="Начало: Верховный маг Альтур",[2]="https://www.wowhead.com/wotlk/ru/npc=17613",["targets"]={{["name"]="Верховный маг Альтур (место поиска)",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=47.28,["y"]=75.21,["kind"]="npc",["entityID"]=17613}},["kind"]="npc",["entityID"]=17613},{[1]="Цель: Фрагмент обугленной кости",[2]="https://www.wowhead.com/wotlk/ru/item=24152",["targets"]={{["name"]="Источник добычи: Фрагмент обугленной кости",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=45,["y"]=78.96,["kind"]="object",["entityID"]=181963}},["kind"]="item",["entityID"]=24152},{[1]="Источник добычи: Фрагмент обугленной кости",[2]="https://www.wowhead.com/wotlk/ru/object=181963",["targets"]={{["name"]="Фрагмент обугленной кости",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=45,["y"]=78.96,["kind"]="object",["entityID"]=181963}},["kind"]="object",["entityID"]=181963}},["url"]="https://www.wowhead.com/wotlk/quest=9680#comments",["startTargets"]={{["name"]="Верховный маг Альтур (место поиска)",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=47.28,["y"]=75.21,["kind"]="npc",["entityID"]=17613}}}
G.questHelp[9824]={["steps"]={"Возле Каражана спуститесь в Подвал Мастера: рядом находятся два входа, примерно 48, 78.","Один проход ведёт к пруду, другой — к колодцу. Используйте выданный кристалл у каждого источника воды и вернитесь к Альтуру."},["refs"]={{[1]="Начало: Верховный маг Альтур",[2]="https://www.wowhead.com/wotlk/ru/npc=17613",["targets"]={{["name"]="Верховный маг Альтур (место поиска)",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=47.28,["y"]=75.21,["kind"]="npc",["entityID"]=17613}},["kind"]="npc",["entityID"]=17613},{[1]="Выданный предмет: Кристалл ясновидения Аметистового Ока",[2]="https://www.wowhead.com/wotlk/ru/item=24474",["targets"]={},["kind"]="item",["entityID"]=24474}},["url"]="https://www.wowhead.com/wotlk/quest=9824#comments",["startTargets"]={{["name"]="Верховный маг Альтур (место поиска)",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=47.28,["y"]=75.21,["kind"]="npc",["entityID"]=17613}}}
G.questHelp[9825]={["steps"]={"Убивайте призраков в Подвале Мастера возле Каражана и собирайте призрачные сущности.","Это удобно делать вместе с измерениями у колодца и пруда. После сбора вернитесь к Альтуру."},["refs"]={{[1]="Начало: Верховный маг Альтур",[2]="https://www.wowhead.com/wotlk/ru/npc=17613",["targets"]={{["name"]="Верховный маг Альтур (место поиска)",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=47.28,["y"]=75.21,["kind"]="npc",["entityID"]=17613}},["kind"]="npc",["entityID"]=17613},{[1]="Цель: Призрачная сущность",[2]="https://www.wowhead.com/wotlk/ru/item=24480",["targets"]={{["name"]="Источник добычи: Беспокойный дух",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=54.4,["y"]=80.74,["kind"]="npc",["entityID"]=7370},{["name"]="Источник добычи: Беспокойный дух",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=54.66,["y"]=78.4,["kind"]="npc",["entityID"]=7370},{["name"]="Источник добычи: Беспокойный дух",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=53.5,["y"]=78.36,["kind"]="npc",["entityID"]=7370},{["name"]="Источник добычи: Беспокойный дух",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=51.97,["y"]=78.25,["kind"]="npc",["entityID"]=7370},{["name"]="Источник добычи: Завывающий призрак",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=52.75,["y"]=79.44,["kind"]="npc",["entityID"]=12377},{["name"]="Источник добычи: Завывающий призрак",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=54.58,["y"]=82.41,["kind"]="npc",["entityID"]=12377},{["name"]="Источник добычи: Завывающий призрак",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=54.58,["y"]=81.48,["kind"]="npc",["entityID"]=12377},{["name"]="Источник добычи: Завывающий призрак",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=49.71,["y"]=79.02,["kind"]="npc",["entityID"]=12377},{["name"]="Источник добычи: Проклятая душа",["zone"]="Пе