G.questHelp[9826]={["steps"]={"После двух заданий у Каражана отправляйтесь к верховному магу Седрику у старого Даларана в Альтеракских горах, примерно 15, 54.","Речь о старом Даларане возле озера, а не о городе в Нордсколе."},["refs"]={{[1]="Начало: Верховный маг Альтур",[2]="https://www.wowhead.com/wotlk/ru/npc=17613",["targets"]={{["name"]="Верховный маг Альтур (место поиска)",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=47.28,["y"]=75.21,["kind"]="npc",["entityID"]=17613}},["kind"]="npc",["entityID"]=17613},{[1]="Сдача: Верховный маг Седрик",[2]="https://www.wowhead.com/wotlk/ru/npc=18165",["targets"]={{["name"]="Верховный маг Седрик",["zone"]="Альтеракские горы",["zoneEN"]="Alterac Mountains",["x"]=15.61,["y"]=54.58,["kind"]="npc",["entityID"]=18165}},["kind"]="npc",["entityID"]=18165},{[1]="Выданный предмет: Донесение Альтура",[2]="https://www.wowhead.com/wotlk/ru/item=24482",["targets"]={},["kind"]="item",["entityID"]=24482}},["url"]="https://www.wowhead.com/wotlk/quest=9826#comments",["startTargets"]={{["name"]="Верховный маг Альтур (место поиска)",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=47.28,["y"]=75.21,["kind"]="npc",["entityID"]=17613}}}
G.questHelp[9829]={["steps"]={"Передайте сообщение Кадгару на Террасе Света в Шаттрате.","Возьмите у него задание на первый фрагмент ключа Каражана."},["refs"]={{[1]="Начало: Верховный маг Седрик",[2]="https://www.wowhead.com/wotlk/ru/npc=18165",["targets"]={{["name"]="Верховный маг Седрик",["zone"]="Альтеракские горы",["zoneEN"]="Alterac Mountains",["x"]=15.61,["y"]=54.58,["kind"]="npc",["entityID"]=18165}},["kind"]="npc",["entityID"]=18165},{[1]="Сдача: Кадгар",[2]="https://www.wowhead.com/wotlk/ru/npc=18166",["targets"]={{["name"]="Кадгар",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=54.75,["y"]=44.32,["kind"]="npc",["entityID"]=18166}},["kind"]="npc",["entityID"]=18166}},["url"]="https://www.wowhead.com/wotlk/quest=9829#comments",["startTargets"]={{["name"]="Верховный маг Седрик",["zone"]="Альтеракские горы",["zoneEN"]="Alterac Mountains",["x"]=15.61,["y"]=54.58,["kind"]="npc",["entityID"]=18165}}}
G.questHelp[9831]={["steps"]={"В Тёмном лабиринте доберитесь до зала Бормотуна. Контейнер стоит слева у края его площадки.","Взаимодействие вызывает хранителя фрагмента: победите его и заберите фрагмент ключа, затем вернитесь к Кадгару."},["refs"]={{[1]="Начало: Кадгар",[2]="https://www.wowhead.com/wotlk/ru/npc=18166",["targets"]={{["name"]="Кадгар",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=54.75,["y"]=44.32,["kind"]="npc",["entityID"]=18166}},["kind"]="npc",["entityID"]=18166},{[1]="Цель: Первый фрагмент ключа",[2]="https://www.wowhead.com/wotlk/ru/item=24514",["targets"]={},["kind"]="item",["entityID"]=24514},{[1]="Источник добычи: Страж первого фрагмента",[2]="https://www.wowhead.com/wotlk/ru/npc=22890",["targets"]={},["kind"]="npc",["entityID"]=22890}},["url"]="https://www.wowhead.com/wotlk/quest=9831#comments",["startTargets"]={{["name"]="Кадгар",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=54.75,["y"]=44.32,["kind"]="npc",["entityID"]=18166}}}
G.questHelp[9832]={["steps"]={"В Паровом подземелье второй контейнер находится под водой возле первого босса.","В Аркатраце найдите третий контейнер. Каждый контейнер вызывает хранителя: фрагмент нужно взять с него, а не просто нажать на ёмкость.","Принесите оба фрагмента Кадгару."},["refs"]={{[1]="Начало: Кадгар",[2]="https://www.wowhead.com/wotlk/ru/npc=18166",["targets"]={{["name"]="Кадгар",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=54.75,["y"]=44.32,["kind"]="npc",["entityID"]=18166}},["kind"]="npc",["entityID"]=18166},{[1]="Цель: Второй фрагмент ключа",[2]="https://www.wowhead.com/wotlk/ru/item=24487",["targets"]={},["kind"]="item",["entityID"]=24487},{[1]="Источник добычи: Страж второго фрагмента",[2]="https://www.wowhead.com/wotlk/ru/npc=22891",["targets"]={},["kind"]="npc",["entityID"]=22891},{[1]="Цель: Третий фрагмент ключа",[2]="https://www.wowhead.com/wotlk/ru/item=24488",["targets"]={},["kind"]="item",["entityID"]=24488},{[1]="Источник добычи: Страж третьего фрагмента",[2]="https://www.wowhead.com/wotlk/ru/npc=22892",["targets"]={},["kind"]="npc",["entityID"]=22892}},["url"]="https://www.wowhead.com/wotlk/quest=9832#comments",["startTargets"]={{["name"]="Кадгар",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=54.75,["y"]=44.32,["kind"]="npc",["entityID"]=18166}}}
G.questHelp[9836]={["steps"]={"Пройдите событие защиты Медива в Чёрных топях, в Пещерах Времени.","После завершения поговорите с Медивом для подтверждения ключа. Простого входа в подземелье недостаточно."},["refs"]={{[1]="Начало: Кадгар",[2]="https://www.wowhead.com/wotlk/ru/npc=18166",["targets"]={{["name"]="Кадгар",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=54.75,["y"]=44.32,["kind"]="npc",["entityID"]=18166}},["kind"]="npc",["entityID"]=18166},{[1]="Сдача: Медив",[2]="https://www.wowhead.com/wotlk/ru/npc=15608",["targets"]={{["name"]="Подход к подземелью: Медив находится внутри",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.7,["y"]=49.8,["kind"]="entrance",["entityID"]=15608}},["kind"]="npc",["entityID"]=15608},{[1]="Выданный предмет: Восстановленный ключ ученика",[2]="https://www.wowhead.com/wotlk/ru/item=24489",["targets"]={},["kind"]="item",["entityID"]=24489}},["url"]="https://www.wowhead.com/wotlk/quest=9836#comments",["startTargets"]={{["name"]="Кадгар",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=54.75,["y"]=44.32,["kind"]="npc",["entityID"]=18166}}}
G.questHelp[9837]={["steps"]={"Вернитесь с подтверждённым ключом к Кадгару в Шаттрат.","После сдачи получите хозяйский ключ Каражана."},["refs"]={{[1]="Начало: Медив",[2]="https://www.wowhead.com/wotlk/ru/npc=15608",["targets"]={{["name"]="Подход к подземелью: Медив находится внутри",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.7,["y"]=49.8,["kind"]="entrance",["entityID"]=15608}},["kind"]="npc",["entityID"]=15608},{[1]="Сдача: Кадгар",[2]="https://www.wowhead.com/wotlk/ru/npc=18166",["targets"]={{["name"]="Кадгар",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=54.75,["y"]=44.32,["kind"]="npc",["entityID"]=18166}},["kind"]="npc",["entityID"]=18166}},["url"]="https://www.wowhead.com/wotlk/quest=9837#comments",["startTargets"]={{["name"]="Подход к подземелью: Медив находится внутри",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.7,["y"]=49.8,["kind"]="entrance",["entityID"]=15608}}}
G.questHelp[9838]={["steps"]={"Вернитесь к верховному магу Альтуру у ворот Каражана, примерно 47, 76.","Это завершающий разговор с Аметистовым Оком, а не новый поиск фрагментов."},["refs"]={{[1]="Начало: Кадгар",[2]="https://www.wowhead.com/wotlk/ru/npc=18166",["targets"]={{["name"]="Кадгар",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=54.75,["y"]=44.32,["kind"]="npc",["entityID"]=18166}},["kind"]="npc",["entityID"]=18166},{[1]="Сдача: Верховный маг Альтур",[2]="https://www.wowhead.com/wotlk/ru/npc=17613",["targets"]={{["name"]="Верховный маг Альтур (место поиска)",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=47.28,["y"]=75.21,["kind"]="npc",["entityID"]=17613}},["kind"]="npc",["entityID"]=17613}},["url"]="https://www.wowhead.com/wotlk/quest=9838#comments",["startTargets"]={{["name"]="Кадгар",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=54.75,["y"]=44.32,["kind"]="npc",["entityID"]=18166}}}
G.questHelp[10091]={["steps"]={"Возьмите задание у шпиона Тогуна внутри Тёмного лабиринта после первого босса. Соберите 5 устройств душ: это предметы обстановки, а не добыча с противников.","Ищите устройства у палаток в залах второго и третьего боссов и по пути к Бормотуну. Сдайте их Мелисе Высокой Короне в Шаттрате."},["refs"]={{[1]="Начало: Шпион То'гун",[2]="https://www.wowhead.com/tbc/ru/npc=18891",["targets"]={{["name"]="Подход к подземелью: Шпион То'гун находится внутри",["zone"]="Лес Тероккар",["zoneEN"]="Terokkar Forest",["x"]=39.6,["y"]=71,["kind"]="entrance",["entityID"]=18891}},["kind"]="npc",["entityID"]=18891},{[1]="Сдача: Предводительница шпионов Мелиса Высокий Венец",[2]="https://www.wowhead.com/tbc/ru/npc=18893",["targets"]={{["name"]="Предводительница шпионов Мелиса Высокий Венец",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=50.24,["y"]=45.36,["kind"]="npc",["entityID"]=18893}},["kind"]="npc",["entityID"]=18893},{[1]="Цель: Инструмент души",[2]="https://www.wowhead.com/tbc/ru/item=27480",["targets"]={{["name"]="Подход к подземелью: Инструмент души находится внутри",["zone"]="Лес Тероккар",["zoneEN"]="Terokkar Forest",["x"]=39.6,["y"]=71,["kind"]="entrance",["entityID"]=182940}},["kind"]="item",["entityID"]=27480},{[1]="Источник добычи: Инструмент души",[2]="https://www.wowhead.com/tbc/ru/object=182940",["targets"]={{["name"]="Подход к подземелью: Инструмент души находится внутри",["zone"]="Лес Тероккар",["zoneEN"]="Terokkar Forest",["x"]=39.6,["y"]=71,["kind"]="entrance",["entityID"]=182940}},["kind"]="object",["entityID"]=182940}},["url"]="https://www.wowhead.com/tbc/quest=10091#comments",["startTargets"]={{["name"]="Подход к подземелью: Шпион То'гун находится внутри",["zone"]="Лес Тероккар",["zoneEN"]="Terokkar Forest",["x"]=39.6,["y"]=71,["kind"]="entrance",["entityID"]=18891}}}
G.questHelp[10094]={["steps"]={"Возьмите задание у Махфууна у входа в Тёмный лабиринт. Прочитайте парящую книгу возле Великого мастера Ворпила после зачистки его площадки.","У книги сразу возьмите «В самое сердце Лабиринта» до боя с Бормотуном."},["refs"]={{[1]="Начало: Боевой командир Мафуун",[2]="https://www.wowhead.com/tbc/ru/npc=19542",["targets"]={{["name"]="Боевой командир Мафуун",["zone"]="Лес Тероккар",["zoneEN"]="Terokkar Forest",["x"]=40.04,["y"]=72.16,["kind"]="npc",["entityID"]=19542}},["kind"]="npc",["entityID"]=19542},{[1]="Сдача: Кодекс Крови",[2]="https://www.wowhead.com/tbc/ru/object=182947",["targets"]={{["name"]="Подход к подземелью: Кодекс Крови находится внутри",["zone"]="Лес Тероккар",["zoneEN"]="Terokkar Forest",["x"]=39.6,["y"]=71,["kind"]="entrance",["entityID"]=182947}},["kind"]="object",["entityID"]=182947}},["url"]="https://www.wowhead.com/tbc/quest=10094#comments",["startTargets"]={{["name"]="Боевой командир Мафуун",["zone"]="Лес Тероккар",["zoneEN"]="Terokkar Forest",["x"]=40.04,["y"]=72.16,["kind"]="npc",["entityID"]=19542}}}
G.questHelp[10095]={["steps"]={"Сначала возьмите задание у Кодекса Крови, затем победите Бормотуна. Сдайте его Мелисе Высокой Короне на Террасе Света в Шаттрате. Совместите бой с походом за первым фрагментом ключа Каражана."},["refs"]={{[1]="Начало: Кодекс Крови",[2]="https://www.wowhead.com/tbc/ru/object=182947",["targets"]={{["name"]="Подход к подземелью: Кодекс Крови находится внутри",["zone"]="Лес Тероккар",["zoneEN"]="Terokkar Forest",["x"]=39.6,["y"]=71,["kind"]="entrance",["entityID"]=182947}},["kind"]="object",["entityID"]=182947},{[1]="Сдача: Предводительница шпионов Мелиса Высокий Венец",[2]="https://www.wowhead.com/tbc/ru/npc=18893",["targets"]={{["name"]="Предводительница шпионов Мелиса Высокий Венец",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=50.24,["y"]=45.36,["kind"]="npc",["entityID"]=18893}},["kind"]="npc",["entityID"]=18893},{[1]="Цель: Бормотун",[2]="https://www.wowhead.com/tbc/ru/npc=18708",["targets"]={{["name"]="Подход к подземелью: Бормотун находится внутри",["zone"]="Лес Тероккар",["zoneEN"]="Terokkar Forest",["x"]=39.6,["y"]=71,["kind"]="entrance",["entityID"]=18708}},["kind"]="npc",["entityID"]=18708}},["url"]="https://www.wowhead.com/tbc/quest=10095#comments",["startTargets"]={{["name"]="Подход к подземелью: Кодекс Крови находится внутри",["zone"]="Лес Тероккар",["zoneEN"]="Terokkar Forest",["x"]=39.6,["y"]=71,["kind"]="entrance",["entityID"]=182947}}}
G.questHelp[10177]={["steps"]={"До похода в Тёмный лабиринт возьмите задание у Мелисы Высокой Короны в Шаттрате. У входа сдайте его Махфууну и возьмите «Кодекс Крови». Если продолжение уже взято или пройдено, вводное поручение может не предлагаться."},["refs"]={{[1]="Начало: Предводительница шпионов Мелиса Высокий Венец",[2]="https://www.wowhead.com/tbc/ru/npc=18893",["targets"]={{["name"]="Предводительница шпионов Мелиса Высокий Венец",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=50.24,["y"]=45.36,["kind"]="npc",["entityID"]=18893}},["kind"]="npc",["entityID"]=18893},{[1]="Сдача: Боевой командир Мафуун",[2]="https://www.wowhead.com/tbc/ru/npc=19542",["targets"]={{["name"]="Боевой командир Мафуун",["zone"]="Лес Тероккар",["zoneEN"]="Terokkar Forest",["x"]=40.04,["y"]=72.16,["kind"]="npc",["entityID"]=19542}},["kind"]="npc",["entityID"]=19542}},["url"]="https://www.wowhead.com/tbc/quest=10177#comments",["startTargets"]={{["name"]="Предводительница шпионов Мелиса Высокий Венец",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=50.24,["y"]=45.36,["kind"]="npc",["entityID"]=18893}}}
G.questHelp[10178]={["steps"]={"Перед входом в Тёмный лабиринт возьмите поручение у Грикты. После первого босса найдите шпиона Тогуна в боковом коридоре и поговорите с ним.","Сразу возьмите у него «Устройства душ», чтобы собирать их по дальнейшему пути."},["refs"]={{[1]="Начало: Шпион Грик'та",[2]="https://www.wowhead.com/tbc/ru/npc=19496",["targets"]={{["name"]="Шпион Грик'та",["zone"]="Лес Тероккар",["zoneEN"]="Terokkar Forest",["x"]=39.94,["y"]=72.28,["kind"]="npc",["entityID"]=19496}},["kind"]="npc",["entityID"]=19496},{[1]="Сдача: Шпион То'гун",[2]="https://www.wowhead.com/tbc/ru/npc=18891",["targets"]={{["name"]="Подход к подземелью: Шпион То'гун находится внутри",["zone"]="Лес Тероккар",["zoneEN"]="Terokkar Forest",["x"]=39.6,["y"]=71,["kind"]="entrance",["entityID"]=18891}},["kind"]="npc",["entityID"]=18891}},["url"]="https://www.wowhead.com/tbc/quest=10178#comments",["startTargets"]={{["name"]="Шпион Грик'та",["zone"]="Лес Тероккар",["zoneEN"]="Terokkar Forest",["x"]=39.94,["y"]=72.28,["kind"]="npc",["entityID"]=19496}}}
G.questHelp[10205]={["steps"]={"Победите Несаада и вернитесь к Кайджи на Площадь 52. Следующее задание направит вас к Гаруджу."},["refs"]={{[1]="Начало: Ловчий Пустоты Кай'джи",[2]="https://www.wowhead.com/tbc/ru/npc=19880",["targets"]={{["name"]="Ловчий Пустоты Кай'джи",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=32.44,["y"]=64.21,["kind"]="npc",["entityID"]=19880}},["kind"]="npc",["entityID"]=19880},{[1]="Цель: Астральный налетчик Несаад",[2]="https://www.wowhead.com/tbc/ru/npc=19641",["targets"]={{["name"]="Астральный налетчик Несаад",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=28.36,["y"]=79.45,["kind"]="npc",["entityID"]=19641}},["kind"]="npc",["entityID"]=19641}},["url"]="https://www.wowhead.com/tbc/quest=10205#comments",["startTargets"]={{["name"]="Ловчий Пустоты Кай'джи",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=32.44,["y"]=64.21,["kind"]="npc",["entityID"]=19880}}}
G.questHelp[10262]={["steps"]={"Убивайте эфириалов Заксис и соберите 10 знаков отличия. Вернитесь к Кайджи на Площадь 52; повторная сдача знаков для репутации не нужна для продолжения ключа."},["refs"]={{[1]="Начало: Ловчий Пустоты Кай'джи",[2]="https://www.wowhead.com/tbc/ru/npc=19880",["targets"]={{["name"]="Ловчий Пустоты Кай'джи",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=32.44,["y"]=64.21,["kind"]="npc",["entityID"]=19880}},["kind"]="npc",["entityID"]=19880},{[1]="Цель: Знак отличия братства Заксис",[2]="https://www.wowhead.com/tbc/ru/item=29209",["targets"]={{["name"]="Источник добычи: Налетчик из братства Заксис",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=31.88,["y"]=74.98,["kind"]="npc",["entityID"]=18875},{["name"]="Источник добычи: Налетчик из братства Заксис",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=31.1,["y"]=75.7,["kind"]="npc",["entityID"]=18875},{["name"]="Источник добычи: Налетчик из братства Заксис",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=30.96,["y"]=75.2,["kind"]="npc",["entityID"]=18875},{["name"]="Источник добычи: Налетчик из братства Заксис",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=29.93,["y"]=74.74,["kind"]="npc",["entityID"]=18875},{["name"]="Источник добычи: Астральный налетчик Несаад",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=28.36,["y"]=79.45,["kind"]="npc",["entityID"]=19641},{["name"]="Источник добычи: Ловчий из братства Заксис",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=30.22,["y"]=74.97,["kind"]="npc",["entityID"]=19642},{["name"]="Источник добычи: Ловчий из братства Заксис",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=30.36,["y"]=78.22,["kind"]="npc",["entityID"]=19642},{["name"]="Источник добычи: Ловчий из братства Заксис",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=30.29,["y"]=78.27,["kind"]="npc",["entityID"]=19642},{["name"]="Источник добычи: Ловчий из братства Заксис",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=29.17,["y"]=78.44