G.questHelp[10265]={["steps"]={"Возьмите задание у Кайджи на Площади 52 в Пустоверти (с 67 уровня). Добудьте артефакт в руинах Арклон и вернитесь к нему. Это начало цепочки ключа Аркатраца."},["refs"]={{[1]="Начало: Ловчий Пустоты Кай'джи",[2]="https://www.wowhead.com/tbc/ru/npc=19880",["targets"]={{["name"]="Ловчий Пустоты Кай'джи",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=32.44,["y"]=64.21,["kind"]="npc",["entityID"]=19880}},["kind"]="npc",["entityID"]=19880},{[1]="Цель: Кристалл-артефакт Арклона",[2]="https://www.wowhead.com/tbc/ru/item=28829",["targets"]={{["name"]="Источник добычи: Пентатрон",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=42.46,["y"]=72.75,["kind"]="npc",["entityID"]=20215}},["kind"]="item",["entityID"]=28829},{[1]="Источник добычи: Пентатрон",[2]="https://www.wowhead.com/tbc/ru/npc=20215",["targets"]={{["name"]="Пентатрон",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=42.46,["y"]=72.75,["kind"]="npc",["entityID"]=20215}},["kind"]="npc",["entityID"]=20215}},["url"]="https://www.wowhead.com/tbc/quest=10265#comments",["startTargets"]={{["name"]="Ловчий Пустоты Кай'джи",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=32.44,["y"]=64.21,["kind"]="npc",["entityID"]=19880}}}
G.questHelp[10266]={["steps"]={"Найдите Гаруджа на Центральной стоянке внутри экокупола Срединных земель в Пустоверти. Сдайте поручение и возьмите сбор оборудования."},["refs"]={{[1]="Начало: Ловчий Пустоты Кай'джи",[2]="https://www.wowhead.com/tbc/ru/npc=19880",["targets"]={{["name"]="Ловчий Пустоты Кай'джи",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=32.44,["y"]=64.21,["kind"]="npc",["entityID"]=19880}},["kind"]="npc",["entityID"]=19880},{[1]="Сдача: Гарудж",[2]="https://www.wowhead.com/tbc/ru/npc=20066",["targets"]={{["name"]="Гарудж",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=46.67,["y"]=56.95,["kind"]="npc",["entityID"]=20066}},["kind"]="npc",["entityID"]=20066}},["url"]="https://www.wowhead.com/tbc/quest=10266#comments",["startTargets"]={{["name"]="Ловчий Пустоты Кай'джи",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=32.44,["y"]=64.21,["kind"]="npc",["entityID"]=19880}}}
G.questHelp[10267]={["steps"]={"Соберите 10 серых ящиков геодезического оборудования у Мана-горна Дуро в Пустоверти: они стоят вдоль стен внутри здания и снаружи.","Верните оборудование Гаруджу в экокупол Срединных земель."},["refs"]={{[1]="Начало: Гарудж",[2]="https://www.wowhead.com/tbc/ru/npc=20066",["targets"]={{["name"]="Гарудж",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=46.67,["y"]=56.95,["kind"]="npc",["entityID"]=20066}},["kind"]="npc",["entityID"]=20066},{[1]="Цель: Ящик с геодезическим снаряжением",[2]="https://www.wowhead.com/tbc/ru/item=28913",["targets"]={{["name"]="Источник добычи: Ящик с геодезическим снаряжением",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=60.15,["y"]=66.45,["kind"]="object",["entityID"]=184031},{["name"]="Источник добычи: Ящик с геодезическим снаряжением",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=60.08,["y"]=65.98,["kind"]="object",["entityID"]=184031},{["name"]="Источник добычи: Ящик с геодезическим снаряжением",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=60.08,["y"]=67.23,["kind"]="object",["entityID"]=184031},{["name"]="Источник добычи: Ящик с геодезическим снаряжением",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=59.92,["y"]=65.65,["kind"]="object",["entityID"]=184031}},["kind"]="item",["entityID"]=28913},{[1]="Источник добычи: Ящик с геодезическим снаряжением",[2]="https://www.wowhead.com/tbc/ru/object=184031",["targets"]={{["name"]="Ящик с геодезическим снаряжением",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=60.15,["y"]=66.45,["kind"]="object",["entityID"]=184031},{["name"]="Ящик с геодезическим снаряжением",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=60.08,["y"]=65.98,["kind"]="object",["entityID"]=184031},{["name"]="Ящик с геодезическим снаряжением",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=60.08,["y"]=67.23,["kind"]="object",["entityID"]=184031},{["name"]="Ящик с геодезическим снаряжением",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=59.92,