G.questHelp[10268]={["steps"]={"Доставьте оборудование проекции принца Харамада на Штормовую Вершину в Пустоверти. Возьмите прибор для следующего задания."},["refs"]={{[1]="Начало: Гарудж",[2]="https://www.wowhead.com/tbc/ru/npc=20066",["targets"]={{["name"]="Гарудж",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=46.67,["y"]=56.95,["kind"]="npc",["entityID"]=20066}},["kind"]="npc",["entityID"]=20066},{[1]="Сдача: Проекция принца нексуса Харамада",[2]="https://www.wowhead.com/tbc/ru/npc=20084",["targets"]={{["name"]="Проекция принца нексуса Харамада",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=45.87,["y"]=35.96,["kind"]="npc",["entityID"]=20084}},["kind"]="npc",["entityID"]=20084},{[1]="Выданный предмет: Геодезическое снаряжение",[2]="https://www.wowhead.com/tbc/ru/item=28934",["targets"]={},["kind"]="item",["entityID"]=28934}},["url"]="https://www.wowhead.com/tbc/quest=10268#comments",["startTargets"]={{["name"]="Гарудж",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=46.67,["y"]=56.95,["kind"]="npc",["entityID"]=20066}}}
G.questHelp[10269]={["steps"]={"Используйте прибор триангуляции у первой точки, примерно 66, 33, и дождитесь зачёта.","После зачёта поговорите с Дилером Хаззином на заставе Протектората, примерно 58, 31."},["refs"]={{[1]="Начало: Проекция принца нексуса Харамада",[2]="https://www.wowhead.com/tbc/ru/npc=20084",["targets"]={{["name"]="Проекция принца нексуса Харамада",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=45.87,["y"]=35.96,["kind"]="npc",["entityID"]=20084}},["kind"]="npc",["entityID"]=20084},{[1]="Сдача: Делец Хаззин",[2]="https://www.wowhead.com/tbc/ru/npc=20092",["targets"]={{["name"]="Делец Хаззин",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=58.35,["y"]=31.26,["kind"]="npc",["entityID"]=20092}},["kind"]="npc",["entityID"]=20092},{[1]="Выданный предмет: Триангуляционный прибор",[2]="https://www.wowhead.com/tbc/ru/item=28962",["targets"]={},["kind"]="item",["entityID"]=28962}},["url"]="https://www.wowhead.com/tbc/quest=10269#comments",["startTargets"]={{["name"]="Проекция принца нексуса Харамада",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=45.87,["y"]=35.96,["kind"]="npc",["entityID"]=20084}}}
G.questHelp[10275]={["steps"]={"Используйте второй прибор триангуляции у точки примерно 28, 41 и дождитесь зачёта.","Сдайте задание Тулуману Торговцу Ветром на пристани Тулумана, примерно 35, 38."},["refs"]={{[1]="Начало: Делец Хаззин",[2]="https://www.wowhead.com/tbc/ru/npc=20092",["targets"]={{["name"]="Делец Хаззин",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=58.35,["y"]=31.26,["kind"]="npc",["entityID"]=20092}},["kind"]="npc",["entityID"]=20092},{[1]="Сдача: Тулуман Торговец Ветром",[2]="https://www.wowhead.com/tbc/ru/npc=20112",["targets"]={{["name"]="Тулуман Торговец Ветром",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=34.62,["y"]=37.95,["kind"]="npc",["entityID"]=20112}},["kind"]="npc",["entityID"]=20112},{[1]="Выданный предмет: Триангуляционный прибор",[2]="https://www.wowhead.com/tbc/ru/item=29018",["targets"]={},["kind"]="item",["entityID"]=29018}},["url"]="https://www.wowhead.com/tbc/quest=10275#comments",["startTargets"]={{["name"]="Делец Хаззин",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=58.35,["y"]=31.26,["kind"]="npc",["entityID"]=20092}}}
G.questHelp[10276]={["steps"]={"Победите Кулутаса примерно у 53, 21 и заберите кристалл Ата'мала.","Доставьте кристалл проекции принца Харамада на Штормовую Вершину, примерно 46, 36. Следующее поручение ведёт в Шаттрат."},["refs"]={{[1]="Начало: Тулуман Торговец Ветром",[2]="https://www.wowhead.com/tbc/ru/npc=20112",["targets"]={{["name"]="Тулуман Торговец Ветром",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=34.62,["y"]=37.95,["kind"]="npc",["entityID"]=20112}},["kind"]="npc",["entityID"]=20112},{[1]="Сдача: Проекция принца нексуса Харамада",[2]="https://www.wowhead.com/tbc/ru/npc=20084",["targets"]={{["name"]="Проекция принца нексуса Харамада",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=45.87,["y"]=35.96,["kind"]="npc",["entityID"]=20084}},["kind"]="npc",["entityID"]=20084},{[1]="Цель: Кристалл Ата'мала",[2]="https://www.wowhead.com/tbc/ru/item=29026",["targets"]={{["name"]="Источник добычи: Кулутас",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=53.51,["y"]=21.53,["kind"]="npc",["entityID"]=20138}},["kind"]="item",["entityID"]=29026},{[1]="Источник добычи: Кулутас",[2]="https://www.wowhead.com/tbc/ru/npc=20138",["targets"]={{["name"]="Кулутас",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=53.51,["y"]=21.53,["kind"]="npc",["entityID"]=20138}},["kind"]="npc",["entityID"]=20138}},["url"]="https://www.wowhead.com/tbc/quest=10276#comments",["startTargets"]={{["name"]="Тулуман Торговец Ветром",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=34.62,["y"]=37.95,["kind"]="npc",["entityID"]=20112}}}
G.questHelp[10277]={["steps"]={"Примите экскурсию по Пещерам Времени и следуйте за хранительницей.","Не убегайте вперёд: дождитесь окончания рассказа и вернитесь к Андорму."},["refs"]={{[1]="Начало: Андорму",[2]="https://www.wowhead.com/wotlk/ru/npc=20130",["targets"]={{["name"]="Андорму",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=58.43,["y"]=54.28,["kind"]="npc",["entityID"]=20130}},["kind"]="npc",["entityID"]=20130}},["url"]="https://www.wowhead.com/wotlk/quest=10277#comments",["startTargets"]={{["name"]="Андорму",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=58.43,["y"]=54.28,["kind"]="npc",["entityID"]=20130}}}
G.questHelp[10279]={["steps"]={"В тоннеле Пещер Времени в Танарисе поговорите с дружелюбным драконом, предварительно спешившись.","Спуститесь к Андорму в глубине пещер и сдайте задание."},["refs"]={{[1]="Начало: Распорядитель времени",[2]="https://www.wowhead.com/tbc/ru/npc=20142",["targets"]={{["name"]="Распорядитель времени",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=66.02,["y"]=49.7,["kind"]="npc",["entityID"]=20142}},["kind"]="npc",["entityID"]=20142},{[1]="Сдача: Андорму",[2]="https://www.wowhead.com/tbc/ru/npc=20130",["targets"]={{["name"]="Андорму",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=58.43,["y"]=54.28,["kind"]="npc",["entityID"]=20130}},["kind"]="npc",["entityID"]=20130}},["url"]="https://www.wowhead.com/tbc/quest=10279/to-the-masters-lair#comments",["startTargets"]={{["name"]="Распорядитель времени",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=66.02,["y"]=49.7,["kind"]="npc",["entityID"]=20142}}}
G.questHelp[10280]={["steps"]={"Отнесите кристалл Адалу на Террасу Света в Шаттрате. Возьмите «Как проникнуть в Аркатрац» до походов в Механар и Ботанику."},["refs"]={{[1]="Начало: Проекция принца нексуса Харамада",[2]="https://www.wowhead.com/tbc/ru/npc=20084",["targets"]={{["name"]="Проекция принца нексуса Харамада",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=45.87,["y"]=35.96,["kind"]="npc",["entityID"]=20084}},["kind"]="npc",["entityID"]=20084},{[1]="Сдача: А'дал",[2]="https://www.wowhead.com/tbc/ru/npc=18481",["targets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}},["kind"]="npc",["entityID"]=18481},{[1]="Выданный предмет: Кристалл Ата'мала",[2]="https://www.wowhead.com/tbc/ru/item=29106",["targets"]={},["kind"]="item",["entityID"]=29106}},["url"]="https://www.wowhead.com/tbc/quest=10280#comments",["startTargets"]={{["name"]="Проекция принца нексуса Харамада",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=45.87,["y"]=35.96,["kind"]="npc",["entityID"]=20084}}}
G.questHelp[10282]={["steps"]={"Войдите в Старый Хилсбрад через Пещеры Времени и поговорите с Эрозионом.","Возьмите поручение и необходимые взрывчатые вещества для плана Тареты."},["refs"]={{[1]="Начало: Андорму",[2]="https://www.wowhead.com/wotlk/ru/npc=20130",["targets"]={{["name"]="Андорму",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=58.43,["y"]=54.28,["kind"]="npc",["entityID"]=20130}},["kind"]="npc",["entityID"]=20130},{[1]="Сдача: Эрозион",[2]="https://www.wowhead.com/wotlk/ru/npc=18723",["targets"]={{["name"]="Подход к подземелью: Эрозион находится внутри",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.7,["y"]=49.8,["kind"]="entrance",["entityID"]=18723}},["kind"]="npc",["entityID"]=18723}},["url"]="https://www.wowhead.com/wotlk/quest=10282#comments",["startTargets"]={{["name"]="Андорму",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=58.43,["y"]=54.28,["kind"]="npc",["entityID"]=20130}}}
G.questHelp[10283]={["steps"]={"В нижней части крепости Дарнхольд найдите пять бараков с заключёнными орками.","Используйте выданные заряды у бочек в каждом бараке. После выполнения продолжайте к Траллу."},["refs"]={{[1]="Начало: Эрозион",[2]="https://www.wowhead.com/wotlk/ru/npc=18723",["targets"]={{["name"]="Подход к подземелью: Эрозион находится внутри",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.7,["y"]=49.8,["kind"]="entrance",["entityID"]=18723}},["kind"]="npc",["entityID"]=18723},{[1]="Сдача: Тралл",[2]="https://www.wowhead.com/wotlk/ru/npc=17876",["targets"]={{["name"]="Подход к подземелью: Тралл находится внутри",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.7,["y"]=49.8,["kind"]="entrance",["entityID"]=17876}},["kind"]="npc",["entityID"]=17876},{[1]="Выданный предмет: Упаковка зажигательных бомб",[2]="https://www.wowhead.com/wotlk/ru/item=25853",["targets"]={},["kind"]="item",["entityID"]=25853}},["url"]="https://www.wowhead.com/wotlk/quest=10283#comments",["startTargets"]={{["name"]="Подход к подземелью: Эрозион находится внутри",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.7,["y"]=49.8,["kind"]="entrance",["entityID"]=18723}}}
G.questHelp[10284]={["steps"]={"Поговорите с Траллом и начните сопровождение только после подготовки группы.","Двигайтесь вместе с ним, защищайте от волн и делайте необходимые разговоры на остановках.","После финального боя завершите задание у Эрозиона, прежде чем уходить."},["refs"]={{[1]="Начало: Тралл",[2]="https://www.wowhead.com/wotlk/ru/npc=17876",["targets"]={{["name"]="Подход к подземелью: Тралл находится внутри",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.7,["y"]=49.8,["kind"]="entrance",["entityID"]=17876}},["kind"]="npc",["entityID"]=17876},{[1]="Сдача: Эрозион",[2]="https://www.wowhead.com/wotlk/ru/npc=18723",["targets"]={{["name"]="Подход к подземелью: Эрозион находится внутри",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.7,["y"]=49.8,["kind"]="entrance",["entityID"]=18723}},["kind"]="npc",["entityID"]=18723}},["url"]="https://www.wowhead.com/wotlk/quest=10284#comments",["startTargets"]={{["name"]="Подход к подземелью: Тралл находится внутри",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.7,["y"]=49.8,["kind"]="entrance",["entityID"]=17876}}}
G.questHelp[10285]={["steps"]={"После завершения побега из Дарнхольда вернитесь к Андорму в Пещеры Времени.","Сдайте задание: это продолжение допуска к следующим событиям Пещер Времени."},["refs"]={{[1]="Начало: Эрозион",[2]="https://www.wowhead.com/wotlk/ru/npc=18723",["targets"]={{["name"]="Подход к подземелью: Эрозион находится внутри",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.7,["y"]=49.8,["kind"]="entrance",["entityID"]=18723}},["kind"]="npc",["entityID"]=18723},{[1]="Сдача: Андорму",[2]="https://www.wowhead.com/wotlk/ru/npc=20130",["targets"]={{["name"]="Андорму",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=58.43,["y"]=54.28,["kind"]="npc",["entityID"]=20130}},["kind"]="npc",["entityID"]=20130}},["url"]="https://www.wowhead.com/wotlk/quest=10285#comments",["startTargets"]={{["name"]="Подход к подземелью: Эрозион находится внутри",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=65.7,["y"]=49.8,["kind"]="entrance",["entityID"]=18723}}}
G.questHelp[10445]={["steps"]={"Возьмите задание до убийства Леди Вайш и Кель’таса Солнечного Скитальца.","Получите части сосуда с обоих боссов в Змеином святилище и Крепости Бурь, затем верните Соридорми в Пещеры Времени."},["refs"]={{[1]="Начало: Соридорми",[2]="https://www.wowhead.com/tbc/ru/npc=19935",["targets"]={{["name"]="Соридорми (место поиска)",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=61.05,["y"]=56.95,["kind"]="npc",["entityID"]=19935}},["kind"]="npc",["entityID"]=19935},{[1]="Цель: Неполный фиал Вайш",[2]="https://www.wowhead.com/tbc/ru/item=29906",["targets"]={{["name"]="Подход к подземелью: Леди Вайш находится внутри",["zone"]="Зангартопь",["zoneEN"]="Zangarmarsh",["x"]=50.4,["y"]=40.9,["kind"]="entrance",["entityID"]=21212}},["kind"]="item",["entityID"]=29906},{[1]="Источник добычи: Леди Вайш",[2]="https://www.wowhead.com/tbc/ru/npc=21212",["targets"]={{["name"]="Подход к подземелью: Леди Вайш находится внутри",["zone"]="Зангартопь",["zoneEN"]="Zangarmarsh",["x"]=50.4,["y"]=40.9,["kind"]="entrance",["entityID"]=21212}},["kind"]="npc",["entityID"]=21212},{[1]="Цель: Неполный фиал Келя",[2]="https://www.wowhead.com/tbc/ru/item=29905",["targets"]={},["kind"]="item",["entityID"]=29905},{[1]="Источник добычи: Кель'тас Солнечный Скиталец",[2]="https://www.wowhead.com/tbc/ru/npc=19622",["targets"]={},["kind"]="npc",["entityID"]=19622}},["url"]="https://www.wowhead.com/tbc/quest=10445#comments",["startTargets"]={{["name"]="Соридорми (место поиска)",["zone"]="Танарис",["zoneEN"]="Tanaris",["x"]=61.05,["y"]=56.95,["kind"]="npc",["entityID"]=19935}}}
G.questHelp[10458]={["steps"]={"Установите выданный тотем рядом с разъярёнными духами земли и огня в Долине Призрачной Луны.","Убивайте духов в радиусе тотема, чтобы захватывать души. Подходящие места отмечены около 45, 45 и 52, 52."},["refs"]={{[1]="Начало: Целитель земли Торлок",[2]="https://www.wowhead.com/wotlk/ru/npc=21024",["targets"]={{["name"]="Целитель земли Торлок",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=42.19,["y"]=45.06,["kind"]="npc",["entityID"]=21024}},["kind"]="npc",["entityID"]=21024},{[1]="Выданный предмет: Тотем духов",[2]="https://www.wowhead.com/wotlk/ru/item=30094",["targets"]={},["kind"]="item",["entityID"]=30094}},["url"]="https://www.wowhead.com/wotlk/quest=10458#comments",["startTargets"]={{["name"]="Целитель земли Торлок",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=42.19,["y"]=45.06,["kind"]="npc",["entityID"]=21024}}}
G.questHelp[10480]={["steps"]={"Найдите духов воды на севере Долины Призрачной Луны, примерно 47, 22.","Ставьте тотем до убийства и дождитесь зачёта души. После нужного количества вернитесь к Торлоку."},["refs"]={{[1]="Начало: Целитель земли Торлок",[2]="https://www.wowhead.com/wotlk/ru/npc=21024",["targets"]={{["name"]="Целитель земли Торлок",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=42.19,["y"]=45.06,["kind"]="npc",["entityID"]=21024}},["kind"]="npc",["entityID"]=21024},{[1]="Выданный предмет: Тотем духов",[2]="https://www.wowhead.com/wotlk/ru/item=30094",["targets"]={},["kind"]="item",["entityID"]=30094}},["url"]="https://www.wowhead.com/wotlk/quest=10480#comments",["startTargets"]={{["name"]="Целитель земли Торлок",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=42.19,["y"]=45.06,["kind"]="npc",["entityID"]=21024}}}
G.questHelp[10481]={["steps"]={"Ищите духов воздуха на юго-востоке Долины Призрачной Луны, примерно 62, 55.","Убивайте их возле установленного тотема и дождитесь захвата души до открытия добычи."},["refs"]={{[1]="Начало: Целитель земли Торлок",[2]="https://www.wowhead.com/wotlk/ru/npc=21024",["targets"]={{["name"]="Целитель земли Торлок",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=42.19,["y"]=45.06,["kind"]="npc",["entityID"]=21024}},["kind"]="npc",["entityID"]=21024},{[1]="Выданный предмет: Тотем духов",[2]="https://www.wowhead.com/wotlk/ru/item=30094",["targets"]={},["kind"]="item",["entityID"]=30094}},["url"]="https://www.wowhead.com/wotlk/quest=10481#comments",["startTargets"]={{["name"]="Целитель земли Торлок",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=42.19,["y"]=45.06,["kind"]="npc",["entityID"]=21024}}}
G.questHelp[10513]={["steps"]={"Найдите Оронока Горемычного на северном уступе Долины Призрачной Луны, примерно 53, 23.","Поговорите с ним для продолжения истории Кода Проклятия."},["refs"]={{[1]="Начало: Целитель земли Торлок",[2]="https://www.wowhead.com/wotlk/ru/npc=21024",["targets"]={{["name"]="Целитель земли Торлок",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=42.19,["y"]=45.06,["kind"]="npc",["entityID"]=21024}},["kind"]="npc",["entityID"]=21024},{[1]="Сдача: Оронок Горемычный",[2]="https://www.wowhead.com/wotlk/ru/npc=21183",["targets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}},["kind"]="npc",["entityID"]=21183}},["url"]="https://www.wowhead.com/wotlk/quest=10513#comments",["startTargets"]={{["name"]="Целитель земли Торлок",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=42.19,["y"]=45.06,["kind"]="npc",["entityID"]=21024}}}
G.questHelp[10514]={["steps"]={"Найдите холмик клубня, возле которого живой дикий кабан, и используйте свисток Оронока.","Кабан выкопает отдельный предмет — заберите его. Подведённый агрессией кабан не заменяет мирно стоящего рядом; защищайте кабанов от местных хищников."},["refs"]={{[1]="Начало: Оронок Горемычный",[2]="https://www.wowhead.com/wotlk/ru/npc=21183",["targets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}},["kind"]="npc",["entityID"]=21183},{[1]="Цель: Клубни долины Призрачной Луны",[2]="https://www.wowhead.com/wotlk/ru/item=30356",["targets"]={},["kind"]="item",["entityID"]=30356},{[1]="Источник добычи: Клубни долины Призрачной Луны",[2]="https://www.wowhead.com/wotlk/ru/object=184691",["targets"]={},["kind"]="object",["entityID"]=184691},{[1]="Выданный предмет: Вепревый свисток Оронока",[2]="https://www.wowhead.com/wotlk/ru/item=30462",["targets"]={},["kind"]="item",["entityID"]=30462}},["url"]="https://www.wowhead.com/wotlk/quest=10514#comments",["startTargets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}}}
G.questHelp[10515]={["steps"]={"К северу от Оронока, примерно у 57, 18, уничтожьте 10 яиц прожорливых камнедеров.","Следите за патрулирующей элитной матриархом живодёров. После выполнения вернитесь к Ороноку."},["refs"]={{[1]="Начало: Оронок Горемычный",[2]="https://www.wowhead.com/wotlk/ru/npc=21183",["targets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}},["kind"]="npc",["entityID"]=21183},{[1]="Цель: Яйцо прожорливого камнедера",[2]="https://www.wowhead.com/wotlk/ru/object=184684",["targets"]={{["name"]="Яйцо прожорливого камнедера",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=55.58,["y"]=15.14,["kind"]="object",["entityID"]=184684},{["name"]="Яйцо прожорливого камнедера",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=57.47,["y"]=16.77,["kind"]="object",["entityID"]=184684},{["name"]="Яйцо прожорливого камнедера",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=55.47,["y"]=16.14,["kind"]="object",["entityID"]=184684},{["name"]="Яйцо прожорливого камнедера",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=56.79,["y"]=16.82,["kind"]="object",["entityID"]=184684}},["kind"]="object",["entityID"]=184684}},["url"]="https://www.wowhead.com/wotlk/quest=10515#comments",["startTargets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}}}
G.questHelp[10519]={["steps"]={"Выберите у Оронока все реплики и дослушайте историю Кода Проклятия.","Затем возьмите направления к трём сыновьям: Гром’тору, Ар’тору и Бораку. Их ветви дают три части кода."},["refs"]={{[1]="Начало: Оронок Горемычный",[2]="https://www.wowhead.com/wotlk/ru/npc=21183",["targets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}},["kind"]="npc",["entityID"]=21183}},["url"]="https://www.wowhead.com/wotlk/quest=10519#comments",["startTargets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}}}
G.questHelp[10521]={["steps"]={"Найдите Гром’тора у поселения наг в Долине Призрачной Луны, примерно 44, 23.","Возьмите задание на первую часть Кода Проклятия."},["refs"]={{[1]="Начало: Оронок Горемычный",[2]="https://www.wowhead.com/wotlk/ru/npc=21183",["targets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}},["kind"]="npc",["entityID"]=21183},{[1]="Сдача: Гром'тор, сын Оронока",[2]="https://www.wowhead.com/wotlk/ru/npc=21291",["targets"]={{["name"]="Гром'тор, сын Оронока (место поиска)",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=44.62,["y"]=23.66,["kind"]="npc",["entityID"]=21291}},["kind"]="npc",["entityID"]=21291}},["url"]="https://www.wowhead.com/wotlk/quest=10521#comments",["startTargets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}}}
G.questHelp[10522]={["steps"]={"Убивайте наг у поселения Кольца Змеи, примерно 45, 27, и собирайте ключи.","Открывайте местные сундуки ключами, пока не найдёте фрагмент кода. Ключ и фрагмент — разные предметы; первого сундука может не хватить."},["refs"]={{[1]="Начало: Гром'тор, сын Оронока",[2]="https://www.wowhead.com/wotlk/ru/npc=21291",["targets"]={{["name"]="Гром'тор, сын Оронока (место поиска)",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=44.62,["y"]=23.66,["kind"]="npc",["entityID"]=21291}},["kind"]="npc",["entityID"]=21291},{[1]="Цель: Первый фрагмент Кода Проклятия",[2]="https://www.wowhead.com/wotlk/ru/item=30428",["targets"]={{["name"]="Источник добычи: Сундук Змеиных Колец",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.12,["y"]=27.67,["kind"]="object",["entityID"]=184716},{["name"]="Источник добычи: Сундук Змеиных Колец",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.59,["y"]=27.08,["kind"]="object",["entityID"]=184716},{["name"]="Источник добычи: Сундук Змеиных Колец",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.46,["y"]=27.31,["kind"]="object",["entityID"]=184716},{["name"]="Источник добычи: Сундук Змеиных Колец",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=52.64,["y"]=25.82,["kind"]="object",["entityID"]=184716}},["kind"]="item",["entityID"]=30428},{[1]="Источник добычи: Сундук Змеиных Колец",[2]="https://www.wowhead.com/wotlk/ru/object=184716",["targets"]={{["name"]="Сундук Змеиных Колец",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.12,["y"]=27.67,["kind"]="object",["entityID"]=184716},{["name"]="Сундук Змеиных Колец",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.59,["y"]=27.08,["kind"]="object",["entityID"]=184716},{["name"]="Сундук Змеиных Колец",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.46,["y"]=27.31,["kind"]="object",["entit