G.questHelp[10523]={["steps"]={"После получения первой части от Гром’тора вернитесь к Ороноку, примерно 54, 23.","Передайте фрагмент. Для полной цепочки остаются ещё две ветви сыновей."},["refs"]={{[1]="Начало: Гром'тор, сын Оронока",[2]="https://www.wowhead.com/wotlk/ru/npc=21291",["targets"]={{["name"]="Гром'тор, сын Оронока (место поиска)",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=44.62,["y"]=23.66,["kind"]="npc",["entityID"]=21291}},["kind"]="npc",["entityID"]=21291},{[1]="Сдача: Оронок Горемычный",[2]="https://www.wowhead.com/wotlk/ru/npc=21183",["targets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}},["kind"]="npc",["entityID"]=21183},{[1]="Выданный предмет: Сейф Гром'тора",[2]="https://www.wowhead.com/wotlk/ru/item=30429",["targets"]={},["kind"]="item",["entityID"]=30429}},["url"]="https://www.wowhead.com/wotlk/quest=10523#comments",["startTargets"]={{["name"]="Гром'тор, сын Оронока (место поиска)",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=44.62,["y"]=23.66,["kind"]="npc",["entityID"]=21291}}}
