G.questHelp[10528]={["steps"]={"Победите демоницу, охраняющую кристальную тюрьму Ар’тора, и заберите ключ.","Освободите пленника. Следующее задание даёт его дух, а не обычное живое тело."},["refs"]={{[1]="Начало: Ар'тор, сын Оронока",[2]="https://www.wowhead.com/wotlk/ru/npc=21292",["targets"]={{["name"]="Ар'тор, сын Оронока",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=29.63,["y"]=50.4,["kind"]="npc",["entityID"]=21292}},["kind"]="npc",["entityID"]=21292},{[1]="Цель: Кристаллический ключ",[2]="https://www.wowhead.com/wotlk/ru/item=30442",["targets"]={{["name"]="Источник добычи: Госпожа боли Габрисса (место поиска)",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=28.3,["y"]=47.61,["kind"]="npc",["entityID"]=21309}},["kind"]="item",["entityID"]=30442},{[1]="Источник добычи: Госпожа боли Габрисса",[2]="https://www.wowhead.com/wotlk/ru/npc=21309",["targets"]={{["name"]="Госпожа боли Габрисса (место поиска)",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=28.3,["y"]=47.61,["kind"]="npc",["entityID"]=21309}},["kind"]="npc",["entityID"]=21309}},["url"]="https://www.wowhead.com/wotlk/quest=10528#comments",["startTargets"]={{["name"]="Ар'тор, сын Оронока",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=29.63,["y"]=50.4,["kind"]="npc",["entityID"]=21292}}}
G.questHelp[10537]={["steps"]={"Убивайте сатиров Иллидари в районе пленения Ар’тора, пока не получите лук Лон’горон.","Верните лук духу Ар’тора."},["refs"]={{[1]="Начало: Дух Ар'тора",[2]="https://www.wowhead.com/wotlk/ru/npc=21318",["targets"]={{["name"]="Дух Ар'тора",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=29.54,["y"]=50.56,["kind"]="npc",["entityID"]=21318}},["kind"]="npc",["entityID"]=21318},{[1]="Цель: Лон'горон, лук Горемычного",[2]="https://www.wowhead.com/wotlk/ru/item=30451",["targets"]={{["name"]="Источник добычи: Иллидарский ужасень",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=31.44,["y"]=55.67,["kind"]="npc",["entityID"]=19799},{["name"]="Источник добычи: Иллидарский ужасень",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=29.38,["y"]=49.31,["kind"]="npc",["entityID"]=19799},{["name"]="Источник добычи: Иллидарский ужасень",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=29.5,["y"]=56.85,["kind"]="npc",["entityID"]=19799},{["name"]="Источник добычи: Иллидарский ужасень",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=32.09,["y"]=50.09,["kind"]="npc",["entityID"]=19799},{["name"]="Источник добычи: Иллидарская бичевательница",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=29.23,["y"]=57,["kind"]="npc",["entityID"]=19800},{["name"]="Источник добычи: Иллидарская бичевательница",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=31.48,["y"]=55.22,["kind"]="npc",["entityID"]=19800},{["name"]="Источник добычи: Иллидарская бичевательница",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=29.34,["y"]=49.26,["kind"]="npc",["entityID"]=19800},{["name"]="Источник добычи: Иллидарская бичевательница",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=29.3,["y"]=49.48,["kind"]="npc",["entityID"]=19800},{["name"]="Источник добычи: Иллидарский терзатель",["zone"]=