G.questHelp[10540]={["steps"]={"Идите с духом Ар’тора к месту появления Венератуса, примерно 30, 57. Не улетайте верхом, иначе потеряете сопровождение.","Подойдите с духом к противнику, победите его и заберите фрагмент. Если дух исчез, вернитесь к Ар’тору."},["refs"]={{[1]="Начало: Дух Ар'тора",[2]="https://www.wowhead.com/wotlk/ru/npc=21318",["targets"]={{["name"]="Дух Ар'тора",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=29.54,["y"]=50.56,["kind"]="npc",["entityID"]=21318}},["kind"]="npc",["entityID"]=21318},{[1]="Цель: Второй фрагмент Кода Проклятия",[2]="https://www.wowhead.com/wotlk/ru/item=30453",["targets"]={},["kind"]="item",["entityID"]=30453},{[1]="Источник добычи: Венератус Многоликий",[2]="https://www.wowhead.com/wotlk/ru/npc=20427",["targets"]={},["kind"]="npc",["entityID"]=20427}},["url"]="https://www.wowhead.com/wotlk/quest=10540#comments",["startTargets"]={{["name"]="Дух Ар'тора",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=29.54,["y"]=50.56,["kind"]="npc",["entityID"]=21318}}}
G.questHelp[10541]={["steps"]={"Верните вторую часть Кода Проклятия Ороноку, примерно 54, 23.","Это сдача результата ветви Ар’тора; повторное сопровождение духа не требуется."},["refs"]={{[1]="Начало: Дух Ар'тора",[2]="https://www.wowhead.com/wotlk/ru/npc=21318",["targets"]={{["name"]="Дух Ар'тора",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=29.54,["y"]=50.56,["kind"]="npc",["entityID"]=21318}},["kind"]="npc",["entityID"]=21318},{[1]="Сдача: Оронок Горемычный",[2]="https://www.wowhead.com/wotlk/ru/npc=21183",["targets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}},["kind"]="npc",["entityID"]=21183},{[1]="Выданный предмет: Запертый сейф Ар'тора",[2]="https://www.wowhead.com/wotlk/ru/item=30454",["targets"]={},["kind"]="item",["entityID"]=30454}},["url"]="https://www.wowhead.com/wotlk/quest=10541#comments",["startTargets"]={{["name"]="Дух Ар'тора",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=29.54,["y"]=50.56,["kind"]="npc",["entityID"]=21318}}}
G.questHelp[10546]={["steps"]={"Найдите Борака у восточного края моста в Долине Призрачной Луны, примерно 48, 57.","Поговорите с ним и начните ветку с яйцами и послом."},["refs"]={{[1]="Начало: Оронок Горемычный",[2]="https://www.wowhead.com/wotlk/ru/npc=21183",["targets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}},["kind"]="npc",["entityID"]=21183},{[1]="Сдача: Борак, сын Оронока",[2]="https://www.wowhead.com/wotlk/ru/npc=21293",["targets"]={{["name"]="Борак, сын Оронока",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=47.56,["y"]=57.18,["kind"]="npc",["entityID"]=21293}},["kind"]="npc",["entityID"]=21293}},["url"]="https://www.wowhead.com/wotlk/quest=10546#comments",["startTargets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}}}
G.questHelp[10547]={["steps"]={"Собирайте яйца ворон возле Борака, пока не найдёте целое пригодное яйцо.","Большинство яиц может оказаться испорченным — это описанная механика, а не обязательная ошибка. Отнесите нужное яйцо торговцу в Шаттрате."},["refs"]={{[1]="Начало: Борак, сын Оронока",[2]="https://www.wowhead.com/wotlk/ru/npc=21293",["targets"]={{["name"]="Борак, сын Оронока",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=47.56,["y"]=57.18,["kind"]="npc",["entityID"]=21293}},["kind"]="npc",["entityID"]=21293},{[1]="Сдача: Тобиас Грязежор",[2]="https://www.wowhead.com/wotlk/ru/npc=21411",["targets"]={{["name"]="Тобиас Грязежор (место поиска)",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=63.95,["y"]=70.03,["kind"]="npc",["entityID"]=21411}},["kind"]="npc",["entityID"]=21411},{[1]="Цель: Тухлое яйцо араккоа",[2]="https://www.wowhead.com/wotlk/ru/item=30500",["targets"]={{["name"]="Источник добычи: Тухлое яйцо араккоа",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=43.32,["y"]=54.63,["kind"]="object",["entityID"]=184795},{["name"]="Источник добычи: Тухлое яйцо араккоа",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=42.97,["y"]=55.03,["kind"]="object",["entityID"]=184795},{["name"]="Источник добычи: Тухлое яйцо араккоа",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=44.68,["y"]=55.21,["kind"]="object",["entityID"]=184795},{["name"]="Источник добычи: Тухлое яйцо араккоа",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=43.29,["y"]=56.03,["kind"]="object",["entityID"]=184795}},["kind"]="item",["entityID"]=30500},{[1]="Источник добычи: Тухлое яйцо араккоа",[2]="https://www.wowhead.com/wotlk/ru/object=184795",["targets"]={{["name"]="Тухлое яйцо араккоа",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=43.32,["y"]=54.63,["kind"]="object",["entityID"]=184795},{["name"]="Тухлое яйцо араккоа",["zone"]="Долина Призрачной Луны",["