G.questHelp[10570]={["steps"]={"Положите кровопийку на дальнем конце моста и отойдите примерно к его середине.","Дождитесь, пока посол поговорит с охраной и телохранитель уйдёт. Только после этого нападайте на посла и забирайте письмо."},["refs"]={{[1]="Начало: Борак, сын Оронока",[2]="https://www.wowhead.com/wotlk/ru/npc=21293",["targets"]={{["name"]="Борак, сын Оронока",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=47.56,["y"]=57.18,["kind"]="npc",["entityID"]=21293}},["kind"]="npc",["entityID"]=21293},{[1]="Цель: Послание Ярости Бури",[2]="https://www.wowhead.com/wotlk/ru/item=30617",["targets"]={},["kind"]="item",["entityID"]=30617},{[1]="Источник добычи: Военный атташе Икарий",[2]="https://www.wowhead.com/wotlk/ru/npc=21409",["targets"]={},["kind"]="npc",["entityID"]=21409},{[1]="Выданный предмет: Сверток кровопийки",[2]="https://www.wowhead.com/wotlk/ru/item=30616",["targets"]={},["kind"]="item",["entityID"]=30616}},["url"]="https://www.wowhead.com/wotlk/quest=10570#comments",["startTargets"]={{["name"]="Борак, сын Оронока",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=47.56,["y"]=57.18,["kind"]="npc",["entityID"]=21293}}}
G.questHelp[10571]={["steps"]={"Старец Орону стоит на балконе в руинах Баа’ри, примерно 57, 32.","Победите его, заберите «Распоряжения Акамы» и вернитесь к квестодателю. Прерывайте его лечение."},["refs"]={{[1]="Начало: Анахоретка Сейла",[2]="https://www.wowhead.com/wotlk/ru/npc=21402",["targets"]={{["name"]="Анахоретка Сейла",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=62.58,["y"]=28.38,["kind"]="npc",["entityID"]=21402}},["kind"]="npc",["entityID"]=21402},{[1]="Цель: Распоряжения Акамы",[2]="https://www.wowhead.com/wotlk/ru/item=30649",["targets"]={{["name"]="Источник добычи: Старец Орону",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=57.19,["y"]=32.87,["kind"]="npc",["entityID"]=21663}},["kind"]="item",["entityID"]=30649},{[1]="Источник добычи: Старец Орону",[2]="https://www.wowhead.com/wotlk/ru/npc=21663",["targets"]={{["name"]="Старец Орону",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=57.19,["y"]=32.87,["kind"]="npc",["entityID"]=21663}},["kind"]="npc",["entityID"]=21663}},["url"]="https://www.wowhead.com/wotlk/quest=10571#comments",["startTargets"]={{["name"]="Анахоретка Сейла",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=62.58,["y"]=28.38,["kind"]="npc",["entityID"]=21402}}}
G.questHelp[10574]={["steps"]={"Найдите четырёх осквернителей в Долине Призрачной Луны: Лакаан 49, 23; Уйлару 48, 39; Эйкенен 51, 52; Хаалум 57, 73.","Сначала уничтожайте их тотемы, затем самих противников. Заберите четыре фрагмента медальона."},["refs"]={{[1]="Начало: Анахоретка Сейла",[2]="https://www.wowhead.com/wotlk/ru/npc=21402",["targets"]={{["name"]="Анахоретка Сейла",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=62.58,["y"]=28.38,["kind"]="npc",["entityID"]=21402}},["kind"]="npc",["entityID"]=21402},{[1]="Цель: Фрагмент медальона Айкенена",[2]="https://www.wowhead.com/wotlk/ru/item=30692",["targets"]={{["name"]="Источник добычи: Айкенен",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=51.18,["y"]=52.82,["kind"]="npc",["entityID"]=21709}},["kind"]="item",["entityID"]=30692},{[1]="Источник добычи: Айкенен",[2]="https://www.wowhead.com/wotlk/ru/npc=21709",["targets"]={{["name"]="Айкенен",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=51.18,["y"]=52.82,["kind"]="npc",["entityID"]=21709}},["kind"]="npc",["entityID"]=21709},{[1]="Цель: Фрагмент медальона Хаалума",[2]="https://www.wowhead.com/wotlk/ru/item=30691",["targets"]={{["name"]="Источник добычи: Хаалум",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=57.09,["y"]=73.65,["kind"]="npc",["entityID"]=21711}},["kind"]="item",["entityID"]=30691},{[1]="Источник добычи: Хаалум",[2]="https://www.wowhead.com/wotlk/ru/npc=21711",["targets"]={{["name"]="Хаалум",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=57.09,["y"]=73.65,["kind"]="npc",["entityID"]=21711}},["kind"]="npc",["entityID"]=21711},{[1]="Цель: Фрагмент медальона Лакаана",[2]="https://www.wowhead.com/wotlk/ru/item=30693",["targets"]={{["name"]="Источник добычи: Лакаан",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=49.89,["y"]=23.01,["kind"]="npc",["entityID"]=21416}},["kind"]="item",["entityID"]=30693},{[1]="Источни