G.questHelp[10575]={["steps"]={"У Клети Стражницы, примерно 57, 50, найдите спуск под охраняющим вход демоном.","Спуститесь внутрь и поговорите с Санору. Метка на поверхности указывает вход, а не этаж с персонажем."},["refs"]={{[1]="Начало: Анахоретка Сейла",[2]="https://www.wowhead.com/wotlk/ru/npc=21402",["targets"]={{["name"]="Анахоретка Сейла",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=62.58,["y"]=28.38,["kind"]="npc",["entityID"]=21402}},["kind"]="npc",["entityID"]=21402},{[1]="Сдача: Санору",[2]="https://www.wowhead.com/wotlk/ru/npc=21826",["targets"]={{["name"]="Санору",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=57.33,["y"]=49.58,["kind"]="npc",["entityID"]=21826}},["kind"]="npc",["entityID"]=21826}},["url"]="https://www.wowhead.com/wotlk/quest=10575#comments",["startTargets"]={{["name"]="Анахоретка Сейла",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=62.58,["y"]=28.38,["kind"]="npc",["entityID"]=21402}}}
G.questHelp[10576]={["steps"]={"Убивайте эльфов крови в лагере Затмения, примерно 44, 65, и собирайте части доспехов.","Предметы выпадают с разных противников этого лагеря. Собранный комплект верните Бораку для маскировки."},["refs"]={{[1]="Начало: Борак, сын Оронока",[2]="https://www.wowhead.com/wotlk/ru/npc=21293",["targets"]={{["name"]="Борак, сын Оронока",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=47.56,["y"]=57.18,["kind"]="npc",["entityID"]=21293}},["kind"]="npc",["entityID"]=21293},{[1]="Цель: Броня лагеря Затмения",[2]="https://www.wowhead.com/wotlk/ru/item=30640",["targets"]={{["name"]="Источник добычи: Центурион лагеря Затмения",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=49.7,["y"]=60.92,["kind"]="npc",["entityID"]=19792},{["name"]="Источник добычи: Центурион лагеря Затмения",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=49.14,["y"]=59.79,["kind"]="npc",["entityID"]=19792},{["name"]="Источник добычи: Центурион лагеря Затмения",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=49.42,["y"]=59.8,["kind"]="npc",["entityID"]=19792},{["name"]="Источник добычи: Центурион лагеря Затмения",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=48.59,["y"]=63.46,["kind"]="npc",["entityID"]=19792},{["name"]="Источник добычи: Рыцарь крови лагеря Затмения",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=51.63,["y"]=64.75,["kind"]="npc",["entityID"]=19795},{["name"]="Источник добычи: Рыцарь крови лагеря Затмения",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=51.72,["y"]=64.95,["kind"]="npc",["entityID"]=19795},{["name"]="Источник добычи: Рыцарь крови лагеря Затмения",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=51.5,["y"]=64.88,["kind"]="npc",["entityID"]=19795},{["name"]="Источник добычи: Рыцарь крови лагеря Затмения",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley