G.questHelp[10577]={["steps"]={"Наденьте выданную маскировку и поговорите с Рууском в лагере Затмения, примерно 46, 72.","Не садитесь на транспорт возле него: это снимает маскировку и вызывает нападение охраны."},["refs"]={{[1]="Начало: Борак, сын Оронока",[2]="https://www.wowhead.com/wotlk/ru/npc=21293",["targets"]={{["name"]="Борак, сын Оронока",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=47.56,["y"]=57.18,["kind"]="npc",["entityID"]=21293}},["kind"]="npc",["entityID"]=21293},{[1]="Выданный предмет: Маскировка под эльфа крови",[2]="https://www.wowhead.com/wotlk/ru/item=30639",["targets"]={},["kind"]="item",["entityID"]=30639}},["url"]="https://www.wowhead.com/wotlk/quest=10577#comments",["startTargets"]={{["name"]="Борак, сын Оронока",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=47.56,["y"]=57.18,["kind"]="npc",["entityID"]=21293}}}
G.questHelp[10578]={["steps"]={"Найдите Руула Светокрада, патрулирующего между Святилищем Звёзд и Крепостью Драконьей Пасти.","Подготовьте группу, победите его и заберите фрагмент кода с тела. После всадника может остаться его дракон — бой ещё не закончен."},["refs"]={{[1]="Начало: Борак, сын Оронока",[2]="https://www.wowhead.com/wotlk/ru/npc=21293",["targets"]={{["name"]="Борак, сын Оронока",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=47.56,["y"]=57.18,["kind"]="npc",["entityID"]=21293}},["kind"]="npc",["entityID"]=21293},{[1]="Цель: Третий фрагмент Кода Проклятия",[2]="https://www.wowhead.com/wotlk/ru/item=30645",["targets"]={{["name"]="Источник добычи: Руул Светокрад (место поиска)",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=57.28,["y"]=50.7,["kind"]="npc",["entityID"]=21315}},["kind"]="item",["entityID"]=30645},{[1]="Источник добычи: Руул Светокрад",[2]="https://www.wowhead.com/wotlk/ru/npc=21315",["targets"]={{["name"]="Руул Светокрад (место поиска)",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=57.28,["y"]=50.7,["kind"]="npc",["entityID"]=21315}},["kind"]="npc",["entityID"]=21315}},["url"]="https://www.wowhead.com/wotlk/quest=10578#comments",["startTargets"]={{["name"]="Борак, сын Оронока",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=47.56,["y"]=57.18,["kind"]="npc",["entityID"]=21293}}}
G.questHelp[10579]={["steps"]={"Принесите третью часть Кода Проклятия Ороноку после завершения ветви Борака.","Когда собраны все три части, продолжайте к общему финалу."},["refs"]={{[1]="Начало: Борак, сын Оронока",[2]="https://www.wowhead.com/wotlk/ru/npc=21293",["targets"]={{["name"]="Борак, сын Оронока",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=47.56,["y"]=57.18,["kind"]="npc",["entityID"]=21293}},["kind"]="npc",["entityID"]=21293},{[1]="Сдача: Оронок Горемычный",[2]="https://www.wowhead.com/wotlk/ru/npc=21183",["targets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}},["kind"]="npc",["entityID"]=21183},{[1]="Выданный предмет: Запертый сейф Борака",[2]="https://www.wowhead.com/wotlk/ru/item=30646",["targets"]={},["kind"]="item",["entityID"]=30646}},["url"]="https://www.wowhead.com/wotlk/quest=10579#comments",["startTargets"]={{["name"]="Борак, сын Оронока",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=47.56,["y"]=57.18,["kind"]="npc",["entityID"]=21293}}}
G.questHelp[10588]={["steps"]={"Собрав части кода, вернитесь к Алтарю Проклятия и используйте восстановленный код для начала события.","Дождитесь союзников, поговорите с Ороноком и победите Цируха Повелителя Огня. Завершите разговоры после боя."},["refs"]={{[1]="Начало: Оронок Горемычный",[2]="https://www.wowhead.com/wotlk/ru/npc=21183",["targets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}},["kind"]="npc",["entityID"]=21183},{[1]="Сдача: Целитель земли Торлок",[2]="https://www.wowhead.com/wotlk/ru/npc=21024",["targets"]={{["name"]="Целитель земли Торлок",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=42.19,["y"]=45.06,["kind"]="npc",["entityID"]=21024}},["kind"]="npc",["entityID"]=21024},{[1]="Цель: Цирух Повелитель Огня",[2]="https://www.wowhead.com/wotlk/ru/npc=21181",["targets"]={},["kind"]="npc",["entityID"]=21181},{[1]="Выданный предмет: Код Проклятия",[2]="https://www.wowhead.com/wotlk/ru/item=30657",["targets"]={},["kind"]="item",["entityID"]=30657}},["url"]="https://www.wowhead.com/wotlk/quest=10588#comments",["startTargets"]={{["name"]="Оронок Горемычный",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=53.95,["y"]=23.52,["kind"]="npc",["entityID"]=21183}}}
G.questHelp[10622]={["steps"]={"Зандрас находится снаружи, над подземной частью Клети Стражницы, примерно 57, 49.","Победите его и вернитесь вниз к Санору."},["refs"]={{[1]="Начало: Санору",[2]="https://www.wowhead.com/wotlk/ru/npc=21826",["targets"]={{["name"]="Санору",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=57.33,["y"]=49.58,["kind"]="npc",["entityID"]=21826}},["kind"]="npc",["entityID"]=21826},{[1]="Цель: Зандрас",[2]="https://www.wowhead.com/wotlk/ru/npc=21827",["targets"]={{["name"]="Зандрас (место поиска)",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.03,["y"]=49.13,["kind"]="npc",["entityID"]=21827}},["kind"]="npc",["entityID"]=21827}},["url"]="https://www.wowhead.com/wotlk/quest=10622#comments",["startTargets"]={{["name"]="Санору",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=57.33,["y"]=49.58,["kind"]="npc",["entityID"]=21826}}}
G.questHelp[10628]={["steps"]={"Пройдите к Акаме в подземной части Клети Стражницы и поговорите с ним.","Если он занят сценой с Вагатом и охраной, дождитесь её окончания и поговорите снова."},["refs"]={{[1]="Начало: Санору",[2]="https://www.wowhead.com/wotlk/ru/npc=21826",["targets"]={{["name"]="Санору",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=57.33,["y"]=49.58,["kind"]="npc",["entityID"]=21826}},["kind"]="npc",["entityID"]=21826},{[1]="Сдача: Акама",[2]="https://www.wowhead.com/wotlk/ru/npc=21700",["targets"]={{["name"]="Акама",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.11,["y"]=48.18,["kind"]="npc",["entityID"]=21700}},["kind"]="npc",["entityID"]=21700}},["url"]="https://www.wowhead.com/wotlk/quest=10628#comments",["startTargets"]={{["name"]="Санору",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=57.33,["y"]=49.58,["kind"]="npc",["entityID"]=21826}}}
G.questHelp[10680]={["steps"]={"Отправляйтесь к целителю земли Торлоку у Алтаря Проклятия, примерно 42, 45 в Долине Призрачной Луны.","Здесь начинается общая цепочка Кода Проклятия для дальнейшего допуска."},["refs"]={{[1]="Начало: Целитель земли Софурус",[2]="https://www.wowhead.com/wotlk/ru/npc=21937",["targets"]={{["name"]="Целитель земли Софурус",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=36.37,["y"]=56.95,["kind"]="npc",["entityID"]=21937}},["kind"]="npc",["entityID"]=21937},{[1]="Сдача: Целитель земли Торлок",[2]="https://www.wowhead.com/wotlk/ru/npc=21024",["targets"]={{["name"]="Целитель земли Торлок",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=42.19,["y"]=45.06,["kind"]="npc",["entityID"]=21024}},["kind"]="npc",["entityID"]=21024}},["url"]="https://www.wowhead.com/wotlk/quest=10680#comments",["startTargets"]={{["name"]="Целитель земли Софурус",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=36.37,["y"]=56.95,["kind"]="npc",["entityID"]=21937}}}
