G.questHelp[10704]={["steps"]={"С уже взятым заданием победите Паталеона Вычислителя в Механаре и Узлодревня в Ботанике. Заберите обе части ключа и отнесите Адалу в Шаттрат.","Для ключа достаточно обычного режима. Он открывает дверь Аркатраца; это не личный допуск к героическому режиму. Подготовьте доступ к платформам Крепости Бурь."},["refs"]={{[1]="Начало: А'дал",[2]="https://www.wowhead.com/tbc/ru/npc=18481",["targets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}},["kind"]="npc",["entityID"]=18481},{[1]="Цель: Верхний обломок ключа Аркатраца",[2]="https://www.wowhead.com/tbc/ru/item=31085",["targets"]={},["kind"]="item",["entityID"]=31085},{[1]="Источник добычи: Узлодревень",[2]="https://www.wowhead.com/tbc/ru/npc=17977",["targets"]={},["kind"]="npc",["entityID"]=17977},{[1]="Источник добычи: Warp Splinter (1)",[2]="https://www.wowhead.com/tbc/ru/npc=21582",["targets"]={},["kind"]="npc",["entityID"]=21582},{[1]="Цель: Нижний обломок ключа Аркатраца",[2]="https://www.wowhead.com/tbc/ru/item=31086",["targets"]={},["kind"]="item",["entityID"]=31086},{[1]="Источник добычи: Паталеон Вычислитель",[2]="https://www.wowhead.com/tbc/ru/npc=19220",["targets"]={},["kind"]="npc",["entityID"]=19220},{[1]="Источник добычи: Pathaleon the Calculator (1)",[2]="https://www.wowhead.com/tbc/ru/npc=21537",["targets"]={},["kind"]="npc",["entityID"]=21537}},["url"]="https://www.wowhead.com/tbc/quest=10704#comments",["startTargets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}}}
G.questHelp[10705]={["steps"]={"Найдите тело провидца Адало в Аркатраце перед комнатой последнего босса.","Взаимодействуйте с телом. Живого квестодателя или обычного вопросительного знака ждать не нужно."},["refs"]={{[1]="Начало: Акама",[2]="https://www.wowhead.com/wotlk/ru/npc=21700",["targets"]={{["name"]="Акама",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.11,["y"]=48.18,["kind"]="npc",["entityID"]=21700}},["kind"]="npc",["entityID"]=21700},{[1]="Сдача: Адало",[2]="https://www.wowhead.com/wotlk/ru/npc=21962",["targets"]={{["name"]="Подход к подземелью: Адало находится внутри",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=74.4,["y"]=57.7,["kind"]="entrance",["entityID"]=21962}},["kind"]="npc",["entityID"]=21962}},["url"]="https://www.wowhead.com/wotlk/quest=10705#comments",["startTargets"]={{["name"]="Акама",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.11,["y"]=48.18,["kind"]="npc",["entityID"]=21700}}}
G.questHelp[10706]={["steps"]={"Вернитесь из Аркатраца к Акаме под Клетью Стражницы в Долине Призрачной Луны.","Сообщите о знаке Адало. Если идёт сцена с демонами, дождитесь возможности разговора."},["refs"]={{[1]="Начало: Адало",[2]="https://www.wowhead.com/wotlk/ru/npc=21962",["targets"]={{["name"]="Подход к подземелью: Адало находится внутри",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=74.4,["y"]=57.7,["kind"]="entrance",["entityID"]=21962}},["kind"]="npc",["entityID"]=21962},{[1]="Сдача: Акама",[2]="https://www.wowhead.com/wotlk/ru/npc=21700",["targets"]={{["name"]="Акама",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.11,["y"]=48.18,["kind"]="npc",["entityID"]=21700}},["kind"]="npc",["entityID"]=21700}},["url"]="https://www.wowhead.com/wotlk/quest=10706#comments",["startTargets"]={{["name"]="Подход к подземелью: Адало находится внутри",["zone"]="Пустоверть",["zoneEN"]="Netherstorm",["x"]=74.4,["y"]=57.7,["kind"]="entrance",["entityID"]=21962}}}
G.questHelp[10707]={["steps"]={"На Террасе Ата’мала, примерно 71, 35, уничтожьте трёх противников, направляющих силу в кристалл.","После этого победите Владыку теней Смертный Вопль и заберите Сердце Ярости. Подготовьтесь к появлению дополнительных врагов."},["refs"]={{[1]="Начало: Акама",[2]="https://www.wowhead.com/wotlk/ru/npc=21700",["targets"]={{["name"]="Акама",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.11,["y"]=48.18,["kind"]="npc",["entityID"]=21700}},["kind"]="npc",["entityID"]=21700},{[1]="Цель: Сердце Ярости",[2]="https://www.wowhead.com/wotlk/ru/item=31307",["targets"]={{["name"]="Источник добычи: Владыка теней Смертокрик (место поиска)",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=72.33,["y"]=34.83,["kind"]="npc",["entityID"]=22006}},["kind"]="item",["entityID"]=31307},{[1]="Источник добычи: Владыка теней Смертокрик",[2]="https://www.wowhead.com/wotlk/ru/npc=22006",["targets"]={{["name"]="Владыка теней Смертокрик (место поиска)",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=72.33,["y"]=34.83,["kind"]="npc",["entityID"]=22006}},["kind"]="npc",["entityID"]=22006}},["url"]="https://www.wowhead.com/wotlk/quest=10707#comments",["startTargets"]={{["name"]="Акама",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.11,["y"]=48.18,["kind"]="npc",["entityID"]=21700}}}
G.questHelp[10708]={["steps"]={"Отнесите Сердце Ярости А’далу в Шаттрат и завершите поручение Акамы.","Следующая часть допуска Чёрного храма связана с Олумом после Каратресса в Змеином святилище."},["refs"]={{[1]="Начало: Акама",[2]="https://www.wowhead.com/wotlk/ru/npc=21700",["targets"]={{["name"]="Акама",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.11,["y"]=48.18,["kind"]="npc",["entityID"]=21700}},["kind"]="npc",["entityID"]=21700},{[1]="Сдача: А'дал",[2]="https://www.wowhead.com/wotlk/ru/npc=18481",["targets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}},["kind"]="npc",["entityID"]=18481}},["url"]="https://www.wowhead.com/wotlk/quest=10708#comments",["startTargets"]={{["name"]="Акама",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.11,["y"]=48.18,["kind"]="npc",["entityID"]=21700}}}
G.questHelp[10754]={["steps"]={"В Долине Призрачной Луны добудьте у Кузнеца Горлунка заготовку для ключа и используйте её, чтобы начать задание. Доставьте её Данату в Оплот Чести на Полуострове Адского Пламени."},["refs"]={{[1]="Начало: Форма для отливки ключа",[2]="https://www.wowhead.com/tbc/ru/item=31239",["targets"]={{["name"]="Источник добычи: Кузнец Горлунк",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=67.64,["y"]=36.2,["kind"]="npc",["entityID"]=22037}},["kind"]="item",["entityID"]=31239},{[1]="Источник добычи: Кузнец Горлунк",[2]="https://www.wowhead.com/tbc/ru/npc=22037",["targets"]={{["name"]="Кузнец Горлунк",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=67.64,["y"]=36.2,["kind"]="npc",["entityID"]=22037}},["kind"]="npc",["entityID"]=22037},{[1]="Сдача: Командир армии Данат Троллебой",[2]="https://www.wowhead.com/tbc/ru/npc=16819",["targets"]={{["name"]="Командир армии Данат Троллебой",["zone"]="Полуостров Адского Пламени",["zoneEN"]="Hellfire Peninsula",["x"]=56.64,["y"]=66.7,["kind"]="npc",["entityID"]=16819}},["kind"]="npc",["entityID"]=16819}},["url"]="https://www.wowhead.com/tbc/quest=10754#comments",["startTargets"]={{["name"]="Источник добычи: Кузнец Горлунк",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=67.64,["y"]=36.2,["kind"]="npc",["entityID"]=22037}}}
G.questHelp[10755]={["steps"]={"В Долине Призрачной Луны добудьте у Кузнеца Горлунка заготовку для ключа и используйте её, чтобы начать задание. Доставьте её Назгрелу в Траллмар на Полуострове Адского Пламени."},["refs"]={{[1]="Начало: Форма для отливки ключа",[2]="https://www.wowhead.com/tbc/ru/item=31241",["targets"]={{["name"]="Источник добычи: Кузнец Горлунк",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=67.64,["y"]=36.2,["kind"]="npc",["entityID"]=22037}},["kind"]="item",["entityID"]=31241},{[1]="Источник добычи: Кузнец Горлунк",[2]="https://www.wowhead.com/tbc/ru/npc=22037",["targets"]={{["name"]="Кузнец Горлунк",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=67.64,["y"]=36.2,["kind"]="npc",["entityID"]=22037}},["kind"]="npc",["entityID"]=22037},{[1]="Сдача: Назгрел",[2]="https://www.wowhead.com/tbc/ru/npc=3230",["targets"]={{["name"]="Назгрел",["zone"]="Полуостров Адского Пламени",["zoneEN"]="Hellfire Peninsula",["x"]=55.02,["y"]=35.96,["kind"]="npc",["entityID"]=3230}},["kind"]="npc",["entityID"]=3230}},["url"]="https://www.wowhead.com/tbc/quest=10755#comments",["startTargets"]={{["name"]="Источник добычи: Кузнец Горлунк",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=67.64,["y"]=36.2,["kind"]="npc",["entityID"]=22037}}}
