G.questHelp[10758]={["steps"]={"Победите Сквернобота на Полуострове Адского Пламени и используйте незакалённую заготовку на его останках. Одного убийства недостаточно.","Верните закалённую заготовку Рохоку в Траллмар и получите ключ Разрушенных залов. Этот ключ открывает дверь, а не героический режим."},["refs"]={{[1]="Начало: Рохок",[2]="https://www.wowhead.com/tbc/ru/npc=16583",["targets"]={{["name"]="Рохок",["zone"]="Полуостров Адского Пламени",["zoneEN"]="Hellfire Peninsula",["x"]=53.13,["y"]=38.16,["kind"]="npc",["entityID"]=16583}},["kind"]="npc",["entityID"]=16583},{[1]="Цель: Обожженная форма для отливки ключа",[2]="https://www.wowhead.com/tbc/ru/item=31252",["targets"]={},["kind"]="item",["entityID"]=31252},{[1]="Выданный предмет: Необожженная форма для отливки ключа",[2]="https://www.wowhead.com/tbc/ru/item=31251",["targets"]={},["kind"]="item",["entityID"]=31251}},["url"]="https://www.wowhead.com/tbc/quest=10758#comments",["startTargets"]={{["name"]="Рохок",["zone"]="Полуостров Адского Пламени",["zoneEN"]="Hellfire Peninsula",["x"]=53.13,["y"]=38.16,["kind"]="npc",["entityID"]=16583}}}
G.questHelp[10762]={["steps"]={"Отнесите заготовку Дамфри в Оплоте Чести. Заранее возьмите 4 слитка осквернённого железа, 2 чародейские пыли и 4 частицы огня для следующего шага."},["refs"]={{[1]="Начало: Командир армии Данат Троллебой",[2]="https://www.wowhead.com/tbc/ru/npc=16819",["targets"]={{["name"]="Командир армии Данат Троллебой",["zone"]="Полуостров Адского Пламени",["zoneEN"]="Hellfire Peninsula",["x"]=56.64,["y"]=66.7,["kind"]="npc",["entityID"]=16819}},["kind"]="npc",["entityID"]=16819},{[1]="Сдача: Болтуй",[2]="https://www.wowhead.com/tbc/ru/npc=21209",["targets"]={{["name"]="Болтуй (место поиска)",["zone"]="Полуостров Адского Пламени",["zoneEN"]="Hellfire Peninsula",["x"]=51.12,["y"]=60.3,["kind"]="npc",["entityID"]=21209}},["kind"]="npc",["entityID"]=21209},{[1]="Выданный предмет: Форма для отливки ключа",[2]="https://www.wowhead.com/tbc/ru/item=31245",["targets"]={},["kind"]="item",["entityID"]=31245}},["url"]="https://www.wowhead.com/tbc/quest=10762#comments",["startTargets"]={{["name"]="Командир армии Данат Троллебой",["zone"]="Полуостров Адского Пламени",["zoneEN"]="Hellfire Peninsula",["x"]=56.64,["y"]=66.7,["kind"]="npc",["entityID"]=16819}}}
