G.questHelp[10764]={["steps"]={"Победите Сквернобота на Полуострове Адского Пламени и используйте незакалённую заготовку на его останках. Одного убийства недостаточно.","Верните закалённую заготовку Дамфри в Оплот Чести и получите ключ Разрушенных залов. Этот ключ открывает дверь, а не героический режим."},["refs"]={{[1]="Начало: Болтуй",[2]="https://www.wowhead.com/tbc/ru/npc=21209",["targets"]={{["name"]="Болтуй (место поиска)",["zone"]="Полуостров Адского Пламени",["zoneEN"]="Hellfire Peninsula",["x"]=51.12,["y"]=60.3,["kind"]="npc",["entityID"]=21209}},["kind"]="npc",["entityID"]=21209},{[1]="Цель: Обожженная форма для отливки ключа",[2]="https://www.wowhead.com/tbc/ru/item=31252",["targets"]={},["kind"]="item",["entityID"]=31252},{[1]="Выданный предмет: Необожженная форма для отливки ключа",[2]="https://www.wowhead.com/tbc/ru/item=31251",["targets"]={},["kind"]="item",["entityID"]=31251}},["url"]="https://www.wowhead.com/tbc/quest=10764#comments",["startTargets"]={{["name"]="Болтуй (место поиска)",["zone"]="Полуостров Адского Пламени",["zoneEN"]="Hellfire Peninsula",["x"]=51.12,["y"]=60.3,["kind"]="npc",["entityID"]=21209}}}
G.questHelp[10883]={["steps"]={"После Кода Проклятия прочитайте письмо Кадгара и отправляйтесь к А’далу в Шаттрат.","Возьмите испытания наару: следующие задачи требуют героических подземелий."},["refs"]={{[1]="Начало: Кадгар",[2]="https://www.wowhead.com/wotlk/ru/npc=18166",["targets"]={{["name"]="Кадгар",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=54.75,["y"]=44.32,["kind"]="npc",["entityID"]=18166}},["kind"]="npc",["entityID"]=18166},{[1]="Сдача: А'дал",[2]="https://www.wowhead.com/wotlk/ru/npc=18481",["targets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}},["kind"]="npc",["entityID"]=18481}},["url"]="https://www.wowhead.com/wotlk/quest=10883#comments",["startTargets"]={{["name"]="Кадгар",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=54.75,["y"]=44.32,["kind"]="npc",["entityID"]=18166}}}
G.questHelp[10884]={["steps"]={"В героических Разрушенных залах за время около 55 минут доберитесь до Палача до казни пленников.","Победите Палача и заберите его топор для А’дала."},["refs"]={{[1]="Начало: А'дал",[2]="https://www.wowhead.com/wotlk/ru/npc=18481",["targets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}},["kind"]="npc",["entityID"]=18481},{[1]="Цель: Неиспользованный топор палача",[2]="https://www.wowhead.com/wotlk/ru/item=31716",["targets"]={},["kind"]="item",["entityID"]=31716},{[1]="Источник добычи: Палач из клана Изувеченной Длани",[2]="https://www.wowhead.com/wotlk/ru/npc=17301",["targets"]={},["kind"]="npc",["entityID"]=17301},{[1]="Источник добычи: Shattered Hand Executioner (1)",[2]="https://www.wowhead.com/wotlk/ru/npc=20585",["targets"]={},["kind"]="npc",["entityID"]=20585}},["url"]="https://www.wowhead.com/wotlk/quest=10884#comments",["startTargets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}}}
G.questHelp[10885]={["steps"]={"В героическом Паровом подземелье заберите трезубец Калитреша.","В героическом Тёмном лабиринте получите сущность Бормотуна. Оба предмета верните А’далу; обычная сложность не подходит."},["refs"]={{[1]="Начало: А'дал",[2]="https://www.wowhead.com/wotlk/ru/npc=18481",["targets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}},["kind"]="npc",["entityID"]=18481},{[1]="Цель: Трезубец Калитреша",[2]="https://www.wowhead.com/wotlk/ru/item=31721",["targets"]={},["kind"]="item",["entityID"]=31721},{[1]="Источник добычи: Warlord Kalithresh (1)",[2]="https://www.wowhead.com/wotlk/ru/npc=20633",["targets"]={},["kind"]="npc",["entityID"]=20633},{[1]="Цель: Сущность Бормотуна",[2]="https://www.wowhead.com/wotlk/ru/item=31722",["targets"]={},["kind"]="item",["entityID"]=31722},{[1]="Источник добычи: Murmur (1)",[2]="https://www.wowhead.com/wotlk/ru/npc=20657",["targets"]={},["kind"]="npc",["entityID"]=20657}},["url"]="https://www.wowhead.com/wotlk/quest=10885#comments",["startTargets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}}}
G.questHelp[10886]={["steps"]={"Пройдите финальное событие героического Аркатраца и защитите Миллхауса Манашторма.","Он должен выжить до победы над Скайриссом. Убийства босса без выполнения условия спасения недостаточно."},["refs"]={{[1]="Начало: А'дал",[2]="https://www.wowhead.com/wotlk/ru/npc=18481",["targets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}},["kind"]="npc",["entityID"]=18481}},["url"]="https://www.wowhead.com/wotlk/quest=10886#comments",["startTargets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}}}
G.questHelp[10888]={["steps"]={"С активным заданием победите Магтеридона и вернитесь к А’далу.","После сдачи Ключ Урагана помещается в связку ключей: искать его среди обычных предметов сумки не обязательно."},["refs"]={{[1]="Начало: А'дал",[2]="https://www.wowhead.com/tbc/ru/npc=18481",["targets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}},["kind"]="npc",["entityID"]=18481},{[1]="Цель: Магтеридон",[2]="https://www.wowhead.com/tbc/ru/npc=17257",["targets"]={{["name"]="Подход к подземелью: Магтеридон находится внутри",["zone"]="Полуостров Адского Пламени",["zoneEN"]="Hellfire Peninsula",["x"]=46.55,["y"]=52.81,["kind"]="entrance",["entityID"]=17257}},["kind"]="npc",["entityID"]=17257}},["url"]="https://www.wowhead.com/tbc/quest=10888#comments",["startTargets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}}}
G.questHelp[10901]={["steps"]={"Скар’тис находится в клетке после первого босса героического Узилища. Возьмите задание до походов к Груулу и Ночной погибели.","Получите предметы с обоих боссов и вернитесь к Скар’тису.","Награда — постоянный допуск в Змеиное святилище; отдельного предмета-ключа в сумке может не появиться."},["refs"]={{[1]="Начало: Скар'тис Еретик",[2]="https://www.wowhead.com/tbc/ru/npc=22421",["targets"]={{["name"]="Подход к подземелью: Скар'тис Еретик находится внутри",["zone"]="Зангартопь",["zoneEN"]="Zangarmarsh",["x"]=50.4,["y"]=40.9,["kind"]="entrance",["entityID"]=22421}},["kind"]="npc",["entityID"]=22421},{[1]="Цель: Печать земли",[2]="https://www.wowhead.com/tbc/ru/item=31750",["targets"]={{["name"]="Подход к подземелью: Груул Драконобой находится внутри",["zone"]="Острогорье",["zoneEN"]="Blade's Edge Mountains",["x"]=68.7,["y"]=24.3,["kind"]="entrance",["entityID"]=19044}},["kind"]="item",["entityID"]=31750},{[1]="Источник добычи: Груул Драконобой",[2]="https://www.wowhead.com/tbc/ru/npc=19044",["targets"]={{["name"]="Подход к подземелью: Груул Драконобой находится внутри",["zone"]="Острогорье",["zoneEN"]="Blade's Edge Mountains",["x"]=68.7,["y"]=24.3,["kind"]="entrance",["entityID"]=19044}},["kind"]="npc",["entityID"]=19044},{[1]="Цель: Печать огня",[2]="https://www.wowhead.com/tbc/ru/item=31751",["targets"]={{["name"]="Подход к подземелью: Ночная Погибель находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=17225}},["kind"]="item",["entityID"]=31751},{[1]="Источник добычи: Ночная Погибель",[2]="https://www.wowhead.com/tbc/ru/npc=17225",["targets"]={{["name"]="Подход к подземелью: Ночная Погибель находится внутри",["zone"]="Перевал Мертвого Ветра",["zoneEN"]="Deadwind Pass",["x"]=46.9,["y"]=74.7,["kind"]="entrance",["entityID"]=17225}},["kind"]="npc",["entityID"]=17225}},["url"]="https://www.wowhead.com/tbc/quest=10901#comments",["startTargets"]={{["name"]="По