G.questHelp[10944]={["steps"]={"После «Обещания Акамы» победите Каратресса и поговорите с вышедшим из клетки Олумом.","Возьмите его сообщение и вернитесь к Акаме в Клеть Стражницы."},["refs"]={{[1]="Начало: Провидец Олум",[2]="https://www.wowhead.com/wotlk/ru/npc=22820",["targets"]={{["name"]="Подход к подземелью: Провидец Олум находится внутри",["zone"]="Зангартопь",["zoneEN"]="Zangarmarsh",["x"]=50.4,["y"]=40.9,["kind"]="entrance",["entityID"]=22820}},["kind"]="npc",["entityID"]=22820},{[1]="Сдача: Акама",[2]="https://www.wowhead.com/wotlk/ru/npc=21700",["targets"]={{["name"]="Акама",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.11,["y"]=48.18,["kind"]="npc",["entityID"]=21700}},["kind"]="npc",["entityID"]=21700}},["url"]="https://www.wowhead.com/wotlk/quest=10944#comments",["startTargets"]={{["name"]="Подход к подземелью: Провидец Олум находится внутри",["zone"]="Зангартопь",["zoneEN"]="Zangarmarsh",["x"]=50.4,["y"]=40.9,["kind"]="entrance",["entityID"]=22820}},["serverNote"]="Выполняйте этот шаг на этапе 10: при раннем прохождении сервер может не выдать продолжение у Олума. Надёжного обхода уже возникшего отказа нет."}
G.questHelp[10946]={["steps"]={"Наденьте выданную маскировку Пеплоустов перед боем с Ал’аром в Крепости Бурь.","Победите Ал’ара под маскировкой и вернитесь к Акаме. Не заменяйте цель другим боссом этого рейда."},["refs"]={{[1]="Начало: Акама",[2]="https://www.wowhead.com/wotlk/ru/npc=21700",["targets"]={{["name"]="Акама",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.11,["y"]=48.18,["kind"]="npc",["entityID"]=21700}},["kind"]="npc",["entityID"]=21700},{[1]="Выданный предмет: Клобук Пеплоуста",[2]="https://www.wowhead.com/wotlk/ru/item=31946",["targets"]={},["kind"]="item",["entityID"]=31946}},["url"]="https://www.wowhead.com/wotlk/quest=10946#comments",["startTargets"]={{["name"]="Акама",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.11,["y"]=48.18,["kind"]="npc",["entityID"]=21700}}}
G.questHelp[10947]={["steps"]={"С активным заданием победите Лютого Хлада в битве за гору Хиджал.","Заберите с босса «Амулет из прошлого» и верните Акаме."},["refs"]={{[1]="Начало: Акама",[2]="https://www.wowhead.com/wotlk/ru/npc=21700",["targets"]={{["name"]="Акама",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.11,["y"]=48.18,["kind"]="npc",["entityID"]=21700}},["kind"]="npc",["entityID"]=21700},{[1]="Цель: Амулет из прошлого",[2]="https://www.wowhead.com/wotlk/ru/item=32459",["targets"]={},["kind"]="item",["entityID"]=32459},{[1]="Источник добычи: Лютый Хлад",[2]="https://www.wowhead.com/wotlk/ru/npc=17767",["targets"]={},["kind"]="npc",["entityID"]=17767}},["url"]="https://www.wowhead.com/wotlk/quest=10947#comments",["startTargets"]={{["name"]="Акама",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.11,["y"]=48.18,["kind"]="npc",["entityID"]=21700}}}
G.questHelp[10948]={["steps"]={"Отправляйтесь от Акамы к А’далу в Шаттрат и передайте план освобождения души.","Это этап разговора: ещё один рейдовый предмет для него не нужен."},["refs"]={{[1]="Начало: Акама",[2]="https://www.wowhead.com/wotlk/ru/npc=21700",["targets"]={{["name"]="Акама",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.11,["y"]=48.18,["kind"]="npc",["entityID"]=21700}},["kind"]="npc",["entityID"]=21700},{[1]="Сдача: А'дал",[2]="https://www.wowhead.com/wotlk/ru/npc=18481",["targets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}},["kind"]="npc",["entityID"]=18481}},["url"]="https://www.wowhead.com/wotlk/quest=10948#comments",["startTargets"]={{["name"]="Акама",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=58.11,["y"]=48.18,["kind"]="npc",["entityID"]=21700}}}
G.questHelp[10949]={["steps"]={"Найдите Зи’ри на дороге перед Чёрным храмом в Долине Призрачной Луны.","Поговорите с ним для подготовки отвлекающего манёвра."},["refs"]={{[1]="Начало: А'дал",[2]="https://www.wowhead.com/wotlk/ru/npc=18481",["targets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}},["kind"]="npc",["entityID"]=18481},{[1]="Сдача: Зи'ри",[2]="https://www.wowhead.com/wotlk/ru/npc=18528",["targets"]={{["name"]="Зи'ри",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=65.22,["y"]=43.96,["kind"]="npc",["entityID"]=18528}},["kind"]="npc",["entityID"]=18528}},["url"]="https://www.wowhead.com/wotlk/quest=10949#comments",["startTargets"]={{["name"]="А'дал",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=53.99,["y"]=44.75,["kind"]="npc",["entityID"]=18481}}}
G.questHelp[10985]={["steps"]={"Примите задание у Зи’ри, затем поговорите с ним ещё раз, чтобы запустить событие.","Дождитесь завершения сцены с Акамой; самостоятельно сражаться на этом шаге не нужно."},["refs"]={{[1]="Начало: Зи'ри",[2]="https://www.wowhead.com/wotlk/ru/npc=18528",["targets"]={{["name"]="Зи'ри",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=65.22,["y"]=43.96,["kind"]="npc",["entityID"]=18528}},["kind"]="npc",["entityID"]=18528}},["url"]="https://www.wowhead.com/wotlk/quest=10985#comments",["startTargets"]={{["name"]="Зи'ри",["zone"]="Долина Призрачной Луны",["zoneEN"]="Shadowmoon Valley",["x"]=65.22,["y"]=43.96,["kind"]="npc",["entityID"]=18528}}}
G.questHelp[11481]={["steps"]={"Отправляйтесь на остров Кель’Данас к лагерю Армии Расколотого Солнца.","Найдите Ларетора и продолжайте цепочку Террасы Магистров."},["refs"]={{[1]="Начало: Адуин Страж Света",[2]="https://www.wowhead.com/wotlk/ru/npc=18537",["targets"]={{["name"]="Адуин Страж Света (место поиска)",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=30.73,["y"]=34.62,["kind"]="npc",["entityID"]=18537}},["kind"]="npc",["entityID"]=18537},{[1]="Сдача: Экзарх Ларетор",[2]="https://www.wowhead.com/wotlk/ru/npc=24813",["targets"]={{["name"]="Экзарх Ларетор",["zone"]="Остров Кель'Данас",["zoneEN"]="Isle of Quel'Danas",["x"]=47.42,["y"]=30.74,["kind"]="npc",["entityID"]=24813}},["kind"]="npc",["entityID"]=24813}},["url"]="https://www.wowhead.com/wotlk/quest=11481#comments",["startTargets"]={{["name"]="Адуин Страж Света (место поиска)",["zone"]="Шаттрат",["zoneEN"]="Shattrath City",["x"]=30.73,["y"]=34.62,["kind"]="npc",["entityID"]=18537}}}
G.questHelp[11488]={["steps"]={"Войдите в обычную Террасу Магистров и найдите Тирита на пути через подземелье.","Поговорите с ним: следующее поручение ведёт к сфере на балконе."},["refs"]={{[1]="Начало: Экзарх Ларетор",[2]="https://www.wowhead.com/wotlk/ru/npc=24813",["targets"]={{["name"]="Экзарх Ларетор",["zone"]="Остров Кель'Данас",["zoneEN"]="Isle of Quel'Danas",["x"]=47.42,["y"]=30.74,["kind"]="npc",["entityID"]=24813}},["kind"]="npc",["entityID"]=24813},{[1]="Сдача: Тирит",[2]="https://www.wowhead.com/wotlk/ru/npc=24822",["targets"]={{["name"]="Подход к подземелью: Тирит находится внутри",["zone"]="Остров Кель'Данас",["zoneEN"]="Isle of Quel'Danas",["x"]=61.2,["y"]=30.9,["kind"]="entrance",["entityID"]=24822}},["kind"]="npc",["entityID"]=24822}},["url"]="https://www.wowhead.com/wotlk/quest=11488#comments",["startTargets"]={{["name"]="Экзарх Ларетор",["zone"]="Остров Кель'Данас",["zoneEN"]="Isle of Quel'Danas",["x"]=47.42,["y"]=30.74,["kind"]="npc",["entityID"]=24813}}}
G.questHelp[11490]={["steps"]={"На балконе Террасы Магистров взаимодействуйте со сферой наблюдения.","Дождитесь видения и поговорите с появившимся Калесгосом для продолжения."},["refs"]={{[1]="Начало: Тирит",[2]="https://www.wowhead.com/wotlk/ru/npc=24822",["targets"]={{["name"]="Подход к подземелью: Тирит находится внутри",["zone"]="Остров Кель'Данас",["zoneEN"]="Isle of Quel'Danas",["x"]=61.2,["y"]=30.9,["kind"]="entrance",["entityID"]=24822}},["kind"]="npc",["entityID"]=24822},{[1]="Сдача: Калесгос",[2]="https://www.wowhead.com/wotlk/ru/npc=24848",["targets"]={{["name"]="Подход к подземелью: Калесгос находится внутри",["zone"]="Остров Кель'Данас",["zoneEN"]="Isle of Quel'Danas",["x"]=61.2,["y"]=30.9,["kind"]="entrance",["entityID"]=24848}},["kind"]="npc",["entityID"]=24848},{[1]="Цель: Magisters' Terrace - Scryer Quest Bunny",[2]="https://www.wowhead.com/wotlk/ru/npc=25042",["targets"]={{["name"]="Подход к подземелью: Magisters' Terrace - Scryer Quest Bunny находится внутри",["zone"]="Остров Кель'Данас",["zoneEN"]="Isle of Quel'Danas",["x"]=61.2,["y"]=30.9,["kind"]="entrance",["entityID"]=25042}},["kind"]="npc",["entityID"]=25042}},["url"]="https://www.wowhead.com/wotlk/quest=11490#comments",["startTargets"]={{["name"]="Подход к подземелью: Тирит находится внутри",["zone"]="Остров Кель'Данас",["zoneEN"]="Isle of Quel'Danas",["x"]=61.2,["y"]=30.9,["kind"]="entrance",["entityID"]=24822}}}
G.questHelp[11492]={["steps"]={"Победите Кель’таса в Террасе Магистров и заберите его голову.","Вернитесь к Ларетору на острове. Это финал цепочки допуска в героическую Террасу Магистров, а не бой с Кель’тасом в Крепости Бурь."},["refs"]={{[1]="Начало: Калесгос",[2]="https://www.wowhead.com/wotlk/ru/npc=24848",["targets"]={{["name"]="Подход к подземелью: Калесгос находится внутри",["zone"]="Остров Кель'Данас",["zoneEN"]="Isle of Quel'Danas",["x"]=61.2,["y"]=30.9,["kind"]="entrance",["entityID"]=24848}},["kind"]="npc",["entityID"]=24848},{[1]="Сдача: Экзарх Ларетор",[2]="https://www.wowhead.com/wotlk/ru/npc=24813",["targets"]={{["name"]="Экзарх Ларетор",["zone"]="Остров Кель'Данас",["zoneEN"]="Isle of Quel'Danas",["x"]=47.42,["y"]=30.74,["kind"]="npc",["entityID"]=24813}},["kind"]="npc",["entityID"]=24813},{[1]="Цель: Голова Кель'таса",[2]="https://www.wowhead.com/wotlk/ru/item=34157",["targets"]={{["name"]="Подход к подземелью: Кель'тас Солнечный Скиталец находится внутри",["zone"]="Остров Кель'Данас",["zoneEN"]="Isle of Quel'Danas",["x"]=61.2,["y"]=30.9,["kind"]="entrance",["entityID"]=24664}},["kind"]="item",["entityID"]=34157},{[1]="Источник добычи: Кель'тас Солнечный Скиталец",[2]="https://www.wowhead.com/wotlk/ru/npc=24664",["targets"]={{["name"]="Подход к подземелью: Кель'тас Солнечный Скиталец находится внутри",["zone"]="Остров Кель'Данас",["zoneEN"]="Isle of Quel'Danas",["x"]=61.2,["y"]=30.9,["kind"]="entrance",["entityID"]=24664}},["kind"]="npc",["entityID"]=24664},{[1]="Источник добычи: Kael'thas Sunstrider (1)",[2]="https://www.wowhead.com/wotlk/ru/npc=24857",["targets"]={},["kind"]="npc",["entityID"]=24857}},["url"]="https://www.wowhead.com/wotlk/quest=11492#comments",["startTargets"]={{["name"]="Подход к подземелью: Калесгос находится внутри",["zone"]="Остров Кель'Данас",["zoneEN"]="Isle of Quel'Danas",["x"]=61.2,["y"]=30.9,["kind"]="entrance",["entityID"]=24848}}}
G.questHelp[13372]={["steps"]={"Победите Сапфирона в Наксрамасе на 10 игроков и получите предмет, начинающий задание.","Используйте его и отнесите ключ Алекстразе. Для открытия Ока Вечности достаточно ключа хотя бы у одного участника."},["refs"]={{[1]="Начало: Ключ к Радужному Средоточию",[2]="https://www.wowhead.com/wotlk/ru/item=44569",["targets"]={{["name"]="Подход к подземелью: Сапфирон находится внутри",["zone"]="Драконий Погост",["zoneEN"]="Dragonblight",["x"]=87.4,["y"]=51.1,["kind"]="entrance",["entityID"]=15989}},["kind"]="item",["entityID"]=44569},{[1]="Источник добычи: Сапфирон",[2]="https://www.wowhead.com/wotlk/ru/npc=15989",["targets"]={{["name"]="Подход к подземелью: Сапфирон находится внутри",["zone"]="Драконий Погост",["zoneEN"]="Dragonblight",["x"]=87.4,["y"]=51.1,["kind"]="entrance",["entityID"]=15989}},["kind"]="npc",["entityID"]=15989},{[1]="Сдача: Алекстраза Хранительница Жизни",[2]="https://www.wowhead.com/wotlk/ru/npc=26917",["targets"]={{["name"]="Алекстраза Хранительница Жизни",["zone"]="Драконий Погост",["zoneEN"]="Dragonblight",["x"]=59.83,["y"]=54.66,["kind"]="npc",["entityID"]=26917}},["kind"]="npc",["entityID"]=26917}},["url"]="https://www.wowhead.com/wotlk/quest=13372#comments",["startTargets"]={{["name"]="Подход к подземелью: Сапфирон находится внутри",["zone"]="Драконий Погост",["zoneEN"]="Dragonblight",["x"]=87.4,["y"]=51.1,["kind"]="entrance",["entityID"]=15989}}}
G.questHelp[13375]={["steps"]={"Получите героический ключ с Сапфирона в Наксрамасе на 25 игроков и используйте предмет для задания.","Передайте его Алекстразе. Этот вариант открывает Око Вечности на 25 игроков."},["refs"]={{[1]="Начало: Ключ для доступа к героическому режиму Радужного Средоточия",[2]="https://www.wowhead.com/wotlk/ru/item=44577",["targets"]={{["name"]="Подход к подземелью: Sapphiron (1) находится внутри",["zone"]="Драконий Погост",["zoneEN"]="Dragonblight",["x"]=87.4,["y"]=51.1,["kind"]="entrance",["entityID"]=29991}},["kind"]="item",["entityID"]=44577},{[1]="Источник добычи: Sapphiron (1)",[2]="https://www.wowhead.com/wotlk/ru/npc=29991",["targets"]={{["name"]="Подход к подземелью: Sapphiron (1) находится внутри",["zone"]="Драконий Погост",["zoneEN"]="Dragonblight",["x"]=87.4,["y"]=51.1,["kind"]="entrance",["entityID"]=29991}},["kind"]="npc",["entityID"]=29991},{[1]="Сдача: Алекстраза Хранительница Жизни",[2]="https://www.wowhead.com/wotlk/ru/npc=26917",["targets"]={{["name"]="Алекстраза Хранительница Жизни",["zone"]="Драконий Погост",["zoneEN"]="Dragonblight",["x"]=59.83,["y"]=54.66,["kind"]="npc",["entityID"]=26917}},["kind"]="npc",["entityID"]=26917}},["url"]="https://www.wowhead.com/wotlk/quest=13375#comments",["startTargets"]={{["name"]="Подход к подземелью: Sapphiron (1) находится внутри",["zone"]="Драконий Погост",["zoneEN"]="Dragonblight",["x"]=87.4,["y"]=51.1,["kind"]="entrance",["entityID"]=29991}}}
